const ALL_QUESTIONS = [
// ========== EXAM A: Questions 1-40 ==========
{id:"A-1",exam:"A",lo:"FL-1.1.1",kl:"K1",pts:1,multi:false,chapter:1,
q:"Laquelle des affirmations suivantes decrit un objectif de test valide ?",
options:["Prouver qu'il n'y a pas de defauts non corriges dans le systeme sous test","Prouver qu'il n'y aura pas de defaillances apres la mise en production du systeme","Reduire le niveau de risque de l'objet de test et renforcer la confiance dans le niveau de qualite","Verifier qu'il n'existe aucune combinaison d'entrees non testee"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 Les tests trouvent des defauts et des defaillances, ce qui reduit le niveau de risque et renforce la confiance dans la qualite de l\'objet de test.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Il est impossible de prouver qu\'il n\'y a plus aucun defaut dans le systeme (voir principe de test n\u00b01).<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Il est impossible de garantir l\'absence de defaillances apres la mise en production (voir principe n\u00b07).<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Il est impossible de tester toutes les combinaisons d\'entrees (voir principe n\u00b02 : les tests exhaustifs sont impossibles)."},

{id:"A-2",exam:"A",lo:"FL-1.2.1",kl:"K2",pts:1,multi:false,chapter:1,
q:"Laquelle des options suivantes montre un exemple d'activites de test contribuant au succes ?",
options:["L'implication des testeurs dans differentes activites du SDLC permet de detecter des defauts dans les produits d'activite","Les testeurs evitent de deranger les developpeurs pendant le codage pour qu'ils ecrivent un meilleur code","La collaboration des testeurs avec les utilisateurs finaux aide a ameliorer la qualite des rapports de defauts pendant les tests d'integration et systeme","Les testeurs certifies concevront de bien meilleurs cas de test que les testeurs non certifies"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 Il est important que les testeurs soient impliques des le debut du SDLC. Cela augmente la comprehension des decisions de conception et permet de detecter les defauts tot.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les developpeurs et les testeurs ont tout interet a mieux comprendre le travail de l\'autre ; eviter les developpeurs n\'est pas une bonne pratique.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les utilisateurs finaux n\'aident pas les testeurs a ameliorer la qualite des rapports de defauts, et ils ne participent generalement pas aux niveaux de test bas comme les tests d\'integration.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Etre certifie ne signifie pas automatiquement que le testeur sera meilleur en conception de tests."},

{id:"A-3",exam:"A",lo:"FL-1.3.1",kl:"K2",pts:1,multi:false,chapter:1,
q:"Vous avez ete assigne comme testeur dans une equipe produisant un nouveau systeme de maniere incrementale. Vous avez remarque qu'aucune modification n'a ete apportee aux cas de test de regression existants depuis plusieurs iterations et qu'aucun nouveau defaut de regression n'a ete identifie. Votre responsable est content, mais pas vous. Quel principe de test explique votre scepticisme ?",
options:["L'usure des tests","L'illusion de l'absence de defauts","Les defauts se regroupent","Les tests exhaustifs sont impossibles"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 Ce principe signifie que si les memes tests sont repetes encore et encore, ils finissent par ne plus trouver de nouveaux defauts. C\'est probablement pour cela que tous les tests passent dans cette version.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 L\'illusion de l\'absence de defauts concerne la croyance erronee que trouver et corriger beaucoup de defauts garantira le succes du systeme.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Le regroupement des defauts indique qu\'un petit nombre de composants contient generalement la majorite des defauts.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Ce principe dit que tester toutes les combinaisons d\'entrees et de preconditions n\'est pas faisable."},

{id:"A-4",exam:"A",lo:"FL-1.4.1",kl:"K2",pts:1,multi:false,chapter:1,
q:"Vous travaillez dans une equipe qui developpe une application mobile de commande de nourriture. Dans l'iteration actuelle, l'equipe a decide d'implementer la fonctionnalite de paiement.\nQuelle activite fait partie de l'analyse de test ?",
options:["Estimer que le test de l'integration avec le service de paiement prendra 8 jours-personne","Decider que l'equipe devrait tester s'il est possible de partager correctement le paiement entre plusieurs utilisateurs","Utiliser l'analyse des valeurs limites (BVA) pour deriver les donnees de test","Analyser la difference entre le resultat reel et attendu apres l'execution d'un cas de test"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 C\'est un exemple de definition de conditions de test, qui fait partie de l\'analyse de test.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Estimer l\'effort de test fait partie de la planification des tests, pas de l\'analyse.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Utiliser des techniques de test pour deriver des elements de couverture fait partie de la conception de test.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Analyser la difference entre le resultat reel et attendu fait partie de l\'execution des tests (rapport de defaut)."},

{id:"A-5",exam:"A",lo:"FL-1.4.2",kl:"K2",pts:1,multi:false,chapter:1,
q:"Lesquels des facteurs suivants ont une influence SIGNIFICATIVE sur l'approche de test ?\ni. Le SDLC\nii. Le nombre de defauts detectes dans les projets precedents\niii. Les risques produit identifies\niv. De nouvelles exigences reglementaires imposant des tests boite blanche formels\nv. La configuration de l'environnement de test",
options:["i, ii ont une influence significative","i, iii, iv ont une influence significative","ii, iv, v ont une influence significative","iii, v ont une influence significative"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Les affirmations i (le SDLC influence l\'approche de test), iii (les risques produit identifies sont un facteur important) et iv (les exigences reglementaires sont des facteurs importants) sont vraies.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 La combinaison i, ii, iv est incorrecte car ii (nombre de defauts des projets precedents) n\'est pas un facteur aussi significatif.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 La combinaison i, iii, v est incorrecte car v (l\'environnement de test) n\'a pas d\'influence significative sur l\'approche de test.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 La combinaison ii, iii, v est incorrecte car ii et v ne sont pas des facteurs significatifs."},

{id:"A-6",exam:"A",lo:"FL-1.4.5",kl:"K2",pts:1,multi:true,chapter:1,
q:"Lesquelles des taches suivantes appartiennent PRINCIPALEMENT a un role de testeur ?",
options:["Configurer les environnements de test","Maintenir le backlog produit","Concevoir des solutions pour de nouvelles exigences","Creer le plan de test","Analyser la base de test"],
correct:[0,4],
justification:"<strong>\u2713 a, e) Correct</strong> \u2014 a) Configurer les environnements de test est fait par les testeurs. e) Analyser la base de test est une tache technique des testeurs dans le cadre de l\'analyse de test.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Le backlog produit est construit et maintenu par le product owner.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Cette tache est realisee par l\'equipe de developpement.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 C\'est un role managerial, pas une tache de testeur."},

{id:"A-7",exam:"A",lo:"FL-1.5.1",kl:"K2",pts:1,multi:false,chapter:1,
q:"Lesquelles des competences suivantes (i-v) sont les competences les PLUS importantes d'un testeur ?\ni. Avoir des connaissances du domaine\nii. Creer une vision produit\niii. Etre un bon joueur d'equipe\niv. Planifier et organiser le travail de l'equipe\nv. Pensee critique",
options:["ii et iv sont importantes","i, iii et v sont importantes","i, ii et v sont importantes","iii et iv sont importantes"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Les connaissances du domaine, etre un bon joueur d\'equipe et la pensee critique (i, iii, v) sont les competences les plus importantes d\'un testeur.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 La combinaison i, ii, iv est incorrecte car ii (definir les exigences) est une tache de l\'analyste metier et iv (planifier le travail de l\'equipe) est une tache du test manager.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 La combinaison ii, iii, v est incorrecte car ii n\'est pas une competence de testeur.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 La combinaison ii, iv, v est incorrecte car ii et iv ne sont pas des competences de testeur."},

{id:"A-8",exam:"A",lo:"FL-1.5.2",kl:"K1",pts:1,multi:false,chapter:1,
q:"Comment l'approche equipe entiere se manifeste-t-elle dans les interactions entre testeurs et representants metier ?",
options:["Les representants metier decident des approches d'automatisation des tests","Les testeurs aident les representants metier a definir une strategie de test","Les representants metier ne font pas partie de l'approche equipe entiere","Les testeurs aident les representants metier a creer des tests d'acceptation adaptes"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Les testeurs travaillent en etroite collaboration avec les representants metier pour s\'assurer que les niveaux de qualite souhaites sont atteints, en les aidant a creer des tests d\'acceptation adaptes.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 L\'approche d\'automatisation des tests est definie par les testeurs avec l\'aide des developpeurs et des representants metier, pas par le testeur seul.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 La strategie de test est decidee en collaboration avec les developpeurs, pas par le testeur seul.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les testeurs, developpeurs et representants metier font tous partie de l\'approche equipe entiere ; ce n\'est pas specifique au role du testeur."},

{id:"A-9",exam:"A",lo:"FL-2.1.2",kl:"K1",pts:1,multi:false,chapter:2,
q:"Considerez la regle suivante : 'pour chaque activite SDLC, il existe une activite de test correspondante'. Dans quels modeles SDLC cette regle s'applique-t-elle ?",
options:["Uniquement dans les modeles de developpement sequentiel","Uniquement dans les modeles de developpement iteratif","Uniquement dans les modeles iteratifs et incrementaux","Dans les modeles sequentiels, incrementaux et iteratifs"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Cette regle s\'applique a tous les modeles SDLC : pour chaque activite de developpement, il existe une activite de test correspondante.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Ce n\'est pas le bon principe SDLC.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Ce n\'est pas le bon principe SDLC.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Ce n\'est pas le bon principe SDLC."},

{id:"A-10",exam:"A",lo:"FL-2.1.3",kl:"K1",pts:1,multi:false,chapter:2,
q:"Laquelle des affirmations suivantes decrit le MIEUX l'approche ATDD (Acceptance Test-Driven Development) ?",
options:["En ATDD, les criteres d'acceptation sont typiquement crees au format given/when/then","En ATDD, les cas de test sont principalement crees au niveau des tests de composants et sont orientes code","En ATDD, les tests sont crees a partir des criteres d'acceptation pour guider le developpement du logiciel associe","En ATDD, les tests sont bases sur le comportement souhaite du logiciel, ce qui les rend plus faciles a comprendre"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 En ATDD, les tests sont ecrits a partir des criteres d\'acceptation dans le cadre du processus de conception.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Cela est plus souvent utilise dans le developpement pilote par le comportement (BDD).<br><br><strong>\u2717 b) Incorrect</strong> \u2014 C\'est la description du developpement pilote par les tests (TDD), pas de l\'ATDD.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Cela est utilise dans le BDD, pas dans l\'ATDD."},

{id:"A-11",exam:"A",lo:"FL-2.1.5",kl:"K2",pts:1,multi:false,chapter:2,
q:"Lequel des elements suivants n'est PAS un exemple de l'approche shift-left ?",
options:["Reviser les exigences utilisateur avant qu'elles ne soient formellement acceptees par les parties prenantes","Ecrire un test de composant avant que le code correspondant ne soit ecrit","Executer un test d'efficacite de performance pour un composant pendant les tests de composants","Ecrire un script de test avant de mettre en place le processus de gestion de configuration"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Les scripts de test doivent etre sous gestion de configuration, donc il n\'a pas de sens de creer les scripts avant que ce processus soit mis en place. Ce n\'est PAS un exemple de shift-left.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 La revue precoce est un exemple de l\'approche shift-left.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Le TDD est un exemple de l\'approche shift-left.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les tests non fonctionnels precoces sont un exemple de l\'approche shift-left."},

{id:"A-12",exam:"A",lo:"FL-2.1.6",kl:"K2",pts:1,multi:false,chapter:2,
q:"Quel argument utiliseriez-vous pour convaincre votre responsable d'organiser des retrospectives a la fin de chaque cycle de release ?",
options:["Les retrospectives sont tres populaires actuellement et les clients apprecieraient que nous les ajoutions","Les retrospectives economiseront de l'argent car sans elles, les utilisateurs finaux ne fournissent pas de feedback immediat","Les faiblesses de processus identifiees lors de la retrospective peuvent etre analysees et servir de liste d'actions pour l'amelioration continue","Les retrospectives embrassent cinq valeurs dont le courage et le respect, essentiels pour l'amelioration continue"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 Les retrospectives regulieres, lorsqu\'elles sont suivies d\'actions appropriees, sont essentielles a l\'amelioration continue du developpement et des tests.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Les retrospectives sont plus utiles pour identifier des opportunites d\'amelioration et ont peu d\'importance pour les clients.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les retrospectives ne visent pas a collecter du feedback sur le produit mais sur le processus. De plus, elles sont internes a l\'equipe et ne devraient pas inclure les utilisateurs finaux.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Le courage et le respect sont des valeurs de l\'Extreme Programming et ne sont pas etroitement lies aux retrospectives."},

{id:"A-13",exam:"A",lo:"FL-2.2.1",kl:"K2",pts:1,multi:false,chapter:2,
q:"Quels types de defaillances (1-4) correspondent le MIEUX a quels niveaux de test (A-D) ?\n1. Defaillances dans le comportement du systeme deviant des besoins metier\n2. Defaillances dans la communication entre composants\n3. Defaillances dans la logique du code\n4. Defaillances dans les regles metier mal implementees\nA. Test de composant  B. Test d'integration de composants  C. Test systeme  D. Test d'acceptation",
options:["1D, 2B, 3A, 4C","1D, 2B, 3C, 4A","1B, 2A, 3D, 4C","1C, 2B, 3A, 4D"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 La base de test pour les tests d\'acceptation est les besoins metier de l\'utilisateur (1D), la communication entre composants est testee lors des tests d\'integration de composants (2B), les defauts de logique sont trouves lors des tests de composants (3A), les regles metier sont la base de test pour les tests systeme (4C).<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les appariements proposes ne correspondent pas aux associations correctes.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les appariements proposes ne correspondent pas aux associations correctes.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les appariements proposes ne correspondent pas aux associations correctes."},

{id:"A-14",exam:"A",lo:"FL-2.2.3",kl:"K2",pts:1,multi:false,chapter:2,
q:"Vous testez une user story avec trois criteres d'acceptation: AC1, AC2 et AC3. AC1 est couvert par TC1, AC2 par TC2 et AC3 par TC3. L'historique d'execution sur trois versions consecutives :\nExec1: TC1=Echec, TC2=Reussi, TC3=Echec\nExec2: TC1=Reussi, TC2=Echec, TC3=Echec\nExec3: TC1=Reussi, TC2=Reussi, TC3=Reussi\nLesquels des tests ci-dessus sont executes comme tests de regression ?",
options:["Uniquement 4, 7, 8, 9","Uniquement 5, 7","Uniquement 4, 6, 8, 9","Uniquement 5, 6"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 TC1 et TC3 ont echoue a l\'execution 1, donc les tests (4) et (6) sont des tests de confirmation. TC2 et TC3 ont echoue a l\'execution 2, donc les tests (8) et (9) sont aussi des tests de confirmation. TC2 a reussi a l\'execution 1 donc le test (5) est un test de regression. TC1 a reussi a l\'execution 2 donc le test (7) est un test de regression.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Les tests de confirmation et de regression ne sont pas correctement identifies.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les tests de confirmation et de regression ne sont pas correctement identifies.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les tests de confirmation et de regression ne sont pas correctement identifies."},

{id:"A-15",exam:"A",lo:"FL-3.1.2",kl:"K2",pts:1,multi:false,chapter:3,
q:"Lequel des elements suivants n'est PAS un avantage du test statique ?",
options:["Avoir une gestion des defauts moins couteuse grace a la facilite de detection tardive des defauts dans le SDLC","Corriger les defauts trouves lors du test statique est generalement beaucoup moins couteux que ceux trouves lors du test dynamique","Trouver des defauts de codage qui n'auraient pas ete trouves par le seul test dynamique","Detecter des lacunes et des incoherences dans les exigences"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 La gestion des defauts n\'est pas moins couteuse avec les tests statiques. Trouver et corriger les defauts plus tard dans le SDLC est plus couteux.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 C\'est un avantage du test statique (detection precoce des defauts).<br><br><strong>\u2717 c) Incorrect</strong> \u2014 C\'est un avantage du test statique.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 C\'est un avantage du test statique."},

{id:"A-16",exam:"A",lo:"FL-3.2.1",kl:"K1",pts:1,multi:false,chapter:3,
q:"Lequel des elements suivants est un avantage du feedback precoce et frequent ?",
options:["Il ameliore le processus de test pour les projets futurs","Il force les clients a prioriser leurs exigences en fonction des risques convenus","Il fournit une mesure de la qualite des changements","Il aide a eviter les malentendus sur les exigences"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Un feedback precoce et frequent peut prevenir les malentendus sur les exigences.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le feedback peut ameliorer le processus de test, mais s\'il s\'agit uniquement d\'ameliorer les futurs projets, il n\'a pas besoin d\'etre precoce ou frequent.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Le feedback n\'est pas utilise pour prioriser les exigences.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Il n\'existe pas de methode unique recommandee pour mesurer la qualite des changements, et ce n\'est pas un avantage du feedback precoce mentionne dans la section 3.2.1."},

{id:"A-17",exam:"A",lo:"FL-3.2.4",kl:"K2",pts:1,multi:false,chapter:3,
q:"Les revues utilisees dans votre organisation ont les attributs suivants :\n- Il y a un role de scribe\n- L'objectif principal est d'evaluer la qualite\n- La reunion est dirigee par l'auteur du produit d'activite\n- Il y a une preparation individuelle\n- Un rapport de revue est produit\nQuel type de revue est le PLUS probablement utilise ?",
options:["Revue informelle","Walkthrough","Revue technique","Inspection"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Les attributs (specifies pour les walkthroughs, revues techniques et inspections ; l\'objectif d\'evaluer la qualite ; l\'auteur comme moderateur est autorise) indiquent un walkthrough.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Les revues informelles ne sont pas specifiees avec ces attributs formels.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les revues techniques n\'autorisent generalement pas l\'auteur comme moderateur.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les inspections n\'autorisent pas l\'auteur comme moderateur."},

{id:"A-18",exam:"A",lo:"FL-3.2.5",kl:"K1",pts:1,multi:false,chapter:3,
q:"Laquelle de ces affirmations n'est PAS un facteur contribuant au succes des revues ?",
options:["Les participants doivent consacrer un temps adequat a la revue","Diviser les grands produits d'activite en petites parties","Les participants doivent eviter les comportements indiquant l'ennui ou l'hostilite","Les defaillances trouvees doivent etre reconnues et traitees objectivement"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Lors des revues, on peut trouver des defauts, pas des defaillances. Trouver des defaillances n\'est pas un facteur de succes des revues.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Allouer un temps adequat pour la preparation individuelle est un facteur de succes des revues.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Decouper les produits de travail en petites parties adequates est un facteur de succes.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Eviter les comportements indiquant l\'ennui ou l\'exasperation est un facteur de succes."},

{id:"A-19",exam:"A",lo:"FL-4.1.1",kl:"K2",pts:1,multi:false,chapter:4,
q:"Laquelle des affirmations suivantes est une caracteristique des techniques de test basees sur l'experience ?",
options:["Les cas de test sont crees a partir d'informations de conception detaillees","Les elements testes dans la section de code d'interface sont utilises pour mesurer la couverture","Les techniques de test s'appuient fortement sur la connaissance du testeur du logiciel et du domaine metier","Les cas de test sont utilises pour identifier les ecarts par rapport aux exigences"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 C\'est une caracteristique commune des techniques de test basees sur l\'experience : les connaissances et l\'experience de l\'utilisation prevue du logiciel, son environnement et les defauts probables sont utilises pour definir les tests.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 C\'est une caracteristique des techniques de test en boite blanche (derivation a partir du code, architecture, conception detaillee).<br><br><strong>\u2717 b) Incorrect</strong> \u2014 C\'est une caracteristique des techniques en boite blanche (couverture mesuree sur la structure selectionnee).<br><br><strong>\u2717 d) Incorrect</strong> \u2014 C\'est une caracteristique des techniques en boite noire (detection des ecarts entre les exigences et l\'implementation)."},

{id:"A-20",exam:"A",lo:"FL-4.2.1",kl:"K3",pts:1,multi:false,chapter:4,
q:"Vous testez un formulaire de recherche d'appartement simplifie avec deux criteres :\n- Etage (3 options : rez-de-chaussee, premier etage, deuxieme etage ou plus)\n- Type de jardin (3 options : pas de jardin, petit jardin, grand jardin)\nChaque appartement au rez-de-chaussee a un jardin, les appartements aux etages superieurs n'en ont pas.\nQuel est le nombre minimal de cas de test pour atteindre 100% de couverture EP pour les partitions valides ?",
options:["3","4","5","6"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 \"Petit jardin\" et \"grand jardin\" ne vont qu\'avec \"rez-de-chaussee\", donc il faut 2 cas de test avec \"rez-de-chaussee\". Il faut 2 cas supplementaires pour couvrir les autres partitions d\'etage. Total = 4 cas de test.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 3 cas de test ne suffisent pas pour couvrir toutes les combinaisons de partitions valides.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 5 cas de test sont plus que le minimum necessaire.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 6 cas de test sont plus que le minimum necessaire."},

{id:"A-21",exam:"A",lo:"FL-4.2.2",kl:"K3",pts:1,multi:false,chapter:4,
q:"Vous testez un systeme qui attribue une note finale basee sur le resultat :\n0-50: echec, 51-60: passable, 61-70: satisfaisant, 71-80: bien, 81-90: tres bien, 91-100: excellent\nCas de test : TC1=91, TC2=50, TC3=81, TC4=60, TC5=70, TC6=80\nQuelle est la couverture BVA 2 valeurs pour le resultat final ?",
options:["50%","60%","33.3%","100%"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 Il y a 12 valeurs limites pour les resultats finaux : 0, 50, 51, 60, 61, 70, 71, 80, 81, 90, 91 et 100. Les cas de test couvrent 6 d\'entre elles (TC1-91, TC2-50, TC3-81, TC4-60, TC5-70, TC7-51). Donc 6/12 = 50%.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Le calcul ne donne pas ce pourcentage.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Le calcul ne donne pas ce pourcentage.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Le calcul ne donne pas ce pourcentage."},

{id:"A-22",exam:"A",lo:"FL-4.2.3",kl:"K3",pts:1,multi:false,chapter:4,
scenario:'Votre magasin de location de velos favori a un systeme CRM. Fonctionnalites :<br>- Tout le monde peut louer, les membres ont 20% de remise<br>- Si le delai de retour est depasse, la remise est annulee<br>- Apres 15 locations, les membres recoivent un T-Shirt<br><br><table class="q-table"><tr><th>Conditions</th><th>R1</th><th>R2</th><th>R3</th><th>R4</th><th>R5</th><th>R6</th><th>R7</th><th>R8</th></tr><tr><td>Membre</td><td>V</td><td>V</td><td>V</td><td>V</td><td>F</td><td>F</td><td>F</td><td>F</td></tr><tr><td>Retard</td><td>V</td><td>F</td><td>V</td><td>F</td><td>V</td><td>F</td><td>F</td><td>V</td></tr><tr><td>15e location</td><td>F</td><td>F</td><td>V</td><td>V</td><td>F</td><td>F</td><td>V</td><td>V</td></tr><tr><th>Actions</th><th></th><th></th><th></th><th></th><th></th><th></th><th></th><th></th></tr><tr><td>Remise 20%</td><td></td><td>X</td><td></td><td>X</td><td></td><td></td><td></td><td></td></tr><tr><td>T-Shirt</td><td></td><td></td><td>X</td><td>X</td><td></td><td></td><td>X</td><td></td></tr></table>',
q:"Quelle regle decrit une situation impossible ?",
options:["R4","R2","R6","R8"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Pas de reduction car c\'est un non-membre qui a aussi manque une echeance, mais seuls les membres peuvent recevoir un T-shirt cadeau. L\'action n\'est donc pas correcte.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Un membre sans echeance manquee peut obtenir une reduction ET un T-shirt cadeau apres 15 locations de velo.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Un membre sans echeance manquee peut obtenir une reduction mais pas de T-shirt tant qu\'il n\'a pas loue 15 fois.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les non-membres ne peuvent pas obtenir de reduction, meme s\'ils n\'ont pas manque d\'echeance."},

{id:"A-23",exam:"A",lo:"FL-4.2.4",kl:"K3",pts:1,multi:false,chapter:4,
scenario:'Diagramme de transition d\'etats du systeme :<br><br><svg viewBox="0 0 520 260" xmlns="http://www.w3.org/2000/svg" style="max-width:520px;font-family:sans-serif;font-size:12px"><rect x="0" y="100" width="60" height="36" rx="6" fill="#1e3a5f" stroke="#1e3a5f"/><text x="30" y="123" text-anchor="middle" fill="white" font-weight="bold">INIT</text><rect x="110" y="100" width="60" height="36" rx="6" fill="#2563eb" stroke="#1e3a5f"/><text x="140" y="123" text-anchor="middle" fill="white" font-weight="bold">S1</text><rect x="220" y="100" width="60" height="36" rx="6" fill="#2563eb" stroke="#1e3a5f"/><text x="250" y="123" text-anchor="middle" fill="white" font-weight="bold">S2</text><rect x="330" y="100" width="60" height="36" rx="6" fill="#2563eb" stroke="#1e3a5f"/><text x="360" y="123" text-anchor="middle" fill="white" font-weight="bold">S3</text><rect x="440" y="100" width="60" height="36" rx="6" fill="#16a34a" stroke="#166534"/><text x="470" y="123" text-anchor="middle" fill="white" font-weight="bold">OFF</text><line x1="60" y1="118" x2="105" y2="118" stroke="#334155" stroke-width="2" marker-end="url(#ah)"/><line x1="170" y1="118" x2="215" y2="118" stroke="#334155" stroke-width="2" marker-end="url(#ah)"/><line x1="280" y1="118" x2="325" y2="118" stroke="#334155" stroke-width="2" marker-end="url(#ah)"/><line x1="390" y1="118" x2="435" y2="118" stroke="#334155" stroke-width="2" marker-end="url(#ah)"/><path d="M155 100 Q155 40 470 40 Q480 40 480 100" fill="none" stroke="#dc2626" stroke-width="1.5" stroke-dasharray="6 3" marker-end="url(#ah)"/><text x="320" y="35" text-anchor="middle" fill="#dc2626" font-size="11">error</text><path d="M265 100 Q265 55 470 55 Q480 55 480 100" fill="none" stroke="#dc2626" stroke-width="1.5" stroke-dasharray="6 3" marker-end="url(#ah)"/><text x="380" y="50" text-anchor="middle" fill="#dc2626" font-size="11">error</text><defs><marker id="ah" markerWidth="8" markerHeight="6" refX="8" refY="3" orient="auto"><path d="M0,0 L8,3 L0,6" fill="#334155"/></marker></defs></svg><br>6 transitions : INIT→S1, S1→S2, S2→S3, S3→OFF, S1→OFF (error), S2→OFF (error)',
q:"Quel est le nombre MINIMAL de cas de test pour atteindre la couverture des transitions valides ?",
options:["4","2","7","3"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Les transitions \"test\" et \"error\" ne peuvent pas se produire dans le meme cas de test, ni les deux transitions \"done\". Il faut donc au minimum 3 cas de test (ex: TC1: test,done / TC2: run,error,done / TC3: run,pause,resume,pause,done).<br><br><strong>\u2717 a) Incorrect</strong> \u2014 1 cas de test est insuffisant pour la couverture des transitions.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 2 cas de test sont insuffisants pour la couverture des transitions.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 3 est le minimum, pas 4."},

{id:"A-24",exam:"A",lo:"FL-4.3.1",kl:"K2",pts:1,multi:false,chapter:4,
q:"Votre suite de tests a atteint 100% de couverture des instructions. Quelle est la consequence de ce fait ?",
options:["Chaque instruction du code contenant un defaut a ete executee au moins une fois","Toute suite de tests contenant plus de cas de test atteindra aussi 100% de couverture des instructions","Chaque chemin dans le code a ete execute au moins une fois","Chaque combinaison de valeurs d'entree a ete testee au moins une fois"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 Si 100% de couverture des instructions est atteinte, chaque instruction, y compris celles contenant des defauts, a ete executee et evaluee au moins une fois.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 La couverture depend de ce qui est teste, pas du nombre de cas de test. Un seul cas de test peut atteindre 100% de couverture des instructions.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 S\'il y a une boucle, il peut y avoir un nombre infini de chemins possibles, donc il n\'est pas possible d\'executer tous les chemins.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les tests exhaustifs sont impossibles. 100% de couverture des instructions ne signifie pas que toutes les valeurs d\'entree ont ete testees."},

{id:"A-25",exam:"A",lo:"FL-4.3.3",kl:"K2",pts:1,multi:false,chapter:4,
q:"Lequel des elements suivants n'est PAS vrai pour le test boite blanche ?",
options:["L'implementation logicielle entiere est prise en compte","Les metriques de couverture boite blanche peuvent aider a identifier des tests supplementaires","Les techniques de test boite blanche peuvent etre utilisees dans le test statique","Le test boite blanche peut aider a identifier les lacunes dans l'implementation des exigences"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 C\'est la faiblesse des techniques en boite blanche : elles ne peuvent pas identifier les implementations manquantes car elles se basent uniquement sur la structure de l\'objet de test, pas sur la specification des exigences.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 C\'est une force : toute l\'implementation est prise en compte pendant les tests.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 C\'est une force : les mesures de couverture fournissent une mesure objective et permettent de generer des tests supplementaires.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les techniques en boite blanche peuvent etre utilisees pour effectuer des revues (test statique)."},

{id:"A-26",exam:"A",lo:"FL-4.4.1",kl:"K2",pts:1,multi:false,chapter:4,
q:"Lequel des elements suivants decrit le MIEUX le concept derriere la supposition d'erreurs (error guessing) ?",
options:["Utiliser votre connaissance et experience des defauts passes et des erreurs typiques des developpeurs","Utiliser votre experience personnelle de developpement et les erreurs que vous avez faites","Imaginer que vous etes l'utilisateur et deviner les erreurs qu'il pourrait faire","Dupliquer rapidement la tache de developpement pour identifier les erreurs possibles"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 Le concept de base de la prediction d\'erreurs est que le testeur essaie de deviner quelles erreurs le developpeur a pu commettre, base sur l\'experience passee et parfois des checklists.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 La technique n\'est pas basee sur une connaissance prealable du developpement mais sur l\'experience de test.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 La prediction d\'erreurs n\'est pas une technique d\'utilisabilite pour deviner comment les utilisateurs echoueraient a interagir avec le systeme.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Dupliquer la tache de developpement a plusieurs defauts qui la rendent impraticable et ce n\'est pas de la prediction d\'erreurs."},

{id:"A-27",exam:"A",lo:"FL-4.4.2",kl:"K2",pts:1,multi:false,chapter:4,
q:"Dans votre projet, il y a eu un retard dans la release d'une nouvelle application et l'execution des tests a commence en retard, mais vous avez des connaissances detaillees du domaine et de bonnes competences analytiques. La liste complete des exigences n'a pas encore ete partagee. Quelle technique de test convient le MIEUX ?",
options:["Test base sur une checklist","Supposition d'erreurs","Test exploratoire","Test des branches"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 Les tests exploratoires sont les plus utiles quand il y a peu de specifications connues et/ou un delai serre pour les tests.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 C\'est un nouveau produit, vous n\'avez probablement pas encore de checklist et les conditions de test ne sont peut-etre pas connues.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 C\'est un nouveau produit, vous n\'avez probablement pas assez d\'informations pour faire des predictions d\'erreurs correctes.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Le test des branches est chronophage et votre direction veut des resultats maintenant. De plus, le test des branches n\'implique pas de connaissances du domaine."},

{id:"A-28",exam:"A",lo:"FL-4.5.2",kl:"K2",pts:1,multi:false,chapter:4,
q:"Lequel des elements suivants decrit le MIEUX comment les criteres d'acceptation peuvent etre documentes ?",
options:["Utiliser des retrospectives pour determiner les besoins reels des parties prenantes","Utiliser le format given/when/then pour decrire un exemple de condition de test","Utiliser la communication verbale pour reduire les risques de malentendu","Documenter les risques dans un plan de test pour faciliter les tests bases sur les risques"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 C\'est la methode standard pour documenter les criteres d\'acceptation dans le cadre d\'une user story.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Les retrospectives servent a capturer les lecons apprises et ameliorer le processus, pas a documenter les criteres d\'acceptation.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 La communication verbale ne permet pas de documenter physiquement les criteres d\'acceptation (aspect \"carte\" du modele 3C).<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les criteres d\'acceptation sont lies a une user story, pas a un plan de test. Les risques ne sont pas des criteres d\'acceptation."},

{id:"A-29",exam:"A",lo:"FL-4.5.3",kl:"K3",pts:1,multi:false,chapter:4,
q:"Considerez la user story suivante :\nEn tant qu'editeur, je veux revoir le contenu avant publication pour m'assurer que la grammaire est correcte.\nCriteres d'acceptation : connexion editeur, voir les pages, editer le contenu, ajouter des commentaires, sauvegarder, reassigner au proprietaire du contenu.\nQuel est le MEILLEUR exemple de test ATDD ?",
options:["Tester si l'editeur peut sauvegarder apres avoir edite","Tester si le proprietaire du contenu peut se connecter et faire des mises a jour","Tester si l'editeur peut planifier le contenu edite pour publication","Tester si l'editeur peut reassigner a un autre editeur"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 Ce test couvre deux criteres d\'acceptation : un sur l\'edition du document et un sur la sauvegarde des modifications.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les criteres d\'acceptation couvrent les activites de l\'editeur, pas celles du proprietaire du contenu.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Planifier la publication du contenu edite peut etre une fonctionnalite interessante, mais elle n\'est pas couverte par les criteres d\'acceptation.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les criteres d\'acceptation parlent de reassigner de l\'editeur au proprietaire du contenu, pas a un autre editeur."},

{id:"A-30",exam:"A",lo:"FL-5.1.2",kl:"K1",pts:1,multi:false,chapter:5,
q:"Comment les testeurs apportent-ils de la valeur a la planification des iterations et des releases ?",
options:["Les testeurs determinent la priorite des user stories a developper","Les testeurs se concentrent uniquement sur les aspects fonctionnels du systeme","Les testeurs participent a l'identification et a l'evaluation detaillees des risques des user stories","Les testeurs garantissent la release d'un logiciel de haute qualite grace a la conception precoce des tests"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 Selon le syllabus, c\'est une des facons dont les testeurs apportent de la valeur a la planification des iterations et des releases.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Les priorites des user stories sont determinees par le representant metier avec l\'equipe de developpement.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les testeurs se concentrent sur les aspects fonctionnels ET non fonctionnels du systeme a tester.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 La conception precoce des tests ne fait pas partie de la planification de release et ne garantit pas automatiquement la qualite."},

{id:"A-31",exam:"A",lo:"FL-5.1.3",kl:"K2",pts:1,multi:true,chapter:5,
q:"Lesquelles des options suivantes sont des criteres de sortie pour tester un systeme ?",
options:["Disponibilite de l'environnement de test","Capacite du testeur a se connecter a l'objet de test","La densite de defauts estimee est atteinte","Les exigences sont traduites au format given/when/then","Les tests de regression sont automatises"],
correct:[2,4],
justification:"<strong>\u2713 c, e) Correct</strong> \u2014 c) La densite estimee de defauts est une mesure de diligence, donc un critere de sortie. e) L\'automatisation des tests de regression est un critere de completion, donc un critere de sortie.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 La disponibilite de l\'environnement de test est un critere de disponibilite des ressources, donc un critere d\'entree.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 C\'est un critere de disponibilite des ressources, donc un critere d\'entree.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les exigences traduites dans un format donne sont des exigences testables, donc un critere d\'entree."},

{id:"A-32",exam:"A",lo:"FL-5.1.4",kl:"K3",pts:1,multi:false,chapter:5,
q:"Votre equipe utilise la technique d'estimation a trois points pour estimer l'effort de test d'une nouvelle fonctionnalite a haut risque.\n- Estimation la plus optimiste : 2 heures-personne\n- Estimation la plus probable : 11 heures-personne\n- Estimation la plus pessimiste : 14 heures-personne\nQuelle est l'estimation finale ?",
options:["9 heures-personne","14 heures-personne","11 heures-personne","10 heures-personne"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Avec la technique d\'estimation en trois points : E = (optimiste + 4*probable + pessimiste)/6 = (2 + 4*11 + 14)/6 = 60/6 = 10.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le calcul ne donne pas ce resultat.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Le calcul ne donne pas ce resultat.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Le calcul ne donne pas ce resultat."},

{id:"A-33",exam:"A",lo:"FL-5.1.5",kl:"K3",pts:1,multi:false,chapter:5,
q:"Vous testez une application mobile de recherche de restaurant. Cas de test avec priorites et dependances :\nTC001(prio 3, aucune), TC002(prio 2, dep TC001), TC003(prio 1, dep TC002), TC004(prio 2, dep TC002), TC005(prio 3, dep TC002)\nQuel cas de test doit etre execute en troisieme ?",
options:["TC 003","TC 005","TC 002","TC 001"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 TC 001 doit venir en premier, suivi de TC 002 pour satisfaire les dependances. Ensuite TC 003 pour la priorite, puis TC 004 et TC 005.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 L\'ordre ne respecte pas les dependances et/ou les priorites.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 L\'ordre ne respecte pas les dependances et/ou les priorites.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 L\'ordre ne respecte pas les dependances et/ou les priorites."},

{id:"A-34",exam:"A",lo:"FL-5.1.7",kl:"K2",pts:1,multi:false,chapter:5,
q:"Considerez les categories de test (1-4) et les quadrants de test agile (A-D) :\n1. Test d'utilisabilite  2. Test de composant  3. Test fonctionnel  4. Test de fiabilite\nA. Q1: technologie, soutien equipe  B. Q2: metier, soutien equipe  C. Q3: metier, critique produit  D. Q4: technologie, critique produit\nComment les categories correspondent-elles aux quadrants ?",
options:["1C, 2A, 3B, 4D","1D, 2A, 3C, 4B","1C, 2B, 3D, 4A","1D, 2B, 3C, 4A"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 Tests d\'utilisabilite en Q3 (1-C), tests de composants en Q1 (2-A), tests fonctionnels en Q2 (3-B), tests de fiabilite en Q4 (4-D).<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les appariements proposes ne correspondent pas aux bons quadrants de test.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les appariements proposes ne correspondent pas aux bons quadrants de test.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les appariements proposes ne correspondent pas aux bons quadrants de test."},

{id:"A-35",exam:"A",lo:"FL-5.2.4",kl:"K2",pts:1,multi:false,chapter:5,
q:"Lors d'une analyse de risque, le risque suivant a ete identifie :\n- Risque : Le temps de reponse est trop long pour generer un rapport\n- Vraisemblance : moyenne ; Impact : eleve\n- Reponse : une equipe de test independante effectue des tests de performance ; des utilisateurs finaux effectuent des tests alpha et beta\nQuelle mesure est proposee ?",
options:["Acceptation du risque","Plan de contingence","Attenuation du risque","Transfert du risque"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 Les actions proposees sont liees aux tests, ce qui est une forme d\'attenuation des risques.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 On n\'accepte pas le risque ; des actions concretes sont proposees.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Aucun plan de contingence n\'est propose.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Le risque n\'est pas transfere mais attenue."},

{id:"A-36",exam:"A",lo:"FL-5.3.3",kl:"K2",pts:1,multi:false,chapter:5,
q:"Quel produit d'activite peut etre utilise par une equipe agile pour montrer la quantite de travail accomplie et la quantite restante pour une iteration donnee ?",
options:["Criteres d'acceptation","Rapport de defaut","Rapport de completion de test","Burndown chart"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Les burndown charts sont une representation graphique du travail restant en fonction du temps. Ils sont mis a jour quotidiennement et montrent la progression de maniere continue.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Les criteres d\'acceptation sont les conditions pour decider si la user story est terminee. Ils ne montrent pas la progression du travail.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les rapports de defauts informent sur les defauts mais ne montrent pas la progression du travail.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Le rapport de completion des tests peut etre cree apres la fin de l\'iteration, donc il ne montre pas la progression de maniere continue."},

{id:"A-37",exam:"A",lo:"FL-5.4.1",kl:"K2",pts:1,multi:false,chapter:5,
q:"Vous devez mettre a jour un script de test automatise pour etre en ligne avec une nouvelle exigence. Quel processus indique que vous creez une nouvelle version du script dans le referentiel ?",
options:["Gestion de la tracabilite","Test de maintenance","Gestion de configuration","Ingenierie des exigences"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 Pour supporter les tests, la gestion de configuration peut impliquer le controle de version de tous les elements de test.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 La tracabilite est la relation entre deux ou plusieurs produits de travail, pas entre differentes versions du meme produit.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les tests de maintenance concernent le test des changements et ne sont pas etroitement lies au versioning.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 L\'ingenierie des exigences concerne l\'elicitation, la documentation et la gestion des exigences, pas le versioning des scripts de test."},

{id:"A-38",exam:"A",lo:"FL-5.5.1",kl:"K3",pts:1,multi:false,chapter:5,
q:"Vous avez recu un rapport de defaut des developpeurs indiquant que l'anomalie n'est pas reproductible. Le rapport mentionne : application bloquee, compte test_admin01, erreur fatale dans le log, reference TC-1305, exigence REQ-0012.\nQuelle information critique MANQUE ?",
options:["Resultat attendu et resultat reel","References et statut du defaut","Environnement de test et element de test","Priorite et severite"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 On ne sait pas dans quel environnement de test l\'anomalie a ete detectee, ni quelle application (et sa version) est affectee.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le resultat attendu et le resultat reel sont correctement documentes dans le rapport.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Il y a une reference au cas de test et a l\'exigence associee, et le statut du defaut est mentionne.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Le rapport indique que l\'anomalie est urgente, que c\'est un probleme global et que l\'impact est eleve pour les parties prenantes."},

{id:"A-39",exam:"A",lo:"FL-6.1.1",kl:"K2",pts:1,multi:false,chapter:6,
q:"Quelle activite de test un outil de preparation de donnees supporte-t-il ?",
options:["Pilotage et controle des tests","Analyse de test","Conception et implementation de test","Completion de test"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 La conception et l\'implementation des tests peuvent toutes deux inclure l\'identification, la creation ou l\'acquisition du testware necessaire a l\'execution des tests (ex: donnees de test).<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le monitoring et le controle des tests impliquent la verification de la progression et les actions correctives, pas la preparation des donnees de test.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 L\'analyse de test inclut l\'analyse de la base de test pour identifier les conditions de test, pas la preparation des donnees.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les activites de cloture des tests se produisent aux jalons du projet, il est donc trop tard pour preparer les donnees de test."},

{id:"A-40",exam:"A",lo:"FL-6.2.1",kl:"K1",pts:1,multi:false,chapter:6,
q:"Quel element identifie correctement un risque potentiel de l'automatisation des tests ?",
options:["Elle peut introduire des regressions inconnues en production","Un effort insuffisant pour maintenir le testware peut ne pas etre correctement alloue","Les outils de test et le testware associe peuvent ne pas etre suffisamment fiables","Elle peut reduire le temps alloue aux tests manuels"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Une mauvaise allocation de l\'effort pour maintenir le testware est un risque de l\'automatisation des tests.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 L\'automatisation des tests n\'introduit pas de regressions inconnues en production.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les outils de test doivent etre selectionnes pour etre fiables, ce n\'est pas un risque inherent a l\'automatisation.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 L\'objectif principal de l\'automatisation est de reduire les tests manuels, c\'est un avantage, pas un risque."},

// ========== EXAM A: Additional Questions A1-A26 ==========
{id:"A-A1",exam:"A",lo:"FL-1.1.2",kl:"K2",pts:1,multi:false,chapter:1,
q:"On vous a confie la tache d'analyser et de corriger les causes de defaillances dans un nouveau systeme. Quelle activite effectuez-vous ?",
options:["Debogage","Test logiciel","Elicitation des exigences","Gestion des defauts"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 Le debogage est le processus de recherche, d\'analyse et de suppression des causes des defaillances dans un composant ou un systeme.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Le test est le processus concerne par la planification, la preparation et l\'evaluation, pas par la correction des causes des defaillances.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 L\'elicitation des exigences est le processus de collecte et consolidation des exigences, sans lien avec la correction des defaillances.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 La gestion des defauts est le processus de reconnaissance, enregistrement et disposition des defauts, sans lien direct avec la correction des causes."},

{id:"A-A2",exam:"A",lo:"FL-1.2.2",kl:"K1",pts:1,multi:false,chapter:1,
q:"Dans de nombreuses organisations, le departement de test est appele departement Assurance Qualite (QA). Cette phrase est-elle correcte ?",
options:["Oui. Le test et la QA signifient la meme chose","Oui. Ces noms sont interchangeables","Non. Le test inclut tout ; la QA se concentre sur les processus qualite","Non. La QA se concentre sur les processus qualite tandis que le test se concentre sur la demonstration de l'adequation et la detection de defauts"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Le test et l\'assurance qualite ne sont pas la meme chose. Le test est une forme de controle qualite (QC) qui detecte les defauts, tandis que l\'assurance qualite (QA) se concentre sur l\'amelioration des processus avec une approche preventive.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Cette affirmation ne decrit pas correctement la relation entre test et QA/QC.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Cette affirmation ne decrit pas correctement la relation entre test et QA/QC.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Cette affirmation ne decrit pas correctement la relation entre test et QA/QC."},

{id:"A-A3",exam:"A",lo:"FL-1.2.3",kl:"K2",pts:1,multi:false,chapter:1,
q:"Un telephone sonne et distrait un programmeur, causant une erreur dans la verification de la limite superieure d'une variable. Plus tard, le champ accepte des valeurs invalides.\nQu'est-ce qui decrit correctement la limite superieure mal codee ?",
options:["La cause racine","Une defaillance","Une erreur","Un defaut"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Le probleme dans le code est un defaut.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 La cause racine est la distraction que le programmeur a subie pendant la programmation, pas le code lui-meme.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Accepter des entrees invalides est une defaillance (failure), pas un defaut.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 L\'erreur de reflexion qui a mis le defaut dans le code est une erreur (error), pas un defaut."},

{id:"A-A4",exam:"A",lo:"FL-1.4.3",kl:"K2",pts:1,multi:false,chapter:1,
q:"Considerez le testware suivant :\nCharte de test #04.018, Session: 1h\nExplorer: Page d'inscription\nAvec: Differents jeux de donnees incorrectes\nDecouvrir: Defauts lies a l'acceptation de donnees incorrectes\nQuelle activite de test produit ce testware ?",
options:["Planification de test","Pilotage et controle de test","Analyse de test","Conception de test"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Le testware en question est une charte de test (test charter). Les chartes de test sont le resultat de la conception des tests.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Ce n\'est pas le resultat de l\'analyse de test.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Ce n\'est pas le resultat de l\'implementation des tests.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Ce n\'est pas le resultat de l\'execution des tests."},

{id:"A-A5",exam:"A",lo:"FL-1.4.4",kl:"K2",pts:1,multi:false,chapter:1,
q:"Lequel des elements suivants est le MEILLEUR exemple de comment la tracabilite soutient le test ?",
options:["L'analyse d'impact d'un changement donne des informations sur la completion des tests","L'analyse de la tracabilite entre cas de test et resultats donne des informations sur le risque residuel estime","L'analyse d'impact d'un changement aide a selectionner les bons cas de test pour les tests de regression","L'analyse de la tracabilite entre base de test, objets de test et cas de test aide a selectionner les donnees de test"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 L\'analyse d\'impact des changements aide a selectionner les cas de test pour les tests de regression.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 L\'analyse d\'impact ne donne pas d\'information sur la completude des tests.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 La tracabilite ne donne pas d\'information sur le niveau de risque residuel si les cas de test ne sont pas traces aux risques.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 L\'analyse de la tracabilite entre la base de test, les objets de test et les cas de test n\'aide pas a selectionner les donnees de test."},

{id:"A-A6",exam:"A",lo:"FL-1.5.3",kl:"K2",pts:1,multi:false,chapter:1,
q:"Lequel des elements suivants explique le MIEUX un avantage de l'independance des tests ?",
options:["L'equipe de test independante permet d'assigner la responsabilite de la qualite a l'equipe de test","Si une equipe externe peut etre financee, elle n'est pas facilement influencee par les contraintes de livraison","Une equipe de test independante peut travailler separement et restreindre la communication aux rapports de defauts","Quand les specifications contiennent des ambiguites, un testeur independant peut remettre en question les hypotheses"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Les specifications ne sont jamais parfaites, donc des hypotheses doivent etre faites par le developpeur. Un testeur independant est utile car il peut remettre en question et verifier ces hypotheses.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 La qualite devrait etre la responsabilite de tous, pas seulement de l\'equipe de test.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Il n\'y a aucune raison de croire qu\'une equipe de test externe ne respecterait pas les delais.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 C\'est une mauvaise pratique que l\'equipe de test travaille en isolation complete."},

{id:"A-A7",exam:"A",lo:"FL-2.1.1",kl:"K2",pts:1,multi:true,chapter:2,
q:"Vous travaillez comme testeur dans une equipe qui suit le modele en V. Lesquelles des activites suivantes PEUVENT etre effectuees dans les phases initiales du SDLC ?",
options:["Execution dynamique de test","Test statique","Planification de test","Execution de test d'acceptation","Test de maintenance"],
correct:[1,2],
justification:"<strong>\u2713 b, c) Correct</strong> \u2014 b) Dans les modeles sequentiels, les testeurs participent aux revues d\'exigences (test statique) dans les phases initiales. c) La planification des tests peut etre realisee tot dans le SDLC.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le code executable est cree dans les phases ulterieures, donc l\'execution de tests dynamiques ne peut pas etre realisee tot.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 L\'execution des tests d\'acceptation necessite un produit fonctionnel, qui est livre plus tard dans les modeles sequentiels.<br><br><strong>\u2717 e) Incorrect</strong> \u2014 Les tests de maintenance necessitent un produit deploye, ce qui n\'est pas fait dans les phases initiales."},

{id:"A-A8",exam:"A",lo:"FL-2.1.4",kl:"K2",pts:1,multi:false,chapter:2,
q:"Lesquels des elements suivants sont des avantages du DevOps ?\ni. Release produit plus rapide\nii. Augmente le besoin de tests manuels repetitifs\niii. Disponibilite constante de logiciel executable\niv. Reduction du nombre de tests de regression\nv. Mise en place de l'automatisation peu couteuse",
options:["i, ii, iv sont des avantages","iii, v sont des avantages","i, iii sont des avantages","ii, iv, v sont des avantages"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 Les affirmations i (livraison plus rapide) et iii (disponibilite constante du logiciel executable) sont des avantages du DevOps.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 La combinaison i, ii est incorrecte car ii (moins d\'effort pour les tests manuels du fait de l\'automatisation) est faux - on a besoin de MOINS de tests manuels, pas plus.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 La combinaison ii, iii est incorrecte car ii est faux.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les affirmations iv (plus de tests de regression) et v (tout est automatise) sont incorrectes."},

{id:"A-A9",exam:"A",lo:"FL-2.2.2",kl:"K2",pts:1,multi:false,chapter:2,
q:"Vous testez une application mobile de commande de nourriture. L'exigence dit : 'La commande doit etre traitee en moins de 10 secondes dans 95% des cas.' Quel type de test avez-vous effectue ?",
options:["Fonctionnel, car les cas de test couvrent l'exigence metier","Non-fonctionnel, car ils mesurent la performance du systeme","Fonctionnel, car les cas de test interagissent avec l'interface utilisateur","Boite blanche, car il faut connaitre la structure interne"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 C\'est un exemple de test d\'efficacite de performance, un type de test non fonctionnel.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le fait que l\'exigence vienne du client et soit prioritaire ne rend pas ces tests fonctionnels ; ils verifient \"comment\" le systeme fonctionne (performance), pas \"quoi\".<br><br><strong>\u2717 c) Incorrect</strong> \u2014 L\'objectif principal est de verifier la performance, pas l\'utilisabilite, meme si l\'interface utilisateur est impliquee.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 On n\'a pas besoin de connaitre la structure interne du code pour effectuer des tests de performance."},

{id:"A-A10",exam:"A",lo:"FL-2.3.1",kl:"K2",pts:1,multi:false,chapter:2,
q:"La strategie de test de votre organisation suggere que lorsqu'un systeme va etre retire, la migration des donnees doit etre testee. Dans le cadre de quel type de test cela est-il le PLUS probablement effectue ?",
options:["Test de maintenance","Test de regression","Test de fiabilite","Test d'integration"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 Quand un systeme est retire, cela peut necessiter des tests de migration de donnees, qui sont une forme de test de maintenance.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Le test de regression verifie si une correction n\'a pas affecte d\'autres parties du code, pas la migration de donnees.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Le test de portabilite se concentre sur le transfert du systeme vers un autre environnement, pas sur la migration de donnees.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Le test d\'integration se concentre sur les interactions entre composants, pas sur la migration de donnees. De plus, c\'est un niveau de test, pas un type."},

{id:"A-A11",exam:"A",lo:"FL-3.1.1",kl:"K1",pts:1,multi:false,chapter:3,
q:"Voici une liste de produits d'activite :\ni. Exigences metier  ii. Planning  iii. Budget de test  iv. Code executable tiers  v. User stories et criteres d'acceptation\nLesquels peuvent etre revises ?",
options:["i et iv peuvent etre revises","i, ii, iii et iv peuvent etre revises","i, ii, iii et v peuvent etre revises","iii, iv, v peuvent etre revises"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 Seul le code executable tiers ne peut pas etre revu par test statique.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Cette combinaison inclut des elements qui peuvent etre revus.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Cette combinaison inclut des elements qui peuvent etre revus.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Cette combinaison inclut des elements qui peuvent etre revus."},

{id:"A-A12",exam:"A",lo:"FL-3.1.3",kl:"K2",pts:1,multi:false,chapter:3,
q:"Decidez lesquelles des affirmations suivantes (i-v) sont vraies pour le test statique.\ni. Les comportements externes anormaux sont plus faciles a identifier\nii. Les ecarts par rapport a un standard de codage sont plus faciles a trouver\niii. Il identifie les defaillances causees par des defauts lors de l'execution\niv. Son objectif est d'identifier les defauts le plus tot possible\nv. La couverture manquante pour les exigences de securite critiques est plus facile a trouver",
options:["i, iv, v sont vraies","i, iii, iv sont vraies","ii, iii sont vraies","ii, iv, v sont vraies"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Les deviations par rapport aux standards (ii) et les lacunes de tracabilite (v) sont des defauts plus facilement trouves par le test statique. Les comportements visibles a l\'execution (i, iii) relevent du test dynamique. L\'identification precoce des defauts (iv) est un objectif des deux approches.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Les associations ne sont pas correctes.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les associations ne sont pas correctes.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les associations ne sont pas correctes."},

{id:"A-A13",exam:"A",lo:"FL-3.2.2",kl:"K2",pts:1,multi:false,chapter:3,
q:"Laquelle des affirmations suivantes concernant les revues formelles est VRAIE ?",
options:["Certaines revues ne necessitent qu'un seul role","Le processus de revue comprend plusieurs activites","La documentation n'est pas distribuee avant la reunion de revue","Les defauts trouves lors de la revue ne sont pas rapportes"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Il y a plusieurs activites durant le processus de revue formelle.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Dans tous les types de revues, il y a plus d\'un role, meme dans les revues informelles.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 La documentation a revoir devrait etre distribuee le plus tot possible.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les defauts trouves pendant la revue devraient etre reportes."},

{id:"A-A14",exam:"A",lo:"FL-3.2.3",kl:"K1",pts:1,multi:false,chapter:3,
q:"Quelle tache le management peut-il assumer lors d'une revue formelle ?",
options:["Prendre la responsabilite globale de la revue","Decider ce qui doit etre revise","Assurer le bon deroulement des reunions de revue","Enregistrer les informations de revue"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 C\'est la tache du management dans une revue formelle.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 C\'est la tache du responsable de revue (review leader).<br><br><strong>\u2717 c) Incorrect</strong> \u2014 C\'est la tache du moderateur.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 C\'est la tache du scribe."},

{id:"A-A15",exam:"A",lo:"FL-4.2.2",kl:"K3",pts:1,multi:false,chapter:4,
q:"Un systeme de stockage de vin utilise un dispositif qui mesure la temperature T (en degC, arrondie au degre le plus proche) et alerte si elle devie de la valeur optimale de 12.\nRegles : T=12 'optimal', T<12 'trop bas', T>12 'trop haut'\nVous voulez utiliser la BVA 3 points. Quel est l'ensemble MINIMAL de valeurs de test ?",
options:["11, 12, 13","10, 12, 14","10, 11, 12, 13, 14","10, 11, 13, 14"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 Il y a 3 partitions d\'equivalence : {...,10,11}, {12} et {13,14,...}. Les valeurs limites sont 11, 12 et 13. En BVA a trois points, pour chaque limite on teste la limite et ses deux voisins : pour 11 (10,11,12), pour 12 (11,12,13), pour 13 (12,13,14). Total : 10, 11, 12, 13, 14.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 L\'ensemble de valeurs ne correspond pas a l\'analyse correcte.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 L\'ensemble de valeurs ne correspond pas a l\'analyse correcte.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 L\'ensemble de valeurs ne correspond pas a l\'analyse correcte."},

{id:"A-A16",exam:"A",lo:"FL-4.3.2",kl:"K2",pts:1,multi:false,chapter:4,
q:"Laquelle des affirmations suivantes concernant le test des branches est CORRECTE ?",
options:["Si un programme ne contient que des branches inconditionnelles, la couverture 100% peut etre atteinte sans executer de cas de test","Si les cas de test exercent toutes les branches inconditionnelles, la couverture 100% est atteinte","Si 100% de couverture des instructions est atteinte, 100% de couverture des branches l'est aussi","Si 100% de couverture des branches est atteinte, tous les resultats de decision sont exerces"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Chaque resultat de decision correspond a une branche conditionnelle, donc 100% de couverture des branches implique 100% de couverture des resultats de decision.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Meme sans code conditionnel, au moins un cas de test est necessaire pour couvrir la branche inconditionnelle.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Couvrir uniquement les branches inconditionnelles n\'implique pas la couverture de toutes les branches conditionnelles.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 100% de couverture des branches implique 100% de couverture des instructions, pas l\'inverse."},

{id:"A-A17",exam:"A",lo:"FL-4.4.3",kl:"K2",pts:1,multi:false,chapter:4,
q:"Vous testez une application bancaire mobile. Vous evaluez chaque ecran et chaque champ selon une liste de bonnes pratiques d'interface utilisateur tiree d'un livre populaire. Quelle technique utilisez-vous ?",
options:["Boite noire","Exploratoire","Basee sur une checklist","Supposition d'erreurs"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 La liste des bonnes pratiques d\'interface utilisateur est la liste des conditions de test a verifier systematiquement (test base sur des checklists).<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le livre fournit des conseils generaux, pas un document d\'exigences formel.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Bien que la liste puisse etre consideree comme des chartes de test, elle ressemble davantage a des conditions de test.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les tests ne sont pas centres sur les defaillances potentielles mais sur les connaissances de ce qui est important pour l\'utilisateur en termes d\'utilisabilite."},

{id:"A-A18",exam:"A",lo:"FL-4.5.1",kl:"K2",pts:1,multi:false,chapter:4,
q:"Lequel des elements suivants decrit le MIEUX l'approche collaborative de redaction de user stories ?",
options:["Les user stories sont creees par les testeurs et developpeurs puis acceptees par les representants metier","Les user stories sont creees ensemble par les representants metier, developpeurs et testeurs","Les user stories sont creees par les representants metier et verifiees par les developpeurs et testeurs","Les user stories sont creees de maniere a etre independantes, negociables, valorisables, estimables, petites et testables"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 L\'ecriture collaborative des user stories signifie que toutes les parties prenantes creent les user stories ensemble pour obtenir une vision partagee.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 La collaboration implique TOUTES les parties prenantes, pas seulement certaines.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 La collaboration implique TOUTES les parties prenantes pour une vision partagee.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 C\'est la liste des proprietes que chaque user story devrait avoir (INVEST), pas la description de l\'approche collaborative."},

{id:"A-A19",exam:"A",lo:"FL-5.1.1",kl:"K2",pts:1,multi:false,chapter:5,
q:"Considerez l'extrait suivant d'un plan de test :\n'Les tests seront effectues en utilisant les tests de composants et d'integration. La reglementation exige de demontrer que 100% de couverture des branches est atteinte pour chaque composant critique.'\nA quelle partie du plan de test cela appartient-il ?",
options:["Communication","Registre des risques","Contexte du test","Approche de test"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Le paragraphe contient des informations sur les niveaux de test et les criteres de sortie, qui font partie de l\'approche de test.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Cette option ne correspond pas au contenu du paragraphe sur les niveaux de test et criteres de sortie.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Cette option ne correspond pas au contenu du paragraphe.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Cette option ne correspond pas au contenu du paragraphe."},

{id:"A-A20",exam:"A",lo:"FL-5.1.4",kl:"K3",pts:1,multi:false,chapter:5,
q:"Votre equipe utilise le planning poker pour estimer l'effort de test. Apres 3 tours :\nTour 3 : 13, 8, 13, 13, 13, 13, 8\nQuelle est la MEILLEURE etape suivante ?",
options:["Le product owner doit trancher","Accepter 13 comme estimation finale car il a le plus de votes","Aucune action necessaire, le consensus est atteint","Retirer la fonctionnalite car le consensus n'est pas atteint"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Si les estimations ne sont pas les memes mais que la variation est faible, on peut appliquer des regles comme \"accepter le nombre avec le plus de votes\".<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Ce devrait etre une activite d\'equipe et non decidee par une seule personne.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Il n\'y a pas encore de consensus car certains disent 13 et d\'autres 8.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Une fonctionnalite ne devrait pas etre supprimee simplement parce que l\'equipe ne se met pas d\'accord sur les estimations."},

{id:"A-A21",exam:"A",lo:"FL-5.1.6",kl:"K1",pts:1,multi:false,chapter:5,
q:"Lequel des elements suivants est VRAI concernant la pyramide de test ?",
options:["Elle met l'accent sur un plus grand nombre de tests aux niveaux inferieurs","Elle suggere que chaque test de bas niveau verifie une grande partie de la fonctionnalite","Elle decrit la distribution des types de test dans le SDLC","Elle n'a aucun impact sur la construction de tests automatises"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 La pyramide des tests met l\'accent sur un plus grand nombre de tests aux niveaux de test inferieurs.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Il n\'est pas vrai qu\'un test de niveau inferieur teste une plus grande partie de la fonctionnalite. Les tests sont plus atomiques, c\'est l\'inverse.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 La pyramide des tests montre comment le nombre de tests est distribue entre les niveaux de test, pas les fonctionnalites.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Le modele de la pyramide des tests soutient l\'equipe dans l\'automatisation des tests, mais ce n\'est pas sa definition principale."},

{id:"A-A22",exam:"A",lo:"FL-5.2.1",kl:"K1",pts:1,multi:false,chapter:5,
q:"Lors de l'analyse de risque, l'equipe a considere le risque : 'Le systeme permet une remise trop elevee'. L'impact est estime tres eleve. Que peut-on dire de la vraisemblance ?",
options:["Elle est aussi tres elevee. Un impact eleve implique toujours une vraisemblance elevee","Elle est tres faible. Un impact eleve implique toujours une vraisemblance faible","On ne peut rien dire. Impact et vraisemblance sont independants","La vraisemblance n'est pas importante avec un tel impact"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 L\'impact du risque et la probabilite du risque sont independants l\'un de l\'autre.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 L\'impact et la probabilite sont independants, cette affirmation est fausse.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 L\'impact et la probabilite sont independants, cette affirmation est fausse.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 On a besoin des deux facteurs pour calculer le niveau de risque."},

{id:"A-A23",exam:"A",lo:"FL-5.2.2",kl:"K2",pts:1,multi:false,chapter:5,
q:"Risques identifies pour un nouveau logiciel :\ni. Le management deplace deux testeurs experimentes vers un autre projet\nii. Le systeme ne respecte pas les normes de securite\niii. Le temps de reponse depasse les exigences utilisateur\niv. Les parties prenantes ont des attentes inexactes\nv. Les personnes handicapees ont des problemes d'utilisation\nLesquels sont des risques projet ?",
options:["i, iv sont des risques projet","iv, v sont des risques projet","i, iii sont des risques projet","ii, v sont des risques projet"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 i) est un risque projet, ii) est un risque produit, iii) est un risque produit, iv) est un risque projet, v) est un risque produit.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 La classification des risques projet/produit n\'est pas correcte.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 La classification des risques projet/produit n\'est pas correcte.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 La classification des risques projet/produit n\'est pas correcte."},

{id:"A-A24",exam:"A",lo:"FL-5.2.3",kl:"K2",pts:1,multi:false,chapter:5,
q:"Lequel des elements suivants est un exemple de comment l'analyse de risque produit influence la rigueur et la portee des tests ?",
options:["Le test manager surveille et rapporte le niveau de tous les risques connus quotidiennement","L'equipe a decide d'integrer le systeme avec une base de donnees open-source","L'equipe a estime le niveau total de tous les risques identifies","L'evaluation des risques a revele un niveau tres eleve de risques de performance, il a donc ete decide d'effectuer des tests de performance detailles tot dans le SDLC"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Cela montre comment l\'analyse des risques impacte la minutie des tests (le niveau de detail).<br><br><strong>\u2717 a) Incorrect</strong> \u2014 C\'est un exemple d\'activite de surveillance des risques, pas d\'analyse des risques.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 C\'est un exemple de decision architecturale, sans lien avec les tests.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 C\'est un exemple d\'analyse quantitative des risques, sans lien avec la minutie ou la portee des tests."},

{id:"A-A25",exam:"A",lo:"FL-5.3.1",kl:"K1",pts:1,multi:true,chapter:5,
q:"Lesquelles des options suivantes sont des metriques courantes utilisees pour rapporter le niveau de qualite de l'objet de test ?",
options:["Nombre de defauts trouves pendant les tests systeme","Effort total de conception de test divise par le nombre de cas de test concus","Nombre de procedures de test executees","Nombre de defauts divise par la taille d'un produit d'activite","Temps necessaire pour reparer un defaut"],
correct:[0,3],
justification:"<strong>\u2713 a, d) Correct</strong> \u2014 a) Le nombre de defauts trouves est lie a la qualite de l\'objet de test. d) La densite de defauts est liee a la qualite de l\'objet de test.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 C\'est une mesure de l\'efficacite du test, pas de la qualite de l\'objet de test.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Le nombre de cas de test executes ne dit rien sur la qualite ; seuls les resultats pourraient le faire.<br><br><strong>\u2717 e) Incorrect</strong> \u2014 Le temps de reparation est une metrique de processus, pas de qualite produit."},

{id:"A-A26",exam:"A",lo:"FL-5.3.2",kl:"K2",pts:1,multi:false,chapter:5,
q:"Quelle information contenue dans un rapport de progression de test est la MOINS utile pour les representants metier ?",
options:["Impediments aux tests","Couverture des branches atteinte","Progression des tests","Nouveaux risques dans le cycle de test"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Le test des branches est une metrique technique utilisee par les developpeurs et analystes de test techniques. Cette information n\'est pas interessante pour les representants metier.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Les impediments aux tests peuvent etre de haut niveau et lies au metier, c\'est une information importante pour les parties prenantes metier.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 La progression des tests est liee au projet, donc utile pour les representants metier.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les risques impactent la qualite du produit, donc utile pour les representants metier."},

// ========== EXAM B: Questions 1-40 ==========
{id:"B-1",exam:"B",lo:"FL-1.2.1",kl:"K2",pts:1,multi:false,chapter:1,
q:"Lequel des elements suivants est un exemple de la raison pour laquelle les tests sont necessaires ?",
options:["Le test dynamique augmente la qualite en causant des defaillances que les utilisateurs ne pourraient jamais obtenir","Le test statique est utilise par les developpeurs pour identifier les defaillances dans leur code plus tot","L'analyse statique fournit des preuves que les elements du systeme sans sorties sont prets","Les revues augmentent la qualite des specifications d'exigences et reduisent les changements necessaires dans les produits derives"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Les revues sont une forme de test statique qui peut etre appliquee des le debut du SDLC pour trouver des defauts dans les exigences avant que les activites suivantes ne gaspillent des efforts sur des exigences defectueuses.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Provoquer des defaillances que les utilisateurs ne pourraient jamais atteindre n\'est pas utile, car le test vise a ameliorer le produit pour les utilisateurs finaux reels.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Le test statique (analyse statique) detecte des defauts, pas des defaillances. C\'est l\'utilisation du terme \"defaillances\" qui rend cette option incorrecte.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 L\'analyse statique detecte directement des defauts dans le code, une information pour le developpeur, pas pour le client."},

{id:"B-2",exam:"B",lo:"FL-1.2.2",kl:"K1",pts:1,multi:false,chapter:1,
q:"Laquelle des affirmations suivantes concernant l'assurance qualite (QA) et/ou le controle qualite (QC) est correcte ?",
options:["La QA est effectuee dans le cadre du test","Le test est effectue dans le cadre du QC","Le test est un autre terme pour le QC","Le test est effectue dans le cadre de la QA"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Le QC vise a atteindre des niveaux de qualite adequats en identifiant et corrigeant les defauts du produit. Le test est une partie importante du QC et aide a decouvrir ces defauts.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le QA se concentre sur l\'amelioration des processus avec une approche preventive pour eviter les erreurs et defauts, tandis que le test est une forme de QC.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Bien que le test soit important pour le QC, d\'autres techniques (non-test) sont aussi utilisees comme les methodes formelles, la simulation et le prototypage.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Le QA se concentre sur l\'amelioration des processus, pas sur la detection des defauts qui est le role du QC/test."},

{id:"B-3",exam:"B",lo:"FL-1.3.1",kl:"K2",pts:1,multi:false,chapter:1,
q:"Un des principes de test dit que les tests exhaustifs sont impossibles. Lequel des elements suivants est un exemple d'application de ce principe ?",
options:["Creer des cas de test couvrant toutes les sorties specifiees possibles","Documenter toutes les variations d'entree possibles et les prioriser","Commencer les tests le plus tot possible avec des revues et du test statique","Utiliser le partitionnement en equivalence et l'analyse des valeurs limites pour generer des cas de test"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 L\'utilisation du partitionnement en equivalence et de l\'analyse des valeurs limites pour generer des cas de test est une facon d\'appliquer le principe \"tests exhaustifs impossibles\" en derivant un sous-ensemble fini systematique de tous les cas de test possibles.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Tester tous les resultats attendus possibles ne resout pas le probleme car la relation entre entrees et resultats varie pour chaque objet de test, et il peut y avoir un nombre pratiquement infini de resultats possibles.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Documenter toutes les variations d\'entrees possibles serait impraticable car il y en a un nombre pratiquement infini pour les systemes non triviaux.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Commencer les tests tot avec les revues ne resout pas le probleme du nombre excessif de cas de test possibles. Le principe \"tests precoces\" concerne la correction precoce des defauts, pas la reduction du nombre de tests."},

{id:"B-4",exam:"B",lo:"FL-1.4.1",kl:"K2",pts:1,multi:false,chapter:1,
q:"Quelle activite de test implique de travailler avec les exigences de donnees de test, les conditions de test, les exigences d'environnement de test et les cas de test ?",
options:["Conception de test","Execution de test","Analyse de test","Implementation de test"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 La conception de test implique l\'utilisation des conditions de test pour creer des cas de test et d\'autres testware comme les exigences de donnees de test, les chartes de test pour le test exploratoire et les exigences d\'environnement de test.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 L\'execution des tests implique l\'execution des cas de test mais ne couvre pas directement les exigences de donnees de test, les exigences d\'environnement et les conditions de test.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 L\'analyse de test identifie les fonctionnalites a tester et definit les conditions de test, mais ne couvre pas les exigences de donnees de test ni les cas de test.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 L\'implementation des tests genere les procedures de test et les scripts, mais ne couvre pas les conditions de test."},

{id:"B-5",exam:"B",lo:"FL-1.4.2",kl:"K2",pts:1,multi:false,chapter:1,
q:"Lequel des elements suivants est le PLUS susceptible d'impacter la facon dont les tests sont effectues pour un objet de test donne ?",
options:["Le niveau d'experience moyen de l'equipe marketing","La connaissance des utilisateurs qu'un nouveau systeme est en cours de developpement","Le nombre d'annees d'experience des membres de l'equipe de test","La structure organisationnelle de l'utilisateur final pour une application de streaming musical"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 Le nombre d\'annees d\'experience des membres de l\'equipe de test de performance determine les capacites et connaissances (outils, types de defauts) qu\'ils appliqueront lors des tests.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 L\'experience moyenne de l\'equipe marketing n\'est pas susceptible d\'affecter la facon dont les tests sont effectues pour un objet de test donne.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Le niveau de connaissance des utilisateurs qu\'un systeme est en cours de construction n\'est pas susceptible d\'affecter la facon dont les tests sont effectues.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 La structure organisationnelle des utilisateurs finaux varie et n\'a que peu d\'effet sur la facon dont les tests sont effectues."},

{id:"B-6",exam:"B",lo:"FL-1.4.4",kl:"K2",pts:1,multi:false,chapter:1,
q:"Laquelle des affirmations suivantes est un exemple CORRECT de la valeur de la tracabilite ?",
options:["La tracabilite entre les risques attenues et les cas de test reussis permet de determiner le niveau de risque residuel","La tracabilite entre les exigences utilisateur et les resultats de test permet de mesurer la progression du projet par rapport aux objectifs metier","La tracabilite entre les testeurs et les cas de test echoues permet de determiner le niveau de competence des testeurs","La tracabilite entre les risques identifies et les conditions de test permet de determiner quels risques meritent d'etre testes"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 La tracabilite entre les exigences utilisateur et les resultats de test fournit une indication des exigences testees et un moyen de mesurer la progression du projet par rapport aux objectifs metier.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 La tracabilite entre les risques attenues et les cas de test reussis fournit peu d\'informations car les risques attenues doivent deja avoir un cas de test reussi.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les cas de test echoues ne fournissent pas une indication claire des competences des testeurs et cette mesure peut etre contre-productive.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 La tracabilite entre risques identifies et conditions de test aide a determiner les conditions supplementaires a ecrire, pas la progression."},

{id:"B-7",exam:"B",lo:"FL-1.5.1",kl:"K2",pts:1,multi:false,chapter:1,
q:"Lequel des elements suivants est le PLUS susceptible d'etre un exemple d'utilisation d'une competence generique par un testeur ?",
options:["La connaissance approfondie des jeux video du testeur lui a permis de bien s'entendre avec un developpeur","Le testeur etait un ancien pilote et pouvait mieux comprendre les criteres d'acceptation du systeme de controle d'helicoptere","Le testeur etait un ancien programmeur et a utilise ses competences pour mieux communiquer avec les analystes metier","Le testeur etait tres minutieux dans la generation methodique de cas de test avant sa session de test exploratoire"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Les connaissances du domaine permettent de comprendre et communiquer avec les utilisateurs finaux et representants metier. Un testeur ayant une experience de pilote apprecierait mieux les criteres d\'acceptation d\'un systeme de controle d\'helicoptere.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Une connaissance approfondie de jeux video pour bien s\'entendre avec un developpeur n\'est pas un exemple de competence generique utile aux testeurs.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les competences en programmation pourraient ameliorer l\'utilisation d\'outils de test mais n\'amelioreraient pas la communication avec les analystes metier.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Generer des cas de test AVANT le test exploratoire va a l\'encontre du principe du test exploratoire ou les cas sont generes pendant le test."},

{id:"B-8",exam:"B",lo:"FL-1.5.2",kl:"K1",pts:1,multi:false,chapter:1,
q:"Lequel des elements suivants est un avantage de l'approche equipe entiere ?",
options:["Elle permet aux membres de l'equipe d'assumer n'importe quel role a tout moment","Elle ne necessite qu'une seule equipe pour l'ensemble du projet","Elle integre des representants metier aux cotes des developpeurs","Elle genere une synergie d'equipe qui profite a l'ensemble du projet"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 En exploitant les competences diverses de chaque membre, l\'approche equipe entiere favorise une dynamique superieure, une communication robuste et une synergie benefique pour tout le projet.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 L\'approche equipe entiere ne signifie pas que chaque membre peut prendre n\'importe quel role a tout moment. Ils prennent generalement des roles dans lesquels ils sont competents.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 L\'approche s\'applique a une seule equipe (typiquement agile), elle ne couvre pas comment plusieurs equipes travaillent sur de grands projets.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 L\'approche n\'exige pas que chaque membre soit implique dans chaque decision importante. Le Product Owner n\'a pas besoin d\'etre implique dans chaque decision technique."},

{id:"B-9",exam:"B",lo:"FL-2.1.1",kl:"K2",pts:1,multi:false,chapter:2,
q:"Laquelle des affirmations suivantes concernant le SDLC choisi est CORRECTE ?",
options:["Si le developpement agile est utilise, l'automatisation des tests systeme remplace le besoin de tests de regression","Si un modele sequentiel est utilise, le test dynamique est typiquement restreint aux phases tardives","Si un modele iteratif est utilise, le test de composant est effectue manuellement par les developpeurs","Si un modele incremental est utilise, le test statique est fait dans les premiers increments et le dynamique dans les derniers"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Dans un modele sequentiel, au debut du SDLC aucun code n\'est disponible pour l\'execution, donc le test statique (revues) est effectue. Plus tard, quand le code est disponible, le test dynamique est possible.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 En agile, les livraisons frequentes necessitent des tests de regression extensifs qui ne peuvent pas etre remplaces par l\'automatisation des tests systeme seule.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 En developpement iteratif, les tests de composants peuvent etre utilises pour la regression et il y a un argument fort pour les automatiser, pas pour les executer manuellement par les developpeurs.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Dans les modeles incrementaux, le test statique ET dynamique a tous les niveaux est necessaire pour chaque increment livre."},

{id:"B-10",exam:"B",lo:"FL-2.1.2",kl:"K1",pts:1,multi:false,chapter:2,
q:"Laquelle des pratiques suivantes est une bonne pratique de test qui s'applique a tous les SDLC ?",
options:["Les testeurs doivent revoir les produits d'activite dans le cadre de la phase de developpement suivante","Les testeurs doivent revoir les produits d'activite des que les brouillons sont disponibles","Les testeurs doivent revoir les produits d'activite avant que l'analyse et la conception de test ne commencent","Les testeurs doivent revoir les produits d'activite immediatement apres leur publication"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Les testeurs devraient revoir les produits de travail des que des brouillons sont disponibles pour permettre le test precoce dans le cadre du shift-left.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Attendre la phase de developpement suivante pourrait entrainer un travail inutile sur des produits de travail non revus et defectueux.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les testeurs revoient generalement les produits de travail dans le cadre de l\'analyse de test, pas avant l\'analyse et la conception de test.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Attendre la publication signifie que les defauts trouvables par la revue seront dans le document publie."},

{id:"B-11",exam:"B",lo:"FL-2.1.3",kl:"K1",pts:1,multi:false,chapter:2,
q:"Lequel des elements suivants est un exemple d'approche test-first du developpement ?",
options:["Developpement dirige par les tests (TDD)","Developpement dirige par la couverture","Developpement dirige par la qualite","Developpement dirige par les fonctionnalites"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 Le TDD (Test-Driven Development) est un exemple bien connu d\'approche test-first du developpement.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Le \"Coverage-Driven Development\" n\'est pas un exemple correct d\'approche test-first.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Le \"Quality-Driven Development\" n\'est pas un exemple correct d\'approche test-first.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Le Feature-Driven Development est une methodologie agile basee sur les fonctionnalites, pas une approche test-first."},

{id:"B-12",exam:"B",lo:"FL-2.1.4",kl:"K2",pts:1,multi:false,chapter:2,
q:"Laquelle des affirmations suivantes concernant le DevOps est CORRECTE ?",
options:["L'integration continue encourage les developpeurs a soumettre du code sans completer les tests de composants","Pour des releases plus frequentes, de nombreux tests de regression automatises sont necessaires pour reduire le risque","Pour traiter developpeurs et operations de maniere egale, les testeurs allouent plus d'effort aux tests de release","Pour creer une synergie, les tests doivent devenir entierement automatises sans test manuel"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Le DevOps ameliore les tests via le feedback rapide, les tests de regression automatises et l\'approche shift-left. Les developpeurs doivent soumettre des tests de composants avec leur code dans le cadre de l\'integration continue.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Les developpeurs doivent completer les tests de composants dans l\'integration continue DevOps, pas l\'eviter.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les testeurs ne cherchent pas a traiter developpeurs et operations de maniere egale en passant plus de temps sur les tests de release.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les processus automatises CI/CD facilitent des environnements de test stables, mais il y a un risque de negliger l\'importance des tests manuels du point de vue utilisateur."},

{id:"B-13",exam:"B",lo:"FL-2.2.1",kl:"K2",pts:1,multi:false,chapter:2,
q:"Lequel des elements suivants est le PLUS susceptible d'etre effectue dans le cadre du test systeme ?",
options:["Test de securite d'un systeme de gestion de credit par une equipe de test independante","Test de l'interface d'un systeme de change avec un systeme bancaire externe","Test beta d'un systeme d'apprentissage a distance par des developpeurs de cours","Test des interactions entre l'interface utilisateur et la base de donnees d'un systeme RH"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 Les tests systeme examinent le comportement et les capacites du systeme complet, y compris les tests non fonctionnels comme les tests de securite. Ce type de test est souvent effectue par une equipe de test independante.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les tests d\'integration systeme examinent les interfaces avec d\'autres systemes et services externes.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les tests beta sont un type de test d\'acceptation effectue sur un site externe par des roles hors de l\'organisation de developpement.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les tests d\'integration de composants testent les interfaces et interactions entre les composants d\'un systeme."},

{id:"B-14",exam:"B",lo:"FL-2.2.3",kl:"K2",pts:1,multi:false,chapter:2,
q:"Laquelle des affirmations suivantes est CORRECTE ?",
options:["Les tests de regression augmentent en nombre tandis que les tests de confirmation diminuent","Les tests de regression sont crees quand l'objet est corrige, les tests de confirmation sont executes quand il est ameliore","Les tests de regression verifient que l'environnement operationnel reste inchange, les tests de confirmation verifient les changements","Les tests de regression concernent les effets indesirables dans le code inchange, les tests de confirmation concernent le code modifie"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Les tests de regression s\'assurent que les changements n\'ont pas d\'effets negatifs sur le logiciel inchange. Les tests de confirmation verifient qu\'un defaut a ete correctement corrige et concernent donc le code modifie.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le nombre de tests de regression et de confirmation augmente au fil du projet car de nouveaux tests sont necessaires pour chaque changement.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 C\'est l\'inverse : les tests de confirmation sont executes quand l\'objet est corrige, et les tests de regression quand l\'objet est modifie/ameliore.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les tests de regression verifient que les changements (y compris de l\'environnement operationnel) n\'ont pas d\'effets negatifs, ils ne verifient pas que l\'environnement reste inchange."},

{id:"B-15",exam:"B",lo:"FL-3.1.3",kl:"K2",pts:1,multi:false,chapter:3,
q:"Lequel des elements suivants est un exemple de defaut pouvant etre trouve par le test statique mais PAS par le test dynamique ?",
options:["Manque d'utilisabilite fournie par l'interface utilisateur","Code sans chemin l'atteignant","Temps de reponse mediocres pour la plupart des utilisateurs attendus","Fonctionnalites requises non implementees dans le code"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Une revue de code peut detecter du code inaccessible, tandis que les tests dynamiques ne peuvent executer que du code accessible et ne peuvent pas determiner qu\'un code est inaccessible sans tester toutes les combinaisons d\'entrees.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Un manque d\'utilisabilite peut etre detecte a la fois par une revue avec checklist et par des tests dynamiques avec des utilisateurs typiques.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les temps de reponse lents sont difficiles a determiner sans executer le code, donc le test dynamique est mieux adapte que le test statique pour ce type de defaut.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Des fonctionnalites manquantes peuvent etre detectees a la fois par une revue de code et par des tests dynamiques."},

{id:"B-16",exam:"B",lo:"FL-3.2.1",kl:"K1",pts:1,multi:false,chapter:3,
q:"Lequel des elements suivants est un avantage du feedback precoce et frequent des parties prenantes ?",
options:["Les managers savent quels developpeurs sont moins productifs","Il permet aux chefs de projet de prioriser les interactions avec les parties prenantes","Il facilite la communication precoce des problemes de qualite potentiels","Les utilisateurs comprennent mieux pourquoi la livraison est retardee"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 Obtenir un feedback precoce et frequent des parties prenantes facilite la communication precoce des problemes de qualite potentiels, previent les malentendus sur les exigences et garantit que les changements sont compris et implementes plus tot.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le feedback vient des parties prenantes (representants metier, utilisateurs finaux), pas des developpeurs, donc il n\'informe pas les managers sur la productivite des developpeurs.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Le feedback precoce et frequent n\'est pas utilise par les chefs de projet pour prioriser leurs interactions avec les parties prenantes.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Idealement il ne devrait pas y avoir de delai. De plus, le feedback vient DES parties prenantes (pas vers elles), donc fournir du feedback ne les aidera pas a mieux comprendre."},

{id:"B-17",exam:"B",lo:"FL-3.2.2",kl:"K2",pts:1,multi:false,chapter:3,
q:"Descriptions de taches :\n1. Les caracteristiques de qualite et criteres de sortie sont selectionnes\n2. Tout le monde a acces au produit d'activite\n3. Les anomalies sont identifiees\n4. Les anomalies sont discutees\nActivites de revue : A. Revue individuelle  B. Initiation de la revue  C. Planification  D. Communication et analyse\nQuelle correspondance est la MEILLEURE ?",
options:["1B, 2C, 3D, 4A","1B, 2D, 3C, 4A","1C, 2A, 3B, 4D","1C, 2B, 3A, 4D"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 L\'association correcte est : 1C (Planification), 2B (Lancement de revue), 3A (Revue individuelle), 4D (Communication et analyse). Les criteres de sortie sont selectionnes lors de la planification, l\'acces est assure lors du lancement, les anomalies sont identifiees lors de la revue individuelle, et analysees lors de la communication.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Les appariements ne correspondent pas aux activites du processus de revue.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les appariements ne correspondent pas aux activites du processus de revue.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les appariements ne correspondent pas aux activites du processus de revue."},

{id:"B-18",exam:"B",lo:"FL-3.2.3",kl:"K1",pts:1,multi:false,chapter:3,
q:"Roles dans les revues :\n1. Scribe  2. Responsable de revue  3. Facilitateur  4. Manager\nResponsabilites :\nA. Assure le bon deroulement des reunions et un environnement de revue sur\nB. Enregistre les informations de revue\nC. Decide ce qui doit etre revise et fournit les ressources\nD. Prend la responsabilite globale de la revue\nQuelle correspondance est la MEILLEURE ?",
options:["1A, 2B, 3D, 4C","1A, 2C, 3B, 4D","1B, 2D, 3A, 4C","1B, 2D, 3C, 4A"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 L\'association correcte est : 1B (Scribe), 2D (Responsable de revue), 3A (Moderateur/Facilitateur), 4C (Management). Le scribe enregistre les informations, le responsable organise la revue, le moderateur assure le bon deroulement, le management decide ce qui doit etre revu.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Les appariements roles-descriptions ne sont pas corrects.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les appariements roles-descriptions ne sont pas corrects.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les appariements roles-descriptions ne sont pas corrects."},

{id:"B-19",exam:"B",lo:"FL-4.1.1",kl:"K2",pts:1,multi:false,chapter:4,
q:"Laquelle des affirmations suivantes decrit le MIEUX la difference entre le test de table de decision et le test des branches ?",
options:["En table de decision, les cas de test derivent des instructions de decision du code. En branche, du flux de controle.","En table de decision, les cas de test derivent de la specification metier. En branche, de l'anticipation de defauts potentiels.","En table de decision, les cas de test derivent du flux de controle. En branche, de la specification metier.","En table de decision, les cas de test sont independants de l'implementation. En branche, ils ne peuvent etre crees qu'apres l'implementation."],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Le test par table de decision est une technique boite noire basee sur l\'analyse du comportement specifie sans reference a la structure interne. Le test des branches est une technique boite blanche basee sur l\'analyse de la structure interne du code.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le test par table de decision est une technique boite noire, pas boite blanche. Les cas de test ne sont pas bases sur les decisions du code source.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 L\'anticipation de defauts potentiels est utilisee en prediction d\'erreurs (technique basee sur l\'experience), pas dans le test des branches.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Le test par table de decision est base sur la logique metier (boite noire), et le test des branches est derive du code source (boite blanche), pas de la specification."},

{id:"B-20",exam:"B",lo:"FL-4.2.1",kl:"K3",pts:1,multi:false,chapter:4,
q:"La chaine de lavage auto TestWash : le systeme augmente le compteur a chaque lavage. Pour chaque 10e lavage : 10% de remise. Pour chaque 20e lavage : 50% de remise au total.\nQuel ensemble de donnees (numeros de lavage) atteint la plus haute couverture EP ?",
options:["19, 20, 30","11, 12, 20","1, 10, 50","10, 29, 30, 31"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 19 couvre la partition \"pas de reduction\", 20 couvre la partition \"50% de reduction\" et 30 couvre la partition \"10% de reduction\". Ces trois valeurs couvrent les trois partitions d\'equivalence valides.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 11 et 12 couvrent la partition \"pas de reduction\", 20 couvre \"50% de reduction\", mais la partition \"10%\" n\'est pas couverte. Seulement 2 partitions sur 3.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 1 couvre \"pas de reduction\", 10 et 50 couvrent \"10% de reduction\", mais \"50% de reduction\" n\'est pas couverte. Seulement 2 partitions sur 3.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 29 et 31 couvrent \"pas de reduction\", 10 et 30 couvrent \"10% de reduction\", mais \"50% de reduction\" n\'est pas couverte. Seulement 2 partitions sur 3."},

{id:"B-21",exam:"B",lo:"FL-4.2.2",kl:"K3",pts:1,multi:false,chapter:4,
q:"Vous testez un formulaire de verification de longueur de mot de passe. Longueur correcte : entre 6 et 12 caracteres inclus. Vous avez deja 100% de couverture BVA 2 valeurs. Quelles longueurs supplementaires pour atteindre 100% BVA 3 valeurs ?",
options:["4, 5, 13, 14","7, 11","1, 5, 13","1, 4, 7, 11, 14"],
correct:[1],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Le domaine de longueur de mot de passe a 3 partitions : trop court {0-5}, correct {6-12}, trop long {13+}. Pour la BVA 3 valeurs il faut tester : 0,1,4,5,6,7,11,12,13,14. La BVA 2 valeurs couvre deja 0,5,6,12,13. Les longueurs supplementaires pour passer de 2 a 3 valeurs sont : 1, 4, 7, 11 et 14.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 L\'ensemble de valeurs ne correspond pas aux longueurs supplementaires correctes.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 L\'ensemble de valeurs ne correspond pas aux longueurs supplementaires correctes.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 L\'ensemble de valeurs ne correspond pas aux longueurs supplementaires correctes."},

{id:"B-22",exam:"B",lo:"FL-4.2.3",kl:"K3",pts:1,multi:false,chapter:4,
scenario:'Table de decision pour le risque d\'atherosclerose :<br><br><table class="q-table"><tr><th>Conditions</th><th>R1</th><th>R2</th><th>R3</th><th>R4</th><th>R5</th></tr><tr><td>Cholesterol (mg/dl)</td><td>≤124</td><td>125-200</td><td>≤124</td><td>125-200</td><td>≥201</td></tr><tr><td>Pression arterielle (mm Hg)</td><td>≤140</td><td>≤140</td><td>&gt;140</td><td>&gt;140</td><td>-</td></tr><tr><th>Niveau de risque</th><th>Tres bas</th><th>Bas</th><th>Moyen</th><th>Haut</th><th>Tres haut</th></tr></table><br>Cas de test :<br>TC1: Cholesterol=125, Pression=141<br>TC2: Cholesterol=200, Pression=201<br>TC3: Cholesterol=124, Pression=201<br>TC4: Cholesterol=109, Pression=200<br>TC5: Cholesterol=201, Pression=140',
q:"Quelle est la couverture de la table de decision ?",
options:["40%","60%","80%","100%"],
correct:[2],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Il y a 5 colonnes dans la table de decision. TC1 et TC2 couvrent la Regle 4, TC3 et TC4 couvrent la Regle 2, TC5 couvre la Regle 5. Ces 5 cas de test couvrent 3 colonnes sur 5, soit (3/5)*100% = 60%.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le calcul de couverture ne donne pas ce resultat.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Le calcul de couverture ne donne pas ce resultat.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Le calcul de couverture ne donne pas ce resultat."},

{id:"B-23",exam:"B",lo:"FL-4.2.4",kl:"K3",pts:1,multi:false,chapter:4,
scenario:'Systeme de stockage avec variable N (0 a 3). Evenements : Add (ajoute 1) et Remove (retire 1).<br><br><svg viewBox="0 0 480 120" xmlns="http://www.w3.org/2000/svg" style="max-width:480px;font-family:sans-serif;font-size:12px"><circle cx="60" cy="60" r="30" fill="#1e3a5f" stroke="#0f172a" stroke-width="2"/><text x="60" y="65" text-anchor="middle" fill="white" font-weight="bold">N=0</text><circle cx="180" cy="60" r="30" fill="#2563eb" stroke="#1e3a5f" stroke-width="2"/><text x="180" y="65" text-anchor="middle" fill="white" font-weight="bold">N=1</text><circle cx="300" cy="60" r="30" fill="#2563eb" stroke="#1e3a5f" stroke-width="2"/><text x="300" y="65" text-anchor="middle" fill="white" font-weight="bold">N=2</text><circle cx="420" cy="60" r="30" fill="#2563eb" stroke="#1e3a5f" stroke-width="2"/><text x="420" y="65" text-anchor="middle" fill="white" font-weight="bold">N=3</text><line x1="93" y1="50" x2="147" y2="50" stroke="#16a34a" stroke-width="2" marker-end="url(#ab)"/><text x="120" y="43" text-anchor="middle" fill="#16a34a" font-size="10">Add</text><line x1="147" y1="70" x2="93" y2="70" stroke="#dc2626" stroke-width="2" marker-end="url(#ab)"/><text x="120" y="88" text-anchor="middle" fill="#dc2626" font-size="10">Rem</text><line x1="213" y1="50" x2="267" y2="50" stroke="#16a34a" stroke-width="2" marker-end="url(#ab)"/><text x="240" y="43" text-anchor="middle" fill="#16a34a" font-size="10">Add</text><line x1="267" y1="70" x2="213" y2="70" stroke="#dc2626" stroke-width="2" marker-end="url(#ab)"/><text x="240" y="88" text-anchor="middle" fill="#dc2626" font-size="10">Rem</text><line x1="333" y1="50" x2="387" y2="50" stroke="#16a34a" stroke-width="2" marker-end="url(#ab)"/><text x="360" y="43" text-anchor="middle" fill="#16a34a" font-size="10">Add</text><line x1="387" y1="70" x2="333" y2="70" stroke="#dc2626" stroke-width="2" marker-end="url(#ab)"/><text x="360" y="88" text-anchor="middle" fill="#dc2626" font-size="10">Rem</text><defs><marker id="ab" markerWidth="8" markerHeight="6" refX="8" refY="3" orient="auto"><path d="M0,0 L8,3 L0,6" fill="#334155"/></marker></defs></svg><br>7 transitions valides : N=0→N=1, N=1→N=0, N=1→N=2, N=2→N=1, N=2→N=3, N=3→N=2, plus les evenements ignores aux limites.',
q:"Lequel des cas de test (sequences d'evenements) atteint le plus haut niveau de couverture des transitions valides ?",
options:["Add, Remove, Add, Add, Add","Add, Add, Add, Add, Remove, Remove","Add, Add, Add, Remove, Remove","Add, Add, Add, Remove, Add"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 Le test c) peut etre ecrit comme E1,E2,E4,E5,E3, couvrant 5 transitions valides sur 5, soit 100% de couverture des transitions valides.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le test a) couvre 4 transitions sur 5 (80% de couverture).<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Le test b) est infaisable car apres 3 \"Add\" le systeme est en etat FULL et aucune transition \"Add\" n\'est valide.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Le test d) couvre 4 transitions sur 5 (80% de couverture)."},

{id:"B-24",exam:"B",lo:"FL-4.3.1",kl:"K2",pts:1,multi:false,chapter:4,
q:"Vous executez deux cas de test T1 et T2 sur le meme code. T1 atteint 40% de couverture des instructions et T2 atteint 65%.\nLaquelle des phrases suivantes est necessairement vraie ?",
options:["La suite T1+T2 atteint 105% de couverture","Il existe au moins une instruction executee par T1 et T2","Au moins 5% des instructions sont non executables","La suite T1+T2 atteint une couverture complete des branches"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Si les instructions executees par T1 et T2 etaient disjointes, la couverture serait 105%, ce qui est impossible. Donc au moins 5% des instructions executables ont ete executees par les deux tests T1 et T2.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 La couverture est toujours definie comme un pourcentage des elements couverts, elle ne peut pas depasser 100%.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 La couverture des instructions ne nous dit rien sur le nombre d\'instructions non executables dans le code.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Meme si une suite de tests atteint 100% de couverture des instructions, cela n\'implique pas 100% de couverture des branches."},

{id:"B-25",exam:"B",lo:"FL-4.3.2",kl:"K2",pts:1,multi:false,chapter:4,
q:"La metrique de couverture des branches est definie comme BCov = (X / Y) * 100%. Que representent X et Y ?",
options:["X = nombre de resultats de decision exerces, Y = nombre total de resultats de decision","X = nombre de branches conditionnelles exercees, Y = nombre total de branches","X = nombre de branches exercees, Y = nombre total de branches","X = nombre de branches conditionnelles exercees, Y = nombre total de resultats de decision"],
correct:[0],
justification:"<strong>\u2713 c) Correct</strong> \u2014 La couverture des branches est mesuree comme le nombre de branches exercees par les cas de test divise par le nombre total de branches, exprime en pourcentage.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Un resultat de decision est une branche conditionnelle. Pour le test des branches, X compte non seulement les branches conditionnelles mais aussi les inconditionnelles.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 La couverture des branches compte les branches conditionnelles ET inconditionnelles, pas seulement les conditionnelles.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 X et Y ne comptent que les branches conditionnelles et ne prennent pas en compte les branches inconditionnelles."},

{id:"B-26",exam:"B",lo:"FL-4.4.2",kl:"K2",pts:1,multi:true,chapter:4,
q:"Lesquelles des affirmations suivantes fournissent la MEILLEURE justification pour utiliser le test exploratoire ?",
options:["Les testeurs n'ont pas eu assez de temps pour la conception et l'execution des tests","La strategie de test existante exige des techniques formelles de boite noire","La specification est ecrite dans un langage formel traitable par un outil","Les testeurs sont membres d'une equipe agile et ont de bonnes competences en programmation","Les testeurs ont de l'experience dans le domaine metier et de bonnes competences analytiques"],
correct:[0,4],
justification:"<strong>\u2713 a, e) Correct</strong> \u2014 a) Le test exploratoire est utile quand il y a peu de specifications ou une forte pression sur le calendrier. e) Le test exploratoire est plus efficace si le testeur est experimente, a des connaissances du domaine et des competences analytiques, de la curiosite et de la creativite.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Le test exploratoire n\'est pas une technique de test boite noire.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Le test exploratoire est utile quand les specifications sont mal ecrites, pas quand elles sont bien ecrites.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les competences en programmation n\'ont rien a voir avec le test exploratoire en principe."},

{id:"B-27",exam:"B",lo:"FL-4.4.3",kl:"K2",pts:1,multi:false,chapter:4,
q:"Lequel des elements suivants convient le MIEUX comme element de checklist dans le test base sur une checklist ?",
options:["Le developpeur a fait une erreur dans le code","La couverture des instructions depasse 85%","Le programme fonctionne correctement pour les exigences fonctionnelles et non fonctionnelles","Les messages d'erreur sont ecrits dans un langage comprehensible par l'utilisateur"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 C\'est un exemple de condition de test qui peut etre verifiee par un humain dans une checklist.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Les checklists devraient contenir des conditions de test a verifier, pas des exemples d\'erreurs. Cette description d\'erreur est trop generale.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les checklists ne devraient pas contenir d\'elements mieux adaptes comme criteres de sortie. C\'est un exemple de critere de sortie.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les checklists ne devraient pas contenir d\'elements trop generaux. Ceci est un element tres general qui decrit pratiquement un objectif de test."},

{id:"B-28",exam:"B",lo:"FL-4.5.2",kl:"K2",pts:1,multi:false,chapter:4,
q:"Considerez le critere d'acceptation suivant pour une user story (proprietaire de magasin en ligne) :\nGiven que l'utilisateur est connecte et sur la page d'accueil,\nWhen l'utilisateur clique sur 'Ajouter un article',\nThen le formulaire 'Creer un article' apparait,\nAnd l'utilisateur peut saisir un nom et un prix.\nDans quel format ce critere d'acceptation est-il ecrit ?",
options:["Oriente regles","Oriente scenarios","Oriente produit","Oriente processus"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 C\'est un format Given/When/Then, qui est un format oriente scenario pour les criteres d\'acceptation.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le format oriente regles inclut des listes de verification a puces ou des tableaux de correspondance entree-sortie. Given/When/Then est un format oriente scenario.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Il n\'existe pas de format \"oriente produit\" pour les criteres d\'acceptation.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Il n\'existe pas de format \"oriente processus\" pour les criteres d\'acceptation."},

{id:"B-29",exam:"B",lo:"FL-4.5.3",kl:"K3",pts:1,multi:false,chapter:4,
q:"Votre equipe analyse la user story suivante :\nEn tant que client enregistre, je veux pouvoir voir mes commandes precedentes pour suivre mes achats.\nQuel cas de test ne sera PAS pertinent ?",
options:["Le client se connecte et clique sur 'Voir l'historique' - le systeme affiche toutes les commandes precedentes","Le client clique sur une commande - le systeme affiche les articles achetes avec prix et quantites","Le client clique sur 'Trier croissant' - le systeme trie l'historique par numero de commande","Un client non enregistre s'inscrit avec une adresse email valide - le systeme accepte l'inscription"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Ce cas de test est lie au processus d\'inscription, qui n\'est pas aborde dans la user story. La user story concerne la consultation des commandes precedentes.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Ce cas de test est lie a la consultation des commandes precedentes dans l\'historique, ce qui correspond a la user story.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Ce cas de test est lie a la consultation des commandes precedentes.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Ce cas de test est lie a la consultation des commandes precedentes dans l\'historique."},

{id:"B-30",exam:"B",lo:"FL-5.1.3",kl:"K2",pts:1,multi:false,chapter:5,
q:"Votre equipe suit un processus de pipeline de livraison DevOps. Les 3 premieres etapes sont :\n(1) Developpement du code\n(2) Soumission du code dans un systeme de controle de version et fusion dans la branche 'test'\n(3) Execution des tests de composants\nQu'est-ce qui convient le MIEUX comme critere d'entree pour l'etape (2) ?",
options:["L'analyse statique ne retourne aucun avertissement de haute severite","Le systeme de controle de version ne rapporte aucun conflit lors de la fusion","Les tests de composants sont compiles et prets a etre executes","La couverture des instructions est d'au moins 80%"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 C\'est quelque chose qui peut (et devrait) etre verifie avant que le code ne soit soumis au controle de version.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 C\'est quelque chose qui peut etre verifie apres la soumission et la fusion du code (rapports de conflits de fusion).<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Cela correspond mieux a un critere d\'entree pour l\'etape 3.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Cela correspond mieux a un critere de sortie pour l\'etape 3."},

{id:"B-31",exam:"B",lo:"FL-5.1.4",kl:"K3",pts:1,multi:false,chapter:5,
scenario:'Vous estimez l\'effort de test en utilisant les ratios. Donnees historiques :<br><br><table class="q-table"><tr><th>Projet</th><th>Effort Dev ($)</th><th>Effort Test ($)</th></tr><tr><td>P1</td><td>800 000</td><td>40 000</td></tr><tr><td>P2</td><td>1 200 000</td><td>130 000</td></tr><tr><td>P3</td><td>600 000</td><td>70 000</td></tr><tr><td>P4</td><td>1 000 000</td><td>120 000</td></tr></table><br>L\'effort de developpement estime pour le nouveau projet est de 800 000$.',
q:"Quelle est votre estimation de l'effort de test ?",
options:["40 000$","80 000$","81 250$","82 500$"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 L\'effort moyen de developpement est 900 000$ et l\'effort moyen de test est 90 000$. Le ratio moyen test/developpement est 1:10, soit 10%. Donc pour un effort de developpement de 800 000$, l\'effort de test estime est 10% * 800 000$ = 80 000$.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le calcul ne donne pas ce resultat.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Le calcul ne donne pas ce resultat.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Le calcul ne donne pas ce resultat."},

{id:"B-32",exam:"B",lo:"FL-5.1.5",kl:"K3",pts:1,multi:false,chapter:5,
q:"Vous testez une application web (SEARCH, VIEW, ADD, ORDER). 7 cas de test avec priorites et dependances logiques.\nSEARCH doit etre teste avant VIEW, VIEW avant ADD, ADD avant ORDER.\nQuel cas de test doit etre execute en quatrieme ?",
options:["TC3","TC1","TC7","TC2"],
correct:[0],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Les dependances logiques imposent SEARCH-VIEW-ADD avant ORDER. La priorite la plus haute va au produit B (TC6,TC4). L\'ordre complet est : TC2-TC4-TC6-TC1-TC3-TC5-TC7.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 TC1 doit etre execute avant TC3 selon les dependances.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 TC7 devrait etre le dernier a etre execute, pas avant.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Le produit B (priorite plus haute) doit etre execute avant le produit A."},

{id:"B-33",exam:"B",lo:"FL-5.1.7",kl:"K2",pts:1,multi:false,chapter:5,
q:"Selon le modele des quadrants de test, lequel des elements suivants appartient au quadrant Q1 ('technologie' et 'soutien equipe') ?",
options:["Test d'utilisabilite","Test fonctionnel","Test d'acceptation utilisateur","Test d'integration de composants"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Les tests d\'integration de composants sont des tests orientes technologie qui supportent l\'equipe (guident le developpement) (Q1).<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Les tests d\'utilisabilite sont des tests orientes metier qui critiquent le produit (Q3).<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les tests fonctionnels sont des tests orientes metier (Q2).<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les tests d\'acceptation utilisateur sont des tests orientes metier qui critiquent le produit (Q3)."},

{id:"B-34",exam:"B",lo:"FL-5.2.4",kl:"K2",pts:1,multi:false,chapter:5,
q:"Risques donnes :\n1. Implementation de boucle inefficace causant des reponses lentes\n2. Les consommateurs changent leurs preferences\n3. Inondation de la salle serveur\n4. Les patients au-dessus d'un certain age recoivent des rapports inexacts\nActivites d'attenuation : A. Acceptation  B. Test de performance  C. BVA  D. Transfert de risque\nQuelle correspondance est la MEILLEURE ?",
options:["1C, 2D, 3A, 4B","1B, 2D, 3A, 4C","1B, 2A, 3D, 4C","1C, 2A, 3D, 4B"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 Les combinaisons correctes sont : 1B (temps de reponse longs - tests de performance), 2A (changements de preferences consommateurs - accepter le risque), 3D (inondation du serveur - transferer le risque via assurance), 4C (rapports inexacts pour certains ages - technique BVA).<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Les appariements risque-attenuation ne sont pas corrects.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les appariements risque-attenuation ne sont pas corrects.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les appariements risque-attenuation ne sont pas corrects."},

{id:"B-35",exam:"B",lo:"FL-5.3.1",kl:"K1",pts:1,multi:false,chapter:5,
q:"Lequel des elements suivants est une metrique de qualite produit ?",
options:["Temps moyen de defaillance (MTTF)","Nombre de defauts trouves","Couverture des exigences","Pourcentage de detection de defauts"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 Les metriques de qualite produit mesurent les caracteristiques de qualite. Le temps moyen avant defaillance (MTBF) mesure la maturite, c\'est donc une metrique de qualite produit.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 C\'est un exemple de metrique de defauts, pas de qualite produit.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 C\'est un exemple de metrique de couverture, pas de qualite produit.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 C\'est un exemple de metrique de defauts, pas de qualite produit."},

{id:"B-36",exam:"B",lo:"FL-5.3.3",kl:"K2",pts:1,multi:false,chapter:5,
q:"Vous etes membre d'une equipe de test en Amerique du Nord, developpant un produit pour un client en Europe. Equipe agile, approche DevOps, pipeline CI/CD.\nQuel est le moyen de communication le MOINS efficace pour rapporter la progression des tests au client ?",
options:["Face-a-face","Tableaux de bord","Email","Videoconference"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 Le client est dans un lieu et fuseau horaire differents, donc la communication face a face peut etre difficile, ce qui est le plus grand defi de communication.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les tableaux de bord sont generalement disponibles a tout moment, donc la difference de fuseau horaire est moins genante que la communication verbale en face a face.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Bien que le decalage horaire entre l\'Europe et l\'Amerique cause des inconvenients, ce n\'est pas aussi impactant que la communication face a face.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les outils de videoconference sont pratiques et moins contraignants que la communication verbale face a face."},

{id:"B-37",exam:"B",lo:"FL-5.4.1",kl:"K2",pts:1,multi:false,chapter:5,
q:"Lequel des elements suivants decrit le MIEUX un exemple de support de la gestion de configuration (CM) aux tests ?",
options:["Avec le numero de version de l'environnement, le CM peut recuperer les versions des bibliotheques, stubs et drivers","Avec les valeurs d'entree, le CM peut executer les cas de test et calculer la couverture","Avec la date d'achat d'une licence, le CM genere automatiquement des infos sur l'expiration","Avec le numero de version du cas de test, le CM peut generer automatiquement les donnees de test"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 Pour un element de configuration complexe (ex: environnement de test), la gestion de configuration enregistre les elements constitutifs, leurs relations et versions.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les outils de CM n\'executent pas de cas de test et ne calculent pas la couverture.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Un outil de CM n\'est pas un outil de gestion de licences.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les outils de CM ne generent pas de donnees de test."},

{id:"B-38",exam:"B",lo:"FL-5.5.1",kl:"K3",pts:1,multi:false,chapter:5,
q:"Vous testez une fonction de tri. Le log montre :\nTC3: Input 8 7 3 7 1, Output 1 3 7 8: ECHEC\nTC4: Input -2 -2 -2 -3 -3, Output -3 -2: ECHEC\nTC5: Input 0 -2 0 3 4 4, Output -2 0 3 4: ECHEC\nQuelle est la MEILLEURE description de la defaillance pour un rapport de defaut ?",
options:["Le systeme ne parvient pas a trier plusieurs ensembles de nombres","Le systeme semble ignorer les doublons lors du tri","Le systeme ne parvient pas a trier les nombres negatifs","TC3, TC4 et TC5 ont des defauts et doivent etre corriges"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 D\'apres les resultats, le systeme semble ignorer les doublons et trier la liste sans les repetitions. C\'est probablement la cause des echecs de TC3, TC4, TC5. Cette information peut aider le developpeur a trouver et corriger le defaut plus efficacement.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Bien que la phrase soit vraie, elle n\'apporte pas beaucoup de valeur au developpeur.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Le systeme n\'echoue pas dans le tri des nombres negatifs. Le probleme est plutot l\'ignorance des doublons.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les cas de test TC3, TC4 et TC5 echouent, mais nous ne savons pas que les cas de test eux-memes ont des defauts."},

{id:"B-39",exam:"B",lo:"FL-6.1.1",kl:"K2",pts:1,multi:false,chapter:6,
q:"Descriptions :\n1. Support du suivi de workflow\n2. Faciliter la communication\n3. Machines virtuelles\n4. Support des revues\nCategories d'outils : A. Outils de test statique  B. Outils de scalabilite et deploiement  C. Outils DevOps  D. Outils de collaboration\nQuelle correspondance est la MEILLEURE ?",
options:["1A, 2B, 3C, 4D","1B, 2D, 3C, 4A","1C, 2D, 3B, 4A","1D, 2C, 3A, 4B"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 L\'association correcte est : 1C (outils DevOps), 2D (outils de collaboration), 3B (outils de scalabilite et deploiement), 4A (outils de test statique).<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Les appariements categories-descriptions ne sont pas corrects.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les appariements categories-descriptions ne sont pas corrects.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les appariements categories-descriptions ne sont pas corrects."},

{id:"B-40",exam:"B",lo:"FL-6.2.1",kl:"K1",pts:1,multi:false,chapter:6,
q:"Lequel des elements suivants est le PLUS susceptible d'etre un avantage de l'automatisation des tests ?",
options:["Elle fournit des mesures de couverture trop complexes pour les humains","Elle partage la responsabilite des tests avec le fournisseur d'outils","Elle supprime le besoin de pensee critique lors de l'analyse des resultats","Elle genere des cas de test a partir de l'analyse du code du programme"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 L\'automatisation des tests peut fournir des mesures trop complexes pour etre derivees par des humains, comme les mesures de couverture boite blanche pour tout code non trivial.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 En utilisant des outils de test, la responsabilite n\'est PAS partagee avec le fournisseur de l\'outil car c\'est la responsabilite du testeur.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les testeurs doivent toujours appliquer une reflexion critique pour analyser les anomalies dans les resultats de test et determiner leur cause probable.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Ni les testeurs ni les outils ne peuvent generer des cas de test simplement a partir de l\'analyse du code car le code ne fournit pas d\'informations sur les resultats attendus."},

// ========== EXAM C: Questions 1-40 ==========
{id:"C-1",exam:"C",lo:"FL-1.1.1",kl:"K1",pts:1,multi:false,chapter:1,
q:"Lequel des elements suivants est un objectif de test typique ?",
options:["Valider que les exigences documentees sont satisfaites","Provoquer des defaillances et identifier des defauts","Initier des erreurs et identifier les causes racines","Verifier que l'objet de test repond aux attentes des utilisateurs"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Provoquer des defaillances et identifier des defauts est probablement l\'objectif le plus courant du test dynamique.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 \"Valider\" que les exigences documentees sont remplies est incorrect car la validation concerne les besoins des utilisateurs. Il faudrait dire \"verifier\".<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les testeurs ne declenchent pas d\'erreurs, ils essaient de provoquer des defaillances. Les erreurs sont faites par les developpeurs. L\'identification des causes racines fait partie du debogage, une activite separee du test.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 \"Verifier\" que l\'objet de test repond aux attentes des utilisateurs est incorrect car la verification concerne les exigences specifiees. Il faudrait dire \"valider\"."},

{id:"C-2",exam:"C",lo:"FL-1.1.2",kl:"K2",pts:1,multi:false,chapter:1,
q:"Laquelle des affirmations suivantes decrit le MIEUX la difference entre test et debogage ?",
options:["Le test cause des defaillances tandis que le debogage corrige les defaillances","Le test est une activite negative tandis que le debogage est positif","Le test determine que des defauts existent tandis que le debogage supprime les defauts","Le test trouve la cause des defauts tandis que le debogage corrige la cause"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 Le test determine que des defauts existent soit directement par observation lors des revues (ou par un outil en analyse statique), soit indirectement en provoquant une defaillance en test dynamique. Le debogage est une activite separee realisee par les developpeurs.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le test dynamique provoque des defaillances (a partir desquelles les defauts peuvent etre localises et corriges). Cependant, le debogage ne corrige pas les defaillances, il corrige les defauts.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Le test et le debogage contribuent tous deux a ameliorer la qualite. Le debogage est generalement considere comme positif. Les cas de test positifs et negatifs sont tous deux possibles.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les causes des defauts sont typiquement des erreurs humaines. Le test ne trouve pas la cause des defauts et le debogage ne corrige pas les causes des defauts."},

{id:"C-3",exam:"C",lo:"FL-1.3.1",kl:"K2",pts:1,multi:false,chapter:1,
q:"L'illusion de l'absence de defauts est un principe de test. Lequel des elements suivants est un exemple d'application de ce principe ?",
options:["Expliquer qu'il n'est pas possible de montrer l'absence de defauts par le test","Aider les utilisateurs finaux a effectuer les tests d'acceptation","S'assurer qu'aucun defaut d'implementation ne subsiste dans le systeme livre","Modifier les tests qui ne causent pas de defaillances pour s'assurer que peu de defauts subsistent"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 En supportant l\'utilisateur final pour effectuer les tests d\'acceptation, il devrait etre possible de valider que le systeme repond aux besoins et attentes des utilisateurs, adressant ainsi le paradoxe de l\'absence de defauts.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Expliquer qu\'il n\'est pas possible de montrer l\'absence de defauts traite le principe \"le test montre la presence de defauts\", pas le paradoxe de l\'absence de defauts.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Il n\'est pas possible de garantir qu\'aucun defaut ne subsiste car le test montre la presence de defauts, pas leur absence.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Modifier les tests qui ne causent pas de defaillances adresse le principe de l\'usure des tests (tests wear out), pas le paradoxe de l\'absence de defauts."},

{id:"C-4",exam:"C",lo:"FL-1.4.1",kl:"K2",pts:1,multi:true,chapter:1,
q:"Quelles activites de test sont les PLUS susceptibles d'impliquer l'application de BVA et EP ?",
options:["Implementation de test","Conception de test","Execution de test","Pilotage de test","Analyse de test"],
correct:[1,4],
justification:"<strong>\u2713 b, e) Correct</strong> \u2014 b) La conception de test utilise les conditions de test pour creer des cas de test. e) L\'analyse de test implique l\'utilisation de techniques de test pour identifier les conditions de test. Les deux activites utilisent donc des techniques de test.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 L\'implementation des tests est principalement concernee par l\'assemblage des cas de test en procedures, pas par l\'utilisation de techniques de test.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 L\'execution des tests est principalement concernee par l\'execution des procedures de test, pas par l\'utilisation de techniques.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Le monitoring des tests est principalement concerne par le suivi de la progression, pas par l\'utilisation de techniques de test."},

{id:"C-5",exam:"C",lo:"FL-1.4.3",kl:"K2",pts:1,multi:false,chapter:1,
q:"Testware donnes :\n1. Elements de couverture  2. Demandes de changement  3. Planning d'execution  4. Conditions de test priorisees\nActivites : A. Analyse de test  B. Conception de test  C. Implementation de test  D. Completion de test\nQuelle correspondance est la MEILLEURE ?",
options:["1B, 2D, 3C, 4A","1B, 2D, 3A, 4C","1D, 2C, 3A, 4B","1D, 2C, 3B, 4A"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 L\'association correcte est : 1B (elements de couverture = conception de test), 2D (demandes de changement = cloture de test), 3C (planning d\'execution = implementation de test), 4A (conditions de test prioritisees = analyse de test).<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les appariements testware-activites ne sont pas corrects.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les appariements testware-activites ne sont pas corrects.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les appariements testware-activites ne sont pas corrects."},

{id:"C-6",exam:"C",lo:"FL-1.4.5",kl:"K2",pts:1,multi:false,chapter:1,
q:"Laquelle des affirmations suivantes concernant les differents roles de test est la PLUS susceptible d'etre CORRECTE ?",
options:["En agile, le role de gestion de test est la responsabilite principale de l'equipe, le role de test d'un individu externe","Le role de test est principalement responsable du pilotage et controle, le role de gestion de la planification et completion","En agile, les activites de gestion de test multi-equipes sont gerees par un test manager externe","Le role de gestion est responsable de l'analyse et la conception, le role de test de l'implementation et l'execution"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 En agile, certaines taches de gestion de test peuvent etre gerees par l\'equipe. Cependant, pour les activites qui s\'etendent sur plusieurs equipes, des test managers hors de l\'equipe de developpement peuvent effectuer ces taches.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le role de test n\'est pas principalement la responsabilite d\'un seul individu exterieur a l\'equipe. L\'approche equipe entiere est utilisee.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Le role de gestion de test est responsable de la planification, du monitoring et du controle des tests, pas seulement du monitoring et du controle.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Le role de gestion de test n\'est normalement pas responsable de l\'analyse et de la conception de test, ce sont des aspects techniques du role de test."},

{id:"C-7",exam:"C",lo:"FL-1.5.2",kl:"K1",pts:1,multi:false,chapter:1,
q:"Lequel des elements suivants est un avantage de l'approche equipe entiere ?",
options:["Equipes sans testeurs","Dynamique d'equipe amelioree","Membres d'equipe specialises","Tailles d'equipe plus grandes"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 En exploitant les competences diverses de chaque membre, l\'approche equipe entiere favorise une dynamique superieure, une communication robuste et un effet de synergie benefique pour le projet.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Les testeurs partagent leur expertise, collaborent avec les representants metier pour les tests d\'acceptation et avec les developpeurs pour la strategie de test et l\'automatisation.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 L\'approche permet a tout membre ayant les competences requises d\'effectuer n\'importe quelle tache, donc les specialistes ne sont pas un avantage specifique.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Il n\'y a pas de guide specifique sur la taille optimale des equipes et rien n\'indique que les equipes plus grandes sont meilleures."},

{id:"C-8",exam:"C",lo:"FL-1.5.3",kl:"K2",pts:1,multi:false,chapter:1,
q:"Laquelle des affirmations suivantes concernant l'independance du test est CORRECTE ?",
options:["Les testeurs independants trouveront des defauts grace a leur perspective technique differente, mais cela peut mener a une relation adversariale","La familiarite des developpeurs avec leur code signifie qu'ils ne trouvent que peu de defauts, mais les testeurs les trouveraient aussi","Le test independant necessite des testeurs externes, mais ils ont du mal a comprendre le domaine","Les testeurs externes sont plus independants, mais les testeurs internes sont plus susceptibles d'etre blames pour les retards"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 L\'avantage principal de l\'independance est que les testeurs sont plus susceptibles d\'identifier differents types de defaillances grace a leurs parcours et points de vue varies. L\'inconvenient principal est l\'isolation possible de l\'equipe de developpement.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 La familiarite du developpeur avec le code ne signifie pas qu\'il trouve rarement des defauts. Les parcours differents sont la raison pour laquelle testeurs et developpeurs trouvent des types de defauts differents.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Plusieurs niveaux d\'independance sont utilises dans les projets. Les testeurs n\'ont pas besoin de venir de l\'exterieur de l\'organisation.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les testeurs exterieurs a l\'equipe sont generalement plus independants mais aussi plus susceptibles d\'etre isoles et blames pour les retards."},

{id:"C-9",exam:"C",lo:"FL-2.1.2",kl:"K1",pts:1,multi:false,chapter:2,
q:"Laquelle des bonnes pratiques de test s'applique a tous les SDLC ?",
options:["Pour chaque niveau de test, il y a un niveau de developpement correspondant","Pour chaque objectif de test, il y a un objectif de developpement correspondant","Pour chaque activite de test, il y a une activite utilisateur correspondante","Pour chaque activite de developpement, il y a une activite de test correspondante"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Le controle qualite s\'applique a toutes les activites de developpement, ce qui signifie que chaque activite de developpement a une activite de test correspondante.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 On tente d\'assimiler les niveaux de test aux niveaux de developpement, mais il n\'y a pas de comprehension commune du terme \"niveau de developpement\".<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Chaque activite de developpement a une activite de test correspondante, mais les objectifs de test sont differents des objectifs de developpement.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 La meme symetrie ne s\'applique pas entre le test et les activites utilisateur. Pour certains systemes, il est meme difficile d\'identifier les utilisateurs finaux."},

{id:"C-10",exam:"C",lo:"FL-2.1.3",kl:"K1",pts:1,multi:false,chapter:2,
q:"Lequel des elements suivants est un exemple d'approche test-first du developpement ?",
options:["Developpement dirige par les tests de composants","Developpement dirige par les tests d'integration","Developpement dirige par les tests systeme","Developpement dirige par les tests d'acceptation (ATDD)"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 L\'ATDD (Acceptance Test-Driven Development) est un exemple bien connu d\'approche test-first du developpement.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le \"Component Test-Driven Development\" n\'est pas un exemple correct d\'approche test-first.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Le \"Integration Test-Driven Development\" n\'est pas un exemple correct d\'approche test-first.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Le \"System Test-Driven Development\" n\'est pas un exemple correct d\'approche test-first."},

{id:"C-11",exam:"C",lo:"FL-2.1.5",kl:"K2",pts:1,multi:false,chapter:2,
q:"Lequel des elements suivants fournit la MEILLEURE description du shift-left ?",
options:["Quand les developpeurs sont d'accord, les activites manuelles de la gauche du processus sont automatisees","Quand c'est rentable, les activites de test sont deplacees plus tot dans le SDLC pour reduire le cout total de la qualite","Quand ils ont du temps, les testeurs automatisent les tests de regression en commencant par les composants","Quand disponibles, les testeurs sont formes pour effectuer des taches tot dans le SDLC"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Le shift-left souligne l\'importance de commencer les tests plus tot dans le SDLC. Sa mise en oeuvre necessite une formation supplementaire et un effort accru en debut de SDLC, mais les economies globales devraient etre superieures.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Il n\'existe pas de \"cote gauche du processus de test\". Le shift-left concerne le deplacement des activites de test plus tot dans le SDLC.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les tests de composants automatises pour la regression sont generalement la responsabilite des developpeurs, pas des testeurs, et font partie de CI/CD, pas du shift-left specifiquement.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Former les testeurs a des taches en debut de SDLC soutient le shift-left, mais automatiser les activites de test plus tard dans le SDLC n\'en fait pas partie."},

{id:"C-12",exam:"C",lo:"FL-2.1.6",kl:"K2",pts:1,multi:false,chapter:2,
q:"Lequel des elements suivants est le MOINS susceptible de se produire suite a une retrospective ?",
options:["La qualite des futurs objets de test s'ameliore en identifiant des ameliorations dans les pratiques de developpement","L'efficacite des tests s'ameliore en accelerant la configuration des environnements par l'automatisation","La comprehension des utilisateurs finaux des processus de developpement et de test s'ameliore","Les scripts de test automatises sont ameliores grace au feedback des developpeurs"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 Les participants aux retrospectives incluent testeurs, developpeurs, architectes, product owners et analystes metier, mais les utilisateurs finaux sont rarement invites. Il est donc tres improbable qu\'ils en apprennent sur les processus via les retrospectives.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Un des objectifs des retrospectives est d\'identifier les ameliorations de processus potentielles, ce qui devrait resulter en une meilleure qualite. C\'est donc un resultat probable.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Un avantage des retrospectives inclut l\'amelioration de l\'efficacite des tests via les ameliorations de processus. C\'est donc un resultat probable.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Un avantage des retrospectives inclut l\'amelioration de la qualite du testware via les revues conjointes avec les developpeurs. C\'est donc un resultat probable."},

{id:"C-13",exam:"C",lo:"FL-2.2.1",kl:"K2",pts:1,multi:false,chapter:2,
q:"Quel niveau de test est le PLUS probablement effectue si le test est axe sur la validation et n'est pas effectue par des testeurs ?",
options:["Test de composant","Test d'integration de composants","Test d'integration systeme","Test d'acceptation"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Les tests d\'acceptation se concentrent sur la validation que le systeme repond aux besoins metier de l\'utilisateur et est pret pour le deploiement. Idealement, ces tests sont effectues par les utilisateurs finaux.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Les tests de composants testent les composants individuels en isolation et sont principalement de la verification. Ces tests sont generalement effectues par les developpeurs, pas les testeurs.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les tests d\'integration de composants testent les interfaces et interactions entre composants. Ces tests sont generalement effectues par les developpeurs.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les tests d\'integration systeme examinent les interfaces avec d\'autres systemes et sont principalement de la verification, pas de la validation par rapport aux besoins utilisateur."},

{id:"C-14",exam:"C",lo:"FL-2.2.3",kl:"K2",pts:1,multi:false,chapter:2,
q:"Le logiciel de navigation a ete mis a jour car il suggerait des itineraires enfreignant le code de la route. Quels tests seront effectues ?",
options:["Uniquement des tests de confirmation","Tests de confirmation puis tests de regression","Uniquement des tests de regression","Tests de regression puis tests de confirmation"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Les tests de confirmation verifient que les mises a jour ont ete correctement implementees, puis les tests de regression verifient qu\'aucun defaut n\'a ete introduit dans les parties inchangees du systeme.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Les tests de confirmation sont necessaires mais il serait aussi judicieux d\'effectuer des tests de regression ensuite.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les tests de regression sont necessaires mais les tests de confirmation le sont aussi pour verifier que les mises a jour sont correctes.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les deux types de tests sont necessaires, mais les tests de confirmation precedent les tests de regression, pas l\'inverse."},

{id:"C-15",exam:"C",lo:"FL-3.1.3",kl:"K2",pts:1,multi:false,chapter:3,
q:"Defauts exemples :\ni. Deux parties de la specification de conception sont en desaccord\nii. Un temps de reponse trop long faisant perdre patience aux utilisateurs\niii. Un chemin dans le code est inatteignable\niv. Une variable declaree mais jamais utilisee\nv. La quantite de memoire necessaire est trop elevee\nLesquels peuvent etre trouves par le test statique (plutot que dynamique) ?",
options:["ii, v","iii, v","i, ii, iv","i, iii, iv"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 L\'association correcte pour le test statique est i (parties du design en desaccord - defaut de specification), iii (chemin inaccessible dans le code - defaut de codage) et iv (variable declaree mais non utilisee - defaut de codage). Les defauts ii et v necessitent l\'execution pour etre detectes (test dynamique).<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Les associations ne sont pas correctes.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les associations ne sont pas correctes.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les associations ne sont pas correctes."},

{id:"C-16",exam:"C",lo:"FL-3.2.1",kl:"K1",pts:1,multi:false,chapter:3,
q:"Lequel des elements suivants est un avantage du feedback precoce et frequent des parties prenantes ?",
options:["Les changements d'exigences sont compris et implementes plus tot","Il s'assure que les parties prenantes metier comprennent les exigences utilisateur","Il permet aux product owners de changer leurs exigences aussi souvent qu'ils veulent","Les utilisateurs sont informes des exigences qui ne seront pas implementees avant la release"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 Obtenir un feedback precoce et frequent des parties prenantes facilite la communication des problemes de qualite, previent les malentendus sur les exigences et garantit que les changements sont compris et implementes plus tot.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Le feedback vient des parties prenantes, donc fournir du feedback ne devrait pas ameliorer leur propre comprehension de leurs exigences.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Le fait que les changements d\'exigences puissent etre compris et implementes plus tot ne signifie pas que des changements illimites sont encourages.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Le feedback vient des parties prenantes et ne couvre pas la communication vers elles. Communiquer les exigences non implementees avant la release ne devrait idealement pas arriver."},

{id:"C-17",exam:"C",lo:"FL-3.2.4",kl:"K2",pts:1,multi:false,chapter:3,
q:"Types de revue :\n1. Revue technique  2. Revue informelle  3. Inspection  4. Walkthrough\nDescriptions :\nA. Consensus, nouvelles idees, motivation des auteurs\nB. Education des reviseurs, consensus, nouvelles idees, detection de defauts\nC. Detection de defauts avec collecte de metriques pour l'amelioration\nD. Detection de defauts sans documentation formelle\nQuelle correspondance est la MEILLEURE ?",
options:["1A, 2B, 3C, 4D","1A, 2D, 3C, 4B","1B, 2C, 3D, 4A","1C, 2D, 3A, 4B"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 L\'association correcte est : 1A (revue technique), 2D (revue informelle), 3C (inspection), 4B (walkthrough). La revue technique vise le consensus, l\'informelle n\'a pas de sortie formelle, l\'inspection collecte des metriques, le walkthrough est mene par l\'auteur.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Les appariements types de revue-descriptions ne sont pas corrects.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les appariements types de revue-descriptions ne sont pas corrects.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les appariements types de revue-descriptions ne sont pas corrects."},

{id:"C-18",exam:"C",lo:"FL-3.2.5",kl:"K1",pts:1,multi:false,chapter:3,
q:"Lequel des elements suivants est un facteur contribuant au succes d'une revue ?",
options:["S'assurer que le management participe comme reviseur","Diviser les grands produits en parties plus petites","Definir l'evaluation des reviseurs comme objectif","Planifier de couvrir un document par revue"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Pour assurer le succes des revues, il est important de decouper le produit de travail en parties suffisamment petites pour etre revues dans un delai raisonnable, evitant ainsi la perte de concentration.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Assurer le soutien du management pour le processus de revue est important, mais cela ne signifie pas qu\'ils devraient participer comme reviewers.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Il est important de definir des objectifs clairs et des criteres de sortie mesurables, SANS evaluer les participants.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Il faut decouper la revue en parties plus petites pour eviter la perte de concentration. Couvrir un document entier par revue n\'est pas recommande."},

{id:"C-19",exam:"C",lo:"FL-4.1.1",kl:"K2",pts:1,multi:false,chapter:4,
q:"Quelle est la PRINCIPALE difference entre les techniques de test boite noire et les techniques basees sur l'experience ?",
options:["L'objet de test","Le niveau de test auquel la technique est utilisee","La base de test","Le SDLC dans lequel la technique peut etre utilisee"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 Les techniques boite noire sont basees sur l\'analyse du comportement specifie sans reference a la structure interne (base de test = specification). Les techniques basees sur l\'experience utilisent les connaissances du testeur et peuvent ne pas utiliser la specification du tout.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Dans la plupart des cas, les techniques boite noire et basees sur l\'experience peuvent etre utilisees pour les memes objets de test.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les deux types de techniques peuvent etre utilises a tous les niveaux de test.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les techniques basees sur l\'experience peuvent detecter des defauts manques par les techniques boite noire et boite blanche. Elles sont complementaires et utilisables dans tous les SDLC."},

{id:"C-20",exam:"C",lo:"FL-4.2.1",kl:"K3",pts:1,multi:false,chapter:4,
q:"Vous testez un validateur de PIN. Un PIN valide a 4 chiffres, pas tous identiques.\nPartitions identifiees :\n- Longueur : correcte (4 chiffres) / incorrecte (autre)\n- Chiffres differents : correct (au moins 2) / incorrect (tous identiques)\nQuel est le MEILLEUR ensemble de donnees de test ?",
options:["12, 1111, 1234, 12345","1, 123, 1111, 1234","11, 12, 1111, 12345","123, 1222, 12345"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 \"12\" couvre \"longueur incorrecte, trop peu de chiffres\", \"1111\" couvre \"longueur correcte\" et \"nombre de chiffres differents incorrect\", \"1234\" couvre \"longueur correcte\" et \"nombre de chiffres differents correct\", \"12345\" couvre \"longueur incorrecte, trop de chiffres\".<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Toutes les partitions sont couvertes mais seulement le cote inferieur de \"longueur incorrecte\" est couvert.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Il n\'y a pas de valeur couvrant le \"PIN correct\".<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Il n\'y a pas de valeur couvrant le \"nombre de chiffres differents\"."},

{id:"C-21",exam:"C",lo:"FL-4.2.2",kl:"K3",pts:1,multi:false,chapter:4,
q:"Regle implementee : IF (value <= 100 OR value >= 200) THEN 'incorrect' ELSE 'OK'\nBVA 2 valeurs. Quel ensemble d'entrees de test atteint la plus grande couverture ?",
options:["100, 150, 200, 201","99, 100, 200, 201","98, 99, 100, 101","101, 150, 199, 200"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Les partitions d\'equivalence sont : {...,99,100}, {101,...,199}, {200,...}. Il y a 4 valeurs limites : 100, 101, 199 et 200. Les valeurs 101, 199 et 200 sont des elements de couverture valides pour la BVA 2 valeurs, soit 75% de couverture.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Seulement 100 et 200 sont des elements de couverture valides, soit 50%.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Seulement 100 et 200 sont des elements de couverture valides, soit 50%.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Seulement 100 et 101 sont des elements de couverture valides, soit 50%."},

{id:"C-22",exam:"C",lo:"FL-4.2.3",kl:"K3",pts:1,multi:false,chapter:4,
scenario:'Systeme d\'analyse des resultats du permis de conduire :<br><br><table class="q-table"><tr><th></th><th>R1</th><th>R2</th><th>R3</th></tr><tr><td>C1: 1er essai ?</td><td>-</td><td>-</td><td>F</td></tr><tr><td>C2: Theorie reussie ?</td><td>V</td><td>F</td><td>-</td></tr><tr><td>C3: Pratique reussie ?</td><td>V</td><td>-</td><td>F</td></tr><tr><th>Actions</th><th></th><th></th><th></th></tr><tr><td>Delivrer le permis</td><td>X</td><td></td><td></td></tr><tr><td>Lecons supplementaires</td><td></td><td>X</td><td></td></tr><tr><td>Repasser l\'examen</td><td></td><td></td><td>X</td></tr></table>',
q:"Quelles donnees de test montrent des regles contradictoires ?",
options:["C1=Oui, C2=Oui, C3=Echec","C1=Oui, C2=Echec, C3=Reussi","C1=Oui, C2=Oui, C3=Oui et C1=Non, C2=Oui, C3=Oui","C1=Non, C2=Echec, C3=Echec"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 La combinaison (F,F,F) correspond a la fois a R2 et R3, mais R2 et R3 ont des actions differentes, ce qui montre une contradiction entre R2 et R3.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 La combinaison (T,T,F) ne correspond a aucune regle. C\'est un exemple d\'omission, pas de contradiction.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 La combinaison (T,F,T) ne correspond qu\'a une seule colonne R2, donc pas de contradiction.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les combinaisons (T,T,T) et (F,T,T) ne correspondent chacune qu\'a une seule colonne R1, donc pas de contradiction."},

{id:"C-23",exam:"C",lo:"FL-4.2.4",kl:"K3",pts:1,multi:false,chapter:4,
scenario:'<em>Note : cette question fait reference a un diagramme de transition d\'etats du PDF source (Sample Exam C, Q23).</em><br><br>Le diagramme contient plusieurs etats et transitions. Pour trouver le nombre minimum de cas de test, il faut identifier toutes les transitions valides, puis trouver le nombre minimum de chemins partant de l\'etat initial qui couvrent l\'ensemble des transitions.',
q:"Quel est le nombre MINIMUM de cas de test pour atteindre 100% de couverture des transitions valides ?",
options:["3","2","5","6"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 Trois transitions ne peuvent pas apparaitre dans le meme cas de test, donc au minimum 3 cas de test sont requis. Les sequences possibles sont : TC1 (demande-disponible-confirme-paiement-fin), TC2 (demande-pas disponible-liste attente-disponible-confirme-paiement-fin), TC3 (demande-pas disponible-liste attente-annulation-fin).<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Ce n\'est pas le bon nombre minimum.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Ce n\'est pas le bon nombre minimum.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Ce n\'est pas le bon nombre minimum."},

{id:"C-24",exam:"C",lo:"FL-4.3.2",kl:"K2",pts:1,multi:false,chapter:4,
scenario:'<em>Note : cette question fait reference a un graphe de flux de controle du PDF source (Sample Exam C, Q24).</em><br><br>Le graphe contient des noeuds de decision avec des branches. Le nombre d\'elements de couverture pour le test des branches correspond au nombre total de resultats de decision (branches sortantes de chaque noeud de decision).',
q:"Combien d'elements de couverture devez-vous tester ?",
options:["2","4","8","7"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 En test des branches, les elements de couverture sont les branches representees par les aretes du graphe de flux de controle. Il y a 8 aretes dans le graphe.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le nombre d\'elements de couverture ne correspond pas a cette reponse.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Le nombre d\'elements de couverture ne correspond pas a cette reponse.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Le nombre d\'elements de couverture ne correspond pas a cette reponse."},

{id:"C-25",exam:"C",lo:"FL-4.3.3",kl:"K2",pts:1,multi:false,chapter:4,
q:"Comment le test boite blanche peut-il etre utile en support du test boite noire ?",
options:["Les mesures de couverture boite blanche peuvent aider a evaluer les tests boite noire en termes de couverture du code","L'analyse de couverture boite blanche peut aider a identifier les fragments de code inatteignables","Le test de branches subsume les techniques boite noire, donc une couverture complete garantit la couverture de toute technique boite noire","Les techniques boite blanche peuvent fournir des elements de couverture pour les techniques boite noire"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 Effectuer uniquement des tests boite noire ne fournit pas de mesure de la couverture reelle du code. Les mesures de couverture boite blanche fournissent une mesure objective et les informations pour generer des tests supplementaires pour augmenter cette couverture.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Cette affirmation est correcte mais n\'a rien a voir avec les tests boite noire.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 En general, il n\'y a pas de relations entre les techniques boite blanche et boite noire.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les techniques boite blanche sont basees sur l\'objet de test et les techniques boite noire sur la specification. Il n\'y a pas de relation entre leurs elements de couverture."},

{id:"C-26",exam:"C",lo:"FL-4.4.1",kl:"K2",pts:1,multi:false,chapter:4,
q:"Considerez la liste suivante :\n- Entree correcte non acceptee\n- Entree incorrecte acceptee\n- Format de sortie errone\n- Division par zero\nQuelle technique de test est PROBABLEMENT utilisee ?",
options:["Test exploratoire","Attaque de fautes (fault attack)","Test base sur une checklist","Analyse des valeurs limites"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 C\'est une liste de defaillances possibles. Les attaques par defauts sont une approche methodique de la prediction d\'erreurs qui demande au testeur de creer une liste d\'erreurs, defauts et defaillances possibles.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le test exploratoire utilise des chartes de test, pas une liste de defauts/defaillances possibles.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Le testeur utilise une liste pour soutenir ses tests. La prediction d\'erreurs et les tests bases sur checklists utilisent de telles listes, mais ici c\'est une liste de defaillances possibles, pas de conditions de test.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 La BVA est basee sur l\'analyse des valeurs limites des partitions d\'equivalence. La liste ne mentionne pas de partitions."},

{id:"C-27",exam:"C",lo:"FL-4.4.3",kl:"K2",pts:1,multi:false,chapter:4,
q:"Lequel des elements suivants decrit le MIEUX comment le test base sur une checklist peut augmenter la couverture ?",
options:["Les elements de la checklist peuvent etre definis a un niveau suffisamment detaille","Les checklists peuvent etre automatisees pour augmenter la couverture a chaque execution","Chaque element de checklist doit etre teste separement et independamment","Deux testeurs utilisant la meme checklist de haut niveau effectueront le test de manieres legerement differentes"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Si les checklists sont de haut niveau, une variabilite dans les tests reels est probable, ce qui resulte en une couverture potentiellement plus grande mais moins de repetabilite. Deux testeurs suivant la meme checklist de haut niveau utiliseront des donnees et etapes differentes, couvrant des zones differentes.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le fait que le testeur puisse implementer des cas de test detailles n\'explique pas comment cela augmenterait la couverture.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les elements de checklist ne devraient pas etre automatises. Meme s\'ils le sont, les scripts automatises executent toujours les tests de la meme maniere, n\'augmentant pas la couverture.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Tester chaque element separement impacte l\'ordre d\'execution, pas la couverture."},

{id:"C-28",exam:"C",lo:"FL-4.5.2",kl:"K2",pts:1,multi:false,chapter:4,
q:"Lequel des elements suivants fournit le MEILLEUR exemple de critere d'acceptation oriente scenario ?",
options:["L'application doit permettre aux utilisateurs de supprimer leur compte et toutes les donnees associees","Quand un client ajoute un article au panier et procede au paiement, il doit etre invite a se connecter ou creer un compte","IF (contain(product(23).Name, cart.products())) THEN return FALSE","Le site web doit respecter les normes d'accessibilite ICT 508"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Ce critere d\'acceptation decrit un scenario d\'exemple qui doit etre realise par le systeme. C\'est un critere d\'acceptation oriente scenario.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Ce critere decrit les regles ou reglementations que le systeme doit respecter (droit a l\'oubli). C\'est un critere oriente regles.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Cette phrase ressemble plus a une ligne de code implementant une regle metier. Les criteres d\'acceptation doivent etre ecrits dans un langage comprehensible par les representants metier.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Ce critere decrit les regles de conformite du systeme. C\'est un critere oriente regles, pas oriente scenario."},

{id:"C-29",exam:"C",lo:"FL-4.5.3",kl:"K3",pts:1,multi:false,chapter:4,
q:"User story : En tant qu'utilisateur Regular ou Special, je veux utiliser ma carte electronique d'etage pour acceder a des etages specifiques.\nAC1: Regular -> etages 1-3\nAC2: Etage 4 -> Special uniquement\nAC3: Special a les memes droits que Regular\nQuel cas de test est le PLUS raisonnable pour tester AC3 ?",
options:["Verifier qu'un utilisateur Regular peut acceder aux etages 1 et 3","Verifier qu'un utilisateur Regular ne peut pas acceder a l'etage 4","Verifier qu'un utilisateur Special peut acceder a l'etage 5","Verifier qu'un utilisateur Special peut acceder aux etages 1, 2 et 3"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 C\'est la facon de verifier si un utilisateur Special peut acceder aux etages accessibles a un utilisateur Regular.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 On veut verifier les droits d\'acces d\'un utilisateur Special, pas d\'un utilisateur Regular.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 On veut verifier les droits d\'acces d\'un utilisateur Special, pas d\'un utilisateur Regular.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Il n\'y a pas d\'etage 5 dans les criteres d\'acceptation. Les cas de test ne devraient pas etendre la portee de la user story."},

{id:"C-30",exam:"C",lo:"FL-5.1.1",kl:"K2",pts:1,multi:false,chapter:5,
q:"Lequel des elements suivants n'est PAS un objectif d'un plan de test ?",
options:["Definir les donnees de test et les resultats attendus pour les tests de composants","Definir comme critere de sortie '100% de couverture des instructions et des branches'","Decrire les champs du rapport de progression et sa forme","Expliquer pourquoi le test d'integration systeme sera exclu"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 Le plan de test peut inclure des exigences de donnees de test (dans l\'approche de test), mais pas les donnees de test detaillees. Les donnees de test font partie des cas de test, pas du plan de test.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Un des objectifs du plan de test est de garantir que les activites respectent les criteres etablis, incluant les criteres de couverture de code pour le niveau composant.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les templates de documentation sont un contenu typique du plan de test pour standardiser la communication.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Un des objectifs du plan de test est de demontrer l\'adhesion a la politique et strategie de test existantes, ou d\'expliquer les deviations."},

{id:"C-31",exam:"C",lo:"FL-5.1.4",kl:"K3",pts:1,multi:false,chapter:5,
scenario:'Modele d\'extrapolation : E(n) = (3 × A(n-1) + A(n-2)) / 4<br><br>Donnees des iterations precedentes :<br><br><svg viewBox="0 0 420 200" xmlns="http://www.w3.org/2000/svg" style="max-width:420px;font-family:sans-serif;font-size:11px"><rect x="40" y="0" width="370" height="180" fill="#f8fafc" rx="4"/><line x1="60" y1="160" x2="390" y2="160" stroke="#cbd5e1" stroke-width="1"/><text x="35" y="25" text-anchor="end" fill="#64748b" font-size="10">13</text><line x1="40" y1="22" x2="390" y2="22" stroke="#e2e8f0" stroke-width="0.5"/><text x="35" y="55" text-anchor="end" fill="#64748b" font-size="10">10</text><line x1="40" y1="52" x2="390" y2="52" stroke="#e2e8f0" stroke-width="0.5"/><text x="35" y="95" text-anchor="end" fill="#64748b" font-size="10">6</text><line x1="40" y1="92" x2="390" y2="92" stroke="#e2e8f0" stroke-width="0.5"/><text x="35" y="125" text-anchor="end" fill="#64748b" font-size="10">3</text><line x1="40" y1="122" x2="390" y2="122" stroke="#e2e8f0" stroke-width="0.5"/><text x="35" y="163" text-anchor="end" fill="#64748b" font-size="10">0</text><rect x="70" y="52" width="28" height="108" fill="#2563eb" rx="3"/><text x="84" y="47" text-anchor="middle" fill="#2563eb" font-size="10" font-weight="bold">10</text><rect x="102" y="22" width="28" height="138" fill="#94a3b8" rx="3"/><text x="116" y="17" text-anchor="middle" fill="#64748b" font-size="10" font-weight="bold">13</text><text x="98" y="190" text-anchor="middle" fill="#334155" font-weight="bold">It. 1</text><rect x="160" y="22" width="28" height="138" fill="#2563eb" rx="3"/><text x="174" y="17" text-anchor="middle" fill="#2563eb" font-size="10" font-weight="bold">13</text><rect x="192" y="52" width="28" height="108" fill="#94a3b8" rx="3"/><text x="206" y="47" text-anchor="middle" fill="#64748b" font-size="10" font-weight="bold">10</text><text x="188" y="190" text-anchor="middle" fill="#334155" font-weight="bold">It. 2</text><rect x="250" y="72" width="28" height="88" fill="#2563eb" rx="3"/><text x="264" y="67" text-anchor="middle" fill="#2563eb" font-size="10" font-weight="bold">8</text><rect x="282" y="92" width="28" height="68" fill="#94a3b8" rx="3"/><text x="296" y="87" text-anchor="middle" fill="#64748b" font-size="10" font-weight="bold">8</text><text x="278" y="190" text-anchor="middle" fill="#334155" font-weight="bold">It. 3</text><rect x="340" y="82" width="28" height="78" fill="#2563eb" rx="3"/><text x="354" y="77" text-anchor="middle" fill="#2563eb" font-size="10" font-weight="bold">7</text><rect x="372" y="97" width="28" height="63" fill="#94a3b8" rx="3"/><text x="386" y="92" text-anchor="middle" fill="#64748b" font-size="10" font-weight="bold">6</text><text x="368" y="190" text-anchor="middle" fill="#334155" font-weight="bold">It. 4</text><rect x="70" y="0" width="12" height="8" fill="#2563eb" rx="2"/><text x="86" y="7" fill="#334155" font-size="9">Estime (E)</text><rect x="140" y="0" width="12" height="8" fill="#94a3b8" rx="2"/><text x="156" y="7" fill="#334155" font-size="9">Reel (A)</text></svg>',
q:"Quelle est l'estimation pour l'iteration #5 ?",
options:["10.5 jours-personne","8.25 jours-personne","6.5 jours-personne","9.4 jours-personne"],
correct:[0],
justification:"<strong>\u2713 c) Correct</strong> \u2014 D\'apres le graphe : A(4)=6 et A(3)=8. Avec la formule : E(5) = (3*A(4) + A(3)) / 4 = (3*6+8) / 4 = 26/4 = 6,5 jours-personne.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le calcul ne donne pas ce resultat.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Le calcul ne donne pas ce resultat.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Le calcul ne donne pas ce resultat."},

{id:"C-32",exam:"C",lo:"FL-5.1.5",kl:"K3",pts:1,multi:false,chapter:5,
scenario:'Vous preparez un planning d\'execution pour 7 cas de test avec priorites et dependances :<br><br><table class="q-table"><tr><th>Cas de test</th><th>Priorite</th><th>Depend de</th></tr><tr><td>TC1</td><td>2</td><td>-</td></tr><tr><td>TC2</td><td>3</td><td>TC1</td></tr><tr><td>TC3</td><td>2</td><td>-</td></tr><tr><td>TC4</td><td>2</td><td>-</td></tr><tr><td>TC5</td><td>1</td><td>TC4, TC2</td></tr><tr><td>TC6</td><td>3</td><td>-</td></tr><tr><td>TC7</td><td>1</td><td>TC4</td></tr></table><br><em>Priorite 1 = la plus haute, 3 = la plus basse.</em>',
q:"Quel cas de test doit etre execute en sixieme ?",
options:["TC 3","TC 5","TC 6","TC 2"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 En considerant les priorites et dependances : TC4 doit preceder TC7 et TC5. TC1 doit preceder TC2 qui doit preceder TC5. L\'ordre optimal est : TC4-TC7-TC1-TC2-TC5-TC3-TC6. Le sixieme cas de test est TC3.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 L\'ordre ne respecte pas les dependances et priorites.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 L\'ordre ne respecte pas les dependances et priorites.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 L\'ordre ne respecte pas les dependances et priorites."},

{id:"C-33",exam:"C",lo:"FL-5.1.6",kl:"K1",pts:1,multi:false,chapter:5,
q:"Que montre le modele de la pyramide de test ?",
options:["Que les tests peuvent avoir des priorites differentes","Que les tests peuvent avoir des granularites differentes","Que les tests peuvent necessiter des criteres de couverture differents","Que les tests peuvent dependre d'autres tests"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Le modele de la pyramide des tests montre que les differents tests ont differents niveaux de granularite.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le modele de la pyramide ne fournit pas d\'informations sur les priorites de test.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Le modele de la pyramide est independant des criteres de couverture.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Le modele de la pyramide ne montre pas de relations entre les differents tests."},

{id:"C-34",exam:"C",lo:"FL-5.1.7",kl:"K2",pts:1,multi:false,chapter:5,
q:"Quelle est la relation entre les quadrants de test, les niveaux de test et les types de test ?",
options:["Les quadrants representent des combinaisons de niveaux et types de test avec leur position dans le SDLC","Les quadrants decrivent la granularite des types de test a chaque niveau","Les quadrants assignent les types de test aux niveaux de test","Les quadrants regroupent niveaux et types de test par criteres comme les parties prenantes cibles"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Les quadrants de test groupent les niveaux de test, types de test, activites et techniques dans le developpement agile. Les tests peuvent etre orientes metier ou technologie, et supporter l\'equipe ou critiquer le produit. La combinaison determine les 4 quadrants.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Les quadrants ne representent pas des combinaisons de niveaux et types de test et ne sont pas lies a un emplacement dans le SDLC.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les quadrants ne decrivent pas le degre de granularite des types de test a chaque niveau. C\'est le role de la pyramide des tests.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 L\'affirmation est fausse car en general tout type de test peut etre effectue a tout niveau de test."},

{id:"C-35",exam:"C",lo:"FL-5.2.3",kl:"K2",pts:1,multi:false,chapter:5,
q:"Lequel des elements suivants est un exemple de comment l'analyse de risque produit influence la rigueur et la portee des tests ?",
options:["Le suivi continu des risques permet d'identifier un risque emergent le plus tot possible","L'identification des risques permet de mettre en oeuvre des activites d'attenuation","Le niveau de risque evalue aide a selectionner la rigueur des tests","L'analyse de risque permet de deriver des elements de couverture"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 C\'est un exemple de la facon dont l\'analyse des risques influence la minutie et la portee des tests.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le monitoring des risques fait partie du controle des risques, pas de l\'analyse des risques.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 L\'identification des risques seule ne permet pas d\'implementer des activites d\'attenuation. Les actions sont definies lors du controle des risques.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les elements de couverture sont derives a l\'aide de techniques de test, pas par l\'analyse des risques."},

{id:"C-36",exam:"C",lo:"FL-5.3.2",kl:"K2",pts:1,multi:false,chapter:5,
q:"Quelle activite du processus de test utilise le PLUS les rapports de progression de test ?",
options:["Conception de test","Completion de test","Analyse de test","Planification de test"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Un rapport de completion de test est prepare pendant la cloture des tests, quand un projet, niveau de test ou type de test est termine et que les criteres de sortie ont ete atteints. Ce rapport utilise les informations des rapports de progression.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Les rapports de progression de test sont utilises pendant le monitoring et le controle, et la cloture, pas pendant la conception de test.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les rapports de progression sont utilises pendant le monitoring et le controle, pas pendant l\'analyse de test.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les rapports de progression sont utilises pendant le monitoring et le controle, pas pendant la planification de test."},

{id:"C-37",exam:"C",lo:"FL-5.4.1",kl:"K2",pts:1,multi:false,chapter:5,
q:"Lequel des elements suivants n'est PAS un exemple de support de la gestion de configuration aux tests ?",
options:["Tous les commits au referentiel sont identifies et versiones","Tous les changements des elements de l'environnement de test sont suivis","Toutes les specifications d'exigences sont referencees sans ambiguite dans les plans de test","Tous les defauts identifies ont un statut assigne"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 C\'est assure par la gestion des defauts, pas par la gestion de configuration.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Grace a l\'identification unique des commits, la gestion de configuration permet de reassembler les fichiers de la version utilisee et de reproduire la defaillance pour localiser le defaut plus rapidement.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Si un changement d\'environnement de test cause des problemes, la gestion de configuration permet de revenir a une version precedente de l\'environnement.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 La gestion de configuration garantit que toute la documentation identifiee est referencee sans ambiguite dans la documentation de test."},

{id:"C-38",exam:"C",lo:"FL-5.5.1",kl:"K3",pts:1,multi:false,chapter:5,
q:"Rapport de defaut pour une application web d'achat :\nApplication: WebShop v0.99\nDefaut: Bouton de connexion ne fonctionne pas\nEtapes: Lancer le site, cliquer sur connexion\nResultat attendu: Redirection vers la page de connexion\nResultat reel: Le bouton ne repond pas\nSeverite: Haute, Priorite: Urgente\nQuelle information MANQUE le plus ?",
options:["Nom du testeur et date","Elements de l'environnement de test et leurs numeros de version","Identification de l'objet de test","Impact sur les interets des parties prenantes"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 L\'information importante manquante est l\'identification du navigateur et de l\'appareil utilise pour les tests. Un tel defaut peut etre specifique au navigateur ou a l\'appareil, et cette information aide les developpeurs a reproduire le probleme.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 C\'est important mais pas aussi crucial que les elements d\'environnement de test.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 L\'objet de test est identifie (WebShop v0.99).<br><br><strong>\u2717 d) Incorrect</strong> \u2014 L\'impact est inclus - c\'est la severite (haute)."},

{id:"C-39",exam:"C",lo:"FL-6.1.1",kl:"K2",pts:1,multi:false,chapter:6,
q:"Les outils de quelle categorie aident a organiser les cas de test, les defauts detectes et la gestion de configuration ?",
options:["Outils d'execution de test et de couverture","Outils de conception et d'implementation de test","Outils de gestion des defauts","Outils de gestion de test"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Les outils de gestion de test augmentent l\'efficacite du processus en facilitant la gestion du SDLC, des exigences, des tests, des defauts et de la gestion de configuration.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Les outils d\'execution et de couverture facilitent l\'execution automatisee des cas de test et la mesure de couverture, mais n\'aident pas a l\'organisation des defauts et a la gestion de configuration.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les outils de conception et implementation facilitent la generation de cas de test et donnees de test, mais n\'aident pas a l\'organisation des defauts et a la gestion de configuration.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les outils de gestion des defauts gerent les defauts mais ne sont pas des outils de test et ne sont pas utilises pour organiser les cas de test."},

{id:"C-40",exam:"C",lo:"FL-6.2.1",kl:"K1",pts:1,multi:false,chapter:6,
q:"Lequel des elements suivants est le PLUS susceptible d'etre un avantage de l'automatisation des tests ?",
options:["La capacite de generer des cas de test sans acces a la base de test","L'obtention d'une couverture accrue grace a une evaluation plus objective","L'augmentation des temps d'execution avec une puissance de traitement superieure","La prevention des erreurs humaines grace a une plus grande coherence et repetabilite"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 La prevention des erreurs humaines grace a une plus grande coherence et repetabilite est un avantage de l\'automatisation car elle ne souffre pas d\'erreurs humaines. Les tests sont derives de maniere coherente, les donnees creees systematiquement, et les tests executes dans le meme ordre.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 La generation de cas de test sans acces a la base de test n\'est pas possible, que ce soit par des testeurs ou des outils.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 L\'automatisation fournit une evaluation plus objective de la couverture, mais cette evaluation n\'augmente pas directement la couverture. Seule l\'ecriture de tests supplementaires le peut.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 L\'augmentation des temps d\'execution est une affirmation contradictoire car une puissance de traitement superieure reduirait les temps, et des temps plus longs ne sont pas un avantage."},

// ========== EXAM D: Questions 1-40 ==========
{id:"D-1",exam:"D",lo:"FL-1.1.1",kl:"K1",pts:1,multi:false,chapter:1,
q:"Lequel des elements suivants est un objectif de test typique ?",
options:["Trouver et corriger les defauts dans l'objet de test","Maintenir des communications efficaces avec les developpeurs","Valider que les exigences legales ont ete respectees","Renforcer la confiance dans la qualite de l'objet de test"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Construire la confiance dans la qualite de l\'objet de test s\'obtient en executant des tests qui passent.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Trouver et corriger des defauts : identifier les defauts est un objectif du test, mais CORRIGER les defauts n\'est pas une activite de test (c\'est le debogage).<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Maintenir une communication efficace avec les developpeurs est utile mais ce n\'est pas un objectif primaire du test.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Valider que les exigences legales ont ete respectees est incorrect car la validation concerne les besoins des utilisateurs. Verifier les exigences legales est de la verification."},

{id:"D-2",exam:"D",lo:"FL-1.2.3",kl:"K2",pts:1,multi:false,chapter:1,
q:"Un concepteur documente un design d'interface ne prenant pas en compte les utilisateurs handicapes car il est fatigue. Le programmeur implemente le design mais, sous pression, n'inclut pas la gestion des exceptions pour les calculs de bonus.\nLaquelle des affirmations est CORRECTE ?",
options:["Le mauvais calcul des bonus est un defaut qui se produit occasionnellement","L'amende recue est une defaillance","Le programmeur travaillant sous forte pression est une cause racine","Le design de l'interface inclut une erreur du concepteur"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 L\'erreur est commise par le programmeur et causee par une pression temporelle severe, qui est la cause racine du defaut subsequent.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le mauvais calcul des bonus est une defaillance (failure) du systeme, pas un defaut.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Le systeme ne supportant pas correctement les utilisateurs handicapes est une defaillance qui entraine une amende, mais l\'amende elle-meme n\'est pas une defaillance (c\'est le fonctionnement correct du systeme reglementaire).<br><br><strong>\u2717 d) Incorrect</strong> \u2014 La mauvaise conception de l\'interface utilisateur est un defaut de conception cause par l\'erreur du concepteur, pas une erreur du concepteur elle-meme."},

{id:"D-3",exam:"D",lo:"FL-1.3.1",kl:"K2",pts:1,multi:false,chapter:1,
q:"Les conditions de test sont utilisees par les testeurs pour generer des cas de test et executer des tests. Bien que les conditions restent les memes, les cas de test varient a chaque fois. Quel principe de test est adresse ?",
options:["L'usure des tests","L'illusion de l'absence de defauts","Les tests precoces economisent du temps et de l'argent","Les defauts se regroupent"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 Le principe de l\'usure des tests signifie que repeter des tests identiques sur du code inchange a peu de chances de decouvrir de nouveaux defauts. En utilisant des conditions de test pour generer de nouveaux tests a chaque fois, le risque d\'usure est reduit.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Le paradoxe de l\'absence de defauts concerne la validation des besoins utilisateur meme si beaucoup de tests sont passes. L\'utilisation de conditions de test ne traite pas directement ce probleme.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Le principe \"tests precoces\" concerne la correction precoce des defauts, pas la generation de cas de test a partir de conditions de test.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Le principe du regroupement des defauts concerne la distribution des defauts (Pareto). L\'utilisation de conditions de test ne traite pas ce probleme."},

{id:"D-4",exam:"D",lo:"FL-1.4.1",kl:"K2",pts:1,multi:false,chapter:1,
q:"Taches de test :\n1. Deriver des cas de test a partir de conditions\n2. Identifier le testware reutilisable\n3. Organiser les cas de test en procedures\n4. Evaluer la base et l'objet de test\nActivites : A. Analyse  B. Conception  C. Implementation  D. Completion\nQuelle correspondance est la MEILLEURE ?",
options:["1B, 2A, 3D, 4C","1B, 2D, 3C, 4A","1C, 2A, 3B, 4D","1C, 2D, 3A, 4B"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 L\'association correcte est : 1B (conception de test), 2D (cloture de test), 3C (implementation de test), 4A (analyse de test). L\'analyse identifie les conditions de test, la conception cree les cas de test, l\'implementation genere les procedures, la cloture archive le testware.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Les appariements activites-taches ne sont pas corrects.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les appariements activites-taches ne sont pas corrects.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les appariements activites-taches ne sont pas corrects."},

{id:"D-5",exam:"D",lo:"FL-1.4.3",kl:"K2",pts:1,multi:false,chapter:1,
q:"Testware donnes :\ni. Rapport de completion de test\nii. Donnees en base pour entrees et resultats attendus\niii. Liste des elements pour construire l'environnement\niv. Sequences documentees de cas de test dans l'ordre d'execution\nv. Cas de test\nLequel est produit lors de l'implementation de test ?",
options:["ii, iv","iii, v","i, ii, v","i, iii, iv"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 Les elements ii (donnees en base = donnees de test, sortie de l\'implementation) et iv (sequences documentees de cas de test = procedures de test, sortie de l\'implementation) sont produits par l\'implementation de test.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les appariements testware-activites ne sont pas corrects.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les appariements testware-activites ne sont pas corrects.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les appariements testware-activites ne sont pas corrects."},

{id:"D-6",exam:"D",lo:"FL-1.4.5",kl:"K2",pts:1,multi:false,chapter:1,
q:"Lequel des elements suivants est le PLUS susceptible de decrire une tache du role de gestion de test ?",
options:["Evaluer la base de test et l'objet de test","Definir les exigences d'environnement de test","Evaluer la testabilite de l'objet de test","Creer le rapport de completion de test"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Le role de gestion de test implique la planification, le monitoring/controle et la cloture des tests. Creer le rapport de completion de test, qui est le principal produit de la cloture, est probablement une tache du role de gestion de test.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Evaluer la base de test pour les defauts et la testabilite sont des taches de l\'analyse de test, donc du role de test (technique).<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Definir les exigences d\'environnement de test est une tache de la conception de test, donc du role de test.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Evaluer la testabilite de l\'objet de test est une tache de l\'analyse de test, donc du role de test."},

{id:"D-7",exam:"D",lo:"FL-1.5.2",kl:"K1",pts:1,multi:false,chapter:1,
q:"Lequel des elements suivants est un avantage de l'approche equipe entiere ?",
options:["Amelioration de la communication entre les membres de l'equipe","Diminution de la responsabilite individuelle pour la qualite","Deploiement plus rapide des livrables","Reduction de la collaboration avec les utilisateurs metier externes"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 L\'approche equipe entiere favorise une communication et une collaboration robustes entre les membres de l\'equipe.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 L\'approche priorise la responsabilite collective pour la qualite, mais chaque membre individuel est toujours egalement responsable de la qualite.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 L\'approche vise une meilleure qualite des livrables mais ne resulte pas necessairement en un deploiement plus rapide.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Avec l\'approche equipe entiere, les testeurs travaillent avec les representants metier pour creer les tests d\'acceptation. Rien n\'indique que cela reduirait la collaboration avec les utilisateurs metier externes."},

{id:"D-8",exam:"D",lo:"FL-1.5.3",kl:"K2",pts:1,multi:false,chapter:1,
q:"Avantages et inconvenients de l'independance du test :\ni. Les testeurs travaillent dans un lieu different\nii. Les testeurs questionnent les hypotheses des programmeurs\niii. Une dynamique conflictuelle s'est etablie\niv. Les developpeurs sont convaincus que les testeurs sont responsables de la qualite\nv. Les testeurs ont des biais differents de ceux des developpeurs\nLesquels sont des avantages ?",
options:["i, iv","ii, v","i, iii, iv","ii, iii, v"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Les avantages de l\'independance des tests sont ii (les testeurs peuvent contester les hypotheses des parties prenantes grace a leurs parcours et biais differents) et v (les testeurs sont plus susceptibles d\'identifier differents types de defaillances).<br><br><strong>\u2717 a) Incorrect</strong> \u2014 i (isolation) est un inconvenient, iii (isolation menant a une relation adversariale) est un inconvenient, iv (developpeurs moins responsables) est un inconvenient.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les combinaisons proposees ne separent pas correctement les avantages des inconvenients.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les combinaisons proposees ne separent pas correctement les avantages des inconvenients."},

{id:"D-9",exam:"D",lo:"FL-2.1.2",kl:"K1",pts:1,multi:false,chapter:2,
q:"Laquelle des bonnes pratiques de test s'applique a tous les SDLC ?",
options:["Chaque niveau de test a des objectifs specifiques et distincts","L'implementation et l'execution des tests commencent pendant la phase de developpement correspondante","Les testeurs doivent commencer la conception des tests des que les brouillons sont disponibles","Chaque activite de test dynamique a une activite de test statique correspondante"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 Chaque niveau de test a des objectifs specifiques et distincts car un type different d\'objet de test est teste a chaque niveau, et des objectifs qui se chevauchent meneraient a une duplication inutile.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 L\'analyse et la conception de test devraient commencer pendant la phase de developpement correspondante, mais l\'implementation demarre generalement plus tard.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 La conception des tests doit etre basee sur une base de test validee, pas sur un brouillon precoce, sinon l\'effort de test pourrait etre gaspille.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Chaque activite de developpement a une activite de test correspondante, mais la meme symetrie ne s\'applique pas entre test dynamique et test statique."},

{id:"D-10",exam:"D",lo:"FL-2.1.3",kl:"K1",pts:1,multi:false,chapter:2,
q:"Lequel des elements suivants est un exemple d'approche test-first du developpement ?",
options:["Developpement dirige par le comportement (BDD)","Developpement dirige par les niveaux de test","Developpement dirige par les fonctions","Developpement dirige par la performance"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 Le BDD (Behavior-Driven Development) est un exemple bien connu d\'approche test-first du developpement.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Le \"Test Level Driven Development\" n\'est pas un exemple correct d\'approche test-first.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Le \"Function-Driven Development\" n\'est pas un exemple correct d\'approche test-first.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Le \"Performance-Driven Development\" n\'est pas un exemple correct d\'approche test-first."},

{id:"D-11",exam:"D",lo:"FL-2.1.4",kl:"K2",pts:1,multi:false,chapter:2,
q:"Lequel des elements suivants est le PLUS susceptible d'etre un defi lors de l'implementation du DevOps ?",
options:["S'assurer que les caracteristiques de qualite non fonctionnelles ne sont pas negligees","Gerer des environnements de test en changement continu","Le besoin de plus de testeurs manuels experimentes","Mettre en place l'automatisation des tests dans le pipeline de livraison"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 L\'implementation du DevOps peut poser plusieurs risques et defis, incluant la necessite de definir le pipeline de livraison, d\'introduire et maintenir les outils CI/CD, et d\'etablir l\'automatisation des tests.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le DevOps augmente generalement la visibilite des caracteristiques de qualite non fonctionnelles, comme la performance et la fiabilite.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les processus automatises CI/CD utilises dans le DevOps facilitent des environnements de test stables.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les processus automatises CI/CD reduisent generalement le besoin de tests manuels."},

{id:"D-12",exam:"D",lo:"FL-2.1.6",kl:"K2",pts:1,multi:false,chapter:2,
q:"Lequel des elements suivants decrit le MIEUX les retrospectives ?",
options:["Elles permettent d'identifier les membres qui n'ont pas pleinement contribue a la qualite","Elles donnent l'occasion d'identifier les activites reussies pour les retenir lors des ameliorations futures","Elles permettent aux membres de l'equipe d'exprimer leurs preoccupations concernant le management","Elles donnent un forum pour discuter du plan et des decisions techniques de la prochaine iteration"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Pendant la retrospective, le groupe discute des aspects reussis a conserver et des domaines a ameliorer, ainsi que de la maniere de le faire.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Pointer des individus qui n\'auraient pas contribue suffisamment ne contribuera pas a la cohesion d\'equipe et a la collaboration, qui sont des avantages des retrospectives.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les retrospectives ne sont pas une occasion pour critiquer le management et les clients. Les resultats de test sont enregistres et peuvent etre lus par d\'autres parties prenantes.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les retrospectives discutent des problemes de qualite de l\'iteration en cours. Elles ne servent pas a faire des plans ou des decisions techniques pour la prochaine iteration (c\'est fait en planification d\'iteration)."},

{id:"D-13",exam:"D",lo:"FL-2.2.2",kl:"K2",pts:1,multi:false,chapter:2,
q:"Lequel des tests suivants est le PLUS susceptible d'etre effectue dans le cadre du test fonctionnel ?",
options:["Le test verifie que la fonction de tri met les elements en ordre croissant","Le test verifie si la fonction de tri se termine en moins d'une seconde","Le test verifie la facilite de modification de la fonction de tri ascendant en descendant","Le test verifie que la fonction de tri fonctionne correctement sur une architecture 64-bit"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 Verifier que la fonction de tri met les elements en ordre croissant est une evaluation de la correction fonctionnelle, qui fait partie des tests fonctionnels.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Evaluer si la fonction de tri respecte son exigence non fonctionnelle de se terminer en une seconde est un test d\'efficacite de performance (test non fonctionnel).<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Evaluer la facilite de modification de la fonction de tri (ascendant vers descendant) est un test de modifiabilite (maintenabilite), un test non fonctionnel.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Evaluer que la fonction fonctionne correctement sur une architecture 64-bit est un test d\'adaptabilite (portabilite), un test non fonctionnel."},

{id:"D-14",exam:"D",lo:"FL-2.3.1",kl:"K2",pts:1,multi:false,chapter:2,
q:"Lequel des elements suivants est le PLUS susceptible d'etre un declencheur de test de maintenance pour un systeme de change ?",
options:["Les developpeurs ont signale que la modification du systeme etait difficile","L'option de remboursement a ete supprimee car elle ne remboursait pas toujours correctement","L'equipe agile a commence a developper une fonctionnalite de fidelite client","Le support linguistique a ete utilise pour activer les transactions en anglais et en langue locale"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Une modification du systeme (comme une correction ou amelioration) est un declencheur des tests de maintenance. La suppression de l\'option de remboursement etait une correction qui necessiterait des tests de maintenance.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Verifier la facilite de changement du systeme serait un test de maintenabilite, pas un declencheur de test de maintenance.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Developper une nouvelle fonctionnalite necessite des tests de la fonctionnalite et de regression, pas des tests de maintenance.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Reconfigurer le systeme pour supporter une autre langue n\'est pas une modification, un changement d\'environnement, ou un retrait - les trois declencheurs des tests de maintenance."},

{id:"D-15",exam:"D",lo:"FL-3.1.1",kl:"K1",pts:1,multi:false,chapter:3,
q:"Lequel des elements suivants ne peut PAS etre examine par le test statique ?",
options:["Contrat","Plan de test","Code chiffre","Charte de test"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 La plupart des produits de travail peuvent etre examines par le test statique, mais il ne convient pas aux produits trop complexes pour l\'interpretation humaine. Le code chiffre est trop complexe pour les humains et ne sera pas analysable par la plupart des outils.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Un contrat doit etre interpretable par des humains et peut donc etre revu (test statique).<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Un plan de test doit etre interpretable par des humains et peut donc etre revu (test statique).<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Une charte de test doit etre interpretable par des humains et peut donc etre revue (test statique)."},

{id:"D-16",exam:"D",lo:"FL-3.1.2",kl:"K2",pts:1,multi:false,chapter:3,
q:"Laquelle des affirmations suivantes concernant la valeur du test statique est CORRECTE ?",
options:["Les types de defauts trouves par le test statique sont differents de ceux trouves par le test dynamique","Le test dynamique peut detecter les types de defauts trouves par le statique plus quelques autres","Le test dynamique peut identifier certains des defauts trouves par le statique mais pas tous","Le test statique peut identifier les types de defauts trouves par le dynamique plus quelques autres"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 Certains types de defauts ne peuvent etre detectes que par le test statique (code inaccessible, patterns de conception non implementes), d\'autres par les deux (defauts de programmation), et d\'autres uniquement par le test dynamique (problemes de performance, memoire).<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Les relations entre test statique et dynamique ne sont pas correctement decrites.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les relations entre test statique et dynamique ne sont pas correctement decrites.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les relations entre test statique et dynamique ne sont pas correctement decrites."},

{id:"D-17",exam:"D",lo:"FL-3.2.2",kl:"K2",pts:1,multi:false,chapter:3,
q:"Descriptions d'activites de revue :\n1. Les anomalies detectees sont deliberees et des determinations sont prises\n2. Les defauts sont enregistres et les mises a jour necessaires sont adressees\n3. Les reviseurs utilisent des techniques pour identifier les anomalies\n4. L'objectif et le planning de la revue sont etablis\n5. Les participants recoivent l'acces a l'element revise\nQuelle est la sequence CORRECTE ?",
options:["4 - 3 - 5 - 2 - 1","4 - 5 - 3 - 1 - 2","5 - 4 - 1 - 3 - 2","5 - 4 - 3 - 2 - 1"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 La sequence correcte des activites du processus de revue generique est : 4 (Planification) - 5 (Lancement de revue) - 3 (Revue individuelle) - 1 (Communication et analyse) - 2 (Correction et rapport).<br><br><strong>\u2717 a) Incorrect</strong> \u2014 La sequence des activites n\'est pas correcte.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 La sequence des activites n\'est pas correcte.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 La sequence des activites n\'est pas correcte."},

{id:"D-18",exam:"D",lo:"FL-3.2.3",kl:"K1",pts:1,multi:false,chapter:3,
q:"Quel participant au processus de revue est responsable de s'assurer que les reunions se deroulent efficacement et que chacun peut exprimer ses opinions librement ?",
options:["Manager","Moderateur","President","Responsable de revue"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Le moderateur (ou facilitateur) est responsable du bon deroulement des reunions de revue, incluant la gestion du temps, la mediation des discussions et la creation d\'un environnement sur ou chacun peut s\'exprimer librement.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le manager est responsable de decider ce qui doit etre revu et d\'allouer les ressources.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Le \"chairman\" n\'est pas un role reconnu dans les revues.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Le responsable de revue (review leader) est responsable de la supervision du processus de revue, de la selection des membres et de la planification des reunions."},

{id:"D-19",exam:"D",lo:"FL-4.1.1",kl:"K2",pts:1,multi:false,chapter:4,
q:"Vous effectuez des tests systeme d'une application web e-commerce. Exigence :\nREQ 05-017 : Si le cout total depasse 100$, le client recoit 5% de remise sur les achats suivants. Sinon, pas de remise.\nQuelles techniques de test seront les PLUS utiles ?",
options:["Techniques de test boite blanche","Techniques de test boite noire","Techniques de test basees sur l'experience","Techniques de test basees sur les risques"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Le document est une exigence qui specifie le comportement desire. Les techniques boite noire (BVA, table de decision) sont donc les plus adaptees. Le libelle \"depasse 100$\" suggere des limites de partitions importantes a tester.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le document ne fait pas reference a la structure interne, mais specifie le comportement desire. Les techniques boite blanche ne seront pas utiles.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Bien que les techniques basees sur l\'experience puissent etre utilisees, les techniques boite noire sont plus adaptees car le document decrit une regle metier precise.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les techniques de test basees sur les risques ne sont pas un type reconnu de technique de test."},

{id:"D-20",exam:"D",lo:"FL-4.2.1",kl:"K3",pts:1,multi:true,chapter:4,
q:"Systeme de billets de cinema avec remise basee sur D = CY - BY :\nD<0: erreur, 0<=D<18: etudiant, 18<=D<65: pas de remise, D>=65: retraite\nDeux cas de test existants : (BY=1990,CY=2020: pas de remise) et (BY=2030,CY=2029: erreur)\nQuels ensembles de donnees ajouter pour la couverture EP complete ?",
options:["BY=2001, CY=2065","BY=1900, CY=1965","BY=1965, CY=1900","BY=2011, CY=2029","BY=2000, CY=2000"],
correct:[1,4],
justification:"<strong>\u2713 b, e) Correct</strong> \u2014 b) CY-BY = 65 correspond a la partition \"reduction senior\" non encore couverte. e) CY-BY = 0 correspond a la partition \"reduction etudiant\" non encore couverte.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 CY-BY = 64 correspond a la partition \"pas de reduction\" deja couverte.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 CY-BY = -65 correspond a la partition \"message d\'erreur\" deja couverte.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 CY-BY = 18 correspond a la partition \"pas de reduction\" deja couverte."},

{id:"D-21",exam:"D",lo:"FL-4.2.2",kl:"K3",pts:1,multi:false,chapter:4,
q:"Systeme de controle de temperature pour chambre froide horticole. Temperature OK : 0-2 degres inclus. En dessous : 'trop bas', au-dessus : 'trop haut'.\nAvec BVA 2 valeurs, quel ensemble de valeurs fournit la plus haute couverture ?",
options:["-1, 3","0, 2","-1, 0, 2, 3","-2, 0, 2, 4"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 Il y a 3 partitions : {...,-2,-1}, {0,1,2}, {3,4,...}. Pour la BVA 2 valeurs, toutes les valeurs limites doivent etre couvertes : -1, 0, 2 et 3.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 L\'ensemble de valeurs limites ne correspond pas a l\'analyse correcte.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 L\'ensemble de valeurs limites ne correspond pas a l\'analyse correcte.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 L\'ensemble de valeurs limites ne correspond pas a l\'analyse correcte."},

{id:"D-22",exam:"D",lo:"FL-4.2.3",kl:"K3",pts:1,multi:false,chapter:4,
scenario:'Table de decision avec 7 regles :<br><br><table class="q-table"><tr><th>Conditions</th><th>R1</th><th>R2</th><th>R3</th><th>R4</th><th>R5</th><th>R6</th><th>R7</th></tr><tr><td>Age</td><td>0-18</td><td>19-65</td><td>19-65</td><td>&gt;65</td><td>0-18</td><td>19-65</td><td>&gt;65</td></tr><tr><td>Experience (annees)</td><td>-</td><td>0-4</td><td>&gt;4</td><td>-</td><td>-</td><td>-</td><td>-</td></tr><tr><td>Enregistre</td><td>Non</td><td>Non</td><td>Non</td><td>Non</td><td>Oui</td><td>Oui</td><td>Oui</td></tr><tr><th>Categorie</th><th>A</th><th>A</th><th>B</th><th>B</th><th>B</th><th>D</th><th>C</th></tr></table><br>Cas de test existants :<br>TC1: 19 ans, non enregistre, 0 exp → Cat. A<br>TC2: 65 ans, non enregistre, 5 ans → Cat. B<br>TC3: 66 ans, enregistre, 0 exp → Cat. C<br>TC4: 65 ans, enregistre, 4 ans → Cat. D',
q:"Quel cas de test supplementaire augmentera la couverture de la table de decision ?",
options:["66 ans, non enregistre, 0 exp -> B","55 ans, non enregistre, 2 ans exp -> A","19 ans, enregistre, 5 ans exp -> D","Aucun cas de test supplementaire ne peut augmenter la couverture"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 Les conditions \"66 ans\", \"non inscrit\" et \"pas d\'experience\" correspondent a la regle R4, qui n\'est pas couverte par les cas de test existants. Ajouter ce cas de test augmentera la couverture de la table de decision.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les conditions \"55 ans\", \"non inscrit\" et \"2 ans d\'experience\" correspondent a la regle R2, deja couverte par TC1.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les conditions \"19 ans\", \"inscrit\" et \"5 ans d\'experience\" correspondent a la regle R6, deja couverte par TC4.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les cas existants ne couvrent que 4 colonnes sur 7. La couverture PEUT etre augmentee en ajoutant des cas pour R1, R4 et R5."},

{id:"D-23",exam:"D",lo:"FL-4.2.4",kl:"K3",pts:1,multi:false,chapter:4,
q:"Test de transition d'etats du systeme de reservation d'hotel (4 etats, 5 evenements).\nQuel cas de test (sequence d'evenements partant de 'Requesting') atteint la plus haute couverture des transitions valides ?",
options:["NotAvailable, Available, ChangeRoom, NotAvailable, Cancel","Available, ChangeRoom, NotAvailable, Available, Pay","Available, ChangeRoom, Available, ChangeRoom, NotAvailable","NotAvailable, Cancel, ChangeRoom, Available, Pay"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Cette sequence de 5 evenements couvre 5 transitions differentes (le premier \"Available\" correspond a une transition S1-S2, le deuxieme a S3-S2, donc 2 transitions differentes). Ce cas couvre 5 transitions valides sur 7 et atteint la couverture maximale.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Cette sequence couvre 4 transitions differentes sur 7 (les deux \"NotAvailable\" correspondent a la meme transition).<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Cette sequence couvre 3 transitions differentes (les deux \"Available\" et \"ChangeRoom\" correspondent aux memes transitions).<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Cette sequence n\'est pas un cas de test faisable car apres \"Cancel\" le systeme est dans l\'etat final et aucune transition valide ne peut etre executee."},

{id:"D-24",exam:"D",lo:"FL-4.3.1",kl:"K2",pts:1,multi:false,chapter:4,
q:"Votre suite de tests S pour un programme P atteint 100% de couverture des instructions. Elle contient 3 cas de test, chacun atteignant 50%.\nLaquelle des affirmations est CORRECTE ?",
options:["Executer S causera toutes les defaillances possibles dans P","S atteint 100% de couverture des branches pour P","Chaque instruction executable contenant un defaut a ete executee au moins une fois","Apres suppression d'un cas de test, les deux restants atteindront toujours 100%"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 100% de couverture des instructions signifie que chaque instruction executable a ete executee au moins une fois.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Une instruction avec un defaut, lorsqu\'executee, ne cause pas forcement une defaillance. Par exemple, x := y/z ne cause une defaillance que quand z vaut 0.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 100% de couverture des instructions ne garantit pas 100% de couverture des branches. Un IF sans ELSE peut atteindre 100% instructions avec un seul test mais seulement 50% branches.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Le cas de test supprime peut couvrir des instructions non couvertes par les deux autres cas, donc les deux restants n\'atteindraient pas 100%."},

{id:"D-25",exam:"D",lo:"FL-4.3.3",kl:"K2",pts:1,multi:false,chapter:4,
q:"Pourquoi le test boite blanche facilite-t-il la detection de defauts meme quand la specification est vague, obsolete ou incomplete ?",
options:["Les cas de test sont concus sur la base de la structure de l'objet de test plutot que de la specification","Pour chaque technique boite blanche, la couverture est bien definie et facilement mesurable","Les techniques boite blanche sont tres bien concues pour detecter les omissions dans les exigences","Les techniques boite blanche peuvent etre utilisees dans le test statique et dynamique"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 Une force fondamentale des techniques boite blanche est que toute l\'implementation est prise en compte pendant les tests, facilitant la detection de defauts meme quand la specification est vague, obsolete ou incomplete. Cela permet de trouver des fonctionnalites ajoutees accidentellement.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Le fait que la couverture puisse etre definie precisement n\'est pas la bonne raison. Le niveau de couverture atteint a plus d\'impact que la possibilite de la mesurer.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Si le logiciel n\'implemente pas une ou plusieurs exigences, le test boite blanche est peu susceptible de detecter les defauts d\'omission resultants.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 C\'est vrai mais il n\'y a pas de lien entre cette capacite et la detection de defauts avec de mauvaises specifications."},

{id:"D-26",exam:"D",lo:"FL-4.4.1",kl:"K2",pts:1,multi:false,chapter:4,
q:"Lequel des elements suivants n'est PAS anticipe par le testeur lors de l'application de la supposition d'erreurs ?",
options:["Le developpeur a mal compris la formule dans la user story","Le developpeur a ecrit 'FA = A*(1+IR^N)' au lieu de 'FA = A*(1+IR)^N'","Le developpeur a manque le seminaire sur la nouvelle legislation des taux d'interet","La precision du calcul d'interet n'est pas assez precise"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 C\'est un exemple de cause racine potentielle d\'un defaut, qui n\'est ni une erreur, ni un defaut, ni une defaillance, et qui est difficile a anticiper pour le testeur.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 C\'est un exemple d\'anticipation de l\'erreur du developpeur.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 C\'est un exemple d\'anticipation du defaut.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 C\'est un exemple d\'anticipation d\'une defaillance, probablement basee sur l\'experience de systemes anterieurs dans ce domaine."},

{id:"D-27",exam:"D",lo:"FL-4.4.2",kl:"K2",pts:1,multi:false,chapter:4,
q:"Lequel des elements suivants est vrai concernant le test exploratoire ?",
options:["Les cas de test sont concus avant le debut de la session","Le testeur peut executer des tests mais ne peut pas concevoir de tests","Les resultats du test exploratoire sont de bons predicteurs du nombre de defauts restants","Pendant le test exploratoire, le testeur peut utiliser des techniques de test boite noire"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 Pendant le test exploratoire, les testeurs peuvent utiliser toute technique de test qu\'ils trouvent utile.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 En test exploratoire, les cas de test sont generalement crees PENDANT la session, en meme temps que l\'analyse, l\'implementation et l\'execution.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 En test exploratoire, les tests sont simultanement concus, executes et evalues pendant que le testeur apprend l\'objet de test.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les resultats du test exploratoire dependent fortement de l\'experience du testeur et ne constituent pas un bon exemple de modeles fiables de prediction de defauts."},

{id:"D-28",exam:"D",lo:"FL-4.5.1",kl:"K2",pts:1,multi:false,chapter:4,
q:"Quelle pratique collaborative de redaction de user stories permet a l'equipe d'atteindre une comprehension collective de ce qui doit etre livre ?",
options:["Le planning poker pour atteindre un consensus sur l'effort","Les revues pour detecter les incoherences et contradictions","La planification d'iteration pour prioriser les user stories a plus haute valeur metier","La conversation pour que les membres de l'equipe comprennent comment le logiciel sera utilise"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 La Conversation explique comment le logiciel sera utilise et permet souvent a l\'equipe de definir des criteres d\'acceptation significatifs, obtenant ainsi une vision partagee de ce qui doit etre livre.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le Planning Poker peut estimer l\'effort pour une user story deja ecrite mais n\'aide pas a comprendre ce qui doit etre livre.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les revues ne sont pas une pratique d\'ecriture collaborative de user stories.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 La planification d\'iteration est une pratique liee au projet pour planifier le travail, pas pour comprendre ce qui doit etre livre."},

{id:"D-29",exam:"D",lo:"FL-4.5.3",kl:"K3",pts:1,multi:false,chapter:4,
q:"User story : En tant que client, je veux filtrer les resultats par fourchette de prix.\nCriteres d'acceptation :\n1. Le filtre fonctionne a partir de la version 3.0\n2. Le filtre permet de definir un prix min et max\n3. Les resultats se mettent a jour dynamiquement\nPrecondition : 2 produits, A=100$, B=110$\nQuel est le MEILLEUR exemple de cas de test ?",
options:["Definir filtre 90-100$, resultat: produit A. Changer max a 110$, resultat: A et B","Verifier les prix par defaut. Ajouter un produit C a 120$. Verifier que le max par defaut change","Definir filtre 90-115$, changer la devise USD en EUR, verifier la conversion","Tester avec 3 navigateurs differents, verifier le meme affichage"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 Ce cas de test est lie aux criteres d\'acceptation 2 et 3 : on verifie si on peut definir une fourchette de prix (critere 2) et si les resultats se mettent a jour dynamiquement apres ajustement du filtre (critere 3).<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Ce cas de test n\'est lie a aucun critere d\'acceptation. Il verifie si le filtre definit dynamiquement la fourchette de prix par defaut.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Ce cas de test n\'est lie a aucun critere d\'acceptation. Il verifie la fonctionnalite de conversion de devises, non abordee dans cette user story.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Ce cas de test n\'est lie a aucun critere d\'acceptation. Il verifie la compatibilite navigateur, non abordee dans cette user story."},

{id:"D-30",exam:"D",lo:"FL-5.1.3",kl:"K2",pts:1,multi:true,chapter:5,
q:"Lesquels des elements suivants definissent le MIEUX des criteres de SORTIE dans un projet de test ?",
options:["Le budget est approuve","Le budget est epuise","La base de test est disponible","Les cas de test ont atteint au moins 80% de couverture des instructions","Tous les analystes de test sont certifies ISTQB Foundation"],
correct:[1,3],
justification:"<strong>\u2713 b, d) Correct</strong> \u2014 b) Etre a court de budget peut etre vu comme un critere de sortie valide. d) La couverture est une mesure de minutie, c\'est donc un critere de sortie typique.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 L\'approbation du budget est un critere d\'entree. Il n\'aurait pas de sens d\'approuver le budget d\'une activite deja terminee.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 La disponibilite des ressources est un exemple de critere d\'entree pour les tests.<br><br><strong>\u2717 e) Incorrect</strong> \u2014 C\'est un exemple de critere d\'entree verifie avant le debut du projet."},

{id:"D-31",exam:"D",lo:"FL-5.1.4",kl:"K3",pts:1,multi:false,chapter:5,
q:"L'equipe veut estimer le temps pour qu'un testeur execute 4 cas de test.\nMeilleur cas: 1h, Pire cas: 8h, Plus probable: 3h\nAvec l'estimation a 3 points, quelle est l'estimation finale pour les 4 cas ?",
options:["14 heures","3.5 heures","16 heures","12 heures"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 Avec la technique en trois points : E = (a + 4*m + b) / 6 = (1h + 4*3h + 8h) / 6 = 21/6 = 3,5 heures par cas de test. Pour 4 cas de test : 3,5 * 4 = 14 heures.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Le calcul ne donne pas ce resultat.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Le calcul ne donne pas ce resultat.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Le calcul ne donne pas ce resultat."},

{id:"D-32",exam:"D",lo:"FL-5.1.5",kl:"K3",pts:1,multi:false,chapter:5,
scenario:'Matrice de tracabilite des cas de test aux exigences :<br><br><table class="q-table"><tr><th></th><th>Req1</th><th>Req2</th><th>Req3</th><th>Req4</th><th>Req5</th><th>Req6</th><th>Req7</th></tr><tr><td>TC1</td><td>X</td><td></td><td>X</td><td>X</td><td></td><td></td><td>X</td></tr><tr><td>TC2</td><td></td><td>X</td><td>X</td><td></td><td></td><td></td><td></td></tr><tr><td>TC3</td><td></td><td></td><td></td><td></td><td>X</td><td>X</td><td></td></tr><tr><td>TC4</td><td></td><td>X</td><td></td><td></td><td></td><td></td><td></td></tr></table><br>Vous voulez prioriser avec la technique de couverture additionnelle.',
q:"Quel cas de test doit etre execute en DERNIER ?",
options:["TC1","TC2","TC3","TC4"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 TC1 atteint la couverture la plus haute (4/7 exigences), donc execute en premier. Puis TC3 couvre 2 des 3 exigences restantes. Puis TC4 couvre la derniere exigence. TC2 est execute en dernier.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 L\'ordre ne maximise pas la couverture additionnelle a chaque etape.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 L\'ordre ne maximise pas la couverture additionnelle a chaque etape.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 L\'ordre ne maximise pas la couverture additionnelle a chaque etape."},

{id:"D-33",exam:"D",lo:"FL-5.1.7",kl:"K2",pts:1,multi:false,chapter:5,
q:"Comment les quadrants de test peuvent-ils etre benefiques pour le test ?",
options:["Ils aident a planifier en divisant le processus en 4 phases correspondant aux 4 niveaux de test","Ils aident a evaluer la couverture de haut niveau basee sur la couverture de bas niveau","Ils aident les parties prenantes non techniques a comprendre les differents types de test","Ils aident les equipes agiles a developper une strategie de communication"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 Les quadrants de test permettent aux managers et parties prenantes de comprendre les relations entre types de test, les activites supportees (support equipe ou critique produit) et le point de vue (metier ou technologie).<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Les quadrants de test n\'ont rien a voir avec la description des relations entre niveaux de test.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Les quadrants de test ne peuvent pas aider a evaluer un type de couverture.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les quadrants de test ne sont pas un modele psychologique."},

{id:"D-34",exam:"D",lo:"FL-5.2.1",kl:"K1",pts:1,multi:false,chapter:5,
q:"Pour un risque donne, le niveau de risque est de 1000$ et la vraisemblance est estimee a 50%. Quel est l'impact du risque ?",
options:["500$","2 000$","50 000$","200$"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 L\'evaluation des risques peut utiliser une approche quantitative : Niveau de risque = Probabilite * Impact. Donc Impact = Niveau / Probabilite = 1000$ / 50% = 1000$ / 0,5 = 2000$.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Le calcul ne donne pas ce resultat.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Le calcul ne donne pas ce resultat.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Le calcul ne donne pas ce resultat."},

{id:"D-35",exam:"D",lo:"FL-5.2.2",kl:"K2",pts:1,multi:true,chapter:5,
q:"Lesquels des elements suivants sont des risques produit ?",
options:["Derive du perimetre (scope creep)","Architecture mediocre","Reduction des couts","Support d'outils insuffisant","Temps de reponse trop long"],
correct:[1,4],
justification:"<strong>\u2713 b, e) Correct</strong> \u2014 b) Une mauvaise architecture est un risque produit car elle fait reference a une caracteristique du produit. e) Un temps de reponse trop long est un risque produit car il fait reference a une caracteristique du produit.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 La derive du perimetre (scope creep) est un risque projet lie aux problemes techniques.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 La reduction des couts est un risque projet lie aux problemes organisationnels.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Le mauvais support des outils est un risque projet lie aux problemes techniques."},

{id:"D-36",exam:"D",lo:"FL-5.3.2",kl:"K2",pts:1,multi:false,chapter:5,
q:"Lequel des elements suivants n'est PAS un objectif valide d'un rapport de test ?",
options:["Suivre la progression des tests et identifier les domaines necessitant plus d'attention","Fournir des informations sur les tests executes, leurs resultats et les defauts trouves","Fournir des informations sur chaque defaut, comme les etapes de reproduction","Fournir des informations sur les tests prevus pour la prochaine periode"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 Fournir des informations sur les defauts est l\'objectif d\'un rapport de defaut, pas d\'un rapport de test.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Suivre la progression des tests et identifier les domaines necessitant une attention supplementaire est un exemple de support au controle continu des tests, un objectif des rapports de test.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Fournir des informations sur les tests executes, resultats et defauts trouves est un objectif des rapports de test.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Fournir des informations sur les tests prevus pour la prochaine periode est un objectif des rapports de test."},

{id:"D-37",exam:"D",lo:"FL-5.4.1",kl:"K2",pts:1,multi:false,chapter:5,
q:"Un utilisateur a signale une defaillance. L'ingenieur support a demande le numero de version. L'equipe a rassemble tous les fichiers de la release. Le developpeur a pu analyser, trouver le defaut et le corriger.\nQu'est-ce qui a permis cette activite ?",
options:["Gestion des risques","Pilotage et controle des tests","Approche equipe entiere","Gestion de configuration"],
correct:[3],
justification:"<strong>\u2713 d) Correct</strong> \u2014 La gestion de configuration fournit une discipline pour identifier, controler et suivre les produits de travail. Elle permet de revenir a une baseline precedente pour reproduire les resultats de test anterieurs.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 La gestion des risques traite des risques, pas des elements de configuration. Elle ne supporte pas le reassemblage des fichiers d\'une release.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Le monitoring et controle de test concernent la collecte d\'informations et les actions correctives, pas la gestion des elements de configuration.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 L\'approche equipe entiere se concentre sur les questions d\'equipe, pas sur les elements de configuration."},

{id:"D-38",exam:"D",lo:"FL-5.5.1",kl:"K3",pts:1,multi:false,chapter:5,
q:"Rapport de defaut pour un systeme de pret de livres. Le systeme ne registre pas le retour du livre.\nQu'est-ce qui est le PLUS susceptible d'aider le developpeur a reproduire la defaillance rapidement ?",
options:["Ajouter des informations sur quels utilisateurs et quels livres sont affectes","Remplir la valeur manquante de 'Priorite'","Ajouter des dumps memoire et snapshots de base de donnees","Repeter le meme test dans differents environnements"],
correct:[0],
justification:"<strong>\u2713 a) Correct</strong> \u2014 Ajouter cette information permet au developpeur d\'utiliser les memes donnees d\'entree, augmentant la probabilite de reproduire la defaillance rapidement et d\'identifier le defaut plus vite.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Ajouter la valeur de Priorite n\'aidera pas a reproduire le defaut lui-meme.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Ajouter des dumps memoire et snapshots de base de donnees apres chaque etape serait excessif, rendant le rapport moins lisible et rallongeant le processus de reparation.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 La question concerne l\'aide au developpeur pour reproduire la defaillance pour une configuration d\'environnement specifique."},

{id:"D-39",exam:"D",lo:"FL-6.1.1",kl:"K2",pts:1,multi:false,chapter:6,
q:"Categories d'outils :\ni. Outils de collaboration  ii. Outils DevOps  iii. Outils de gestion  iv. Outils de test non fonctionnel  v. Outils de conception et implementation de test\nLesquelles facilitent le PLUS l'execution des tests ?",
options:["i, v","ii, iv","i, iii, v","ii, iii, iv"],
correct:[1],
justification:"<strong>\u2713 b) Correct</strong> \u2014 Les outils DevOps (ii) et les outils de test non fonctionnel (iv) facilitent tous deux l\'execution des tests. Le DevOps via CI/CD et les outils non fonctionnels via l\'execution de tests impossibles manuellement.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 Les combinaisons proposees ne sont pas correctes.<br><br><strong>\u2717 c) Incorrect</strong> \u2014 Les outils de collaboration (i) facilitent la communication, pas l\'execution des tests. Les outils de management (iii) gerent le processus, pas l\'execution.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Les outils de conception/implementation (v) generent le testware mais ne facilitent pas l\'execution des tests."},

{id:"D-40",exam:"D",lo:"FL-6.2.1",kl:"K1",pts:1,multi:false,chapter:6,
q:"Lequel des elements suivants est le PLUS susceptible d'etre un risque de l'automatisation des tests ?",
options:["La detection de defauts supplementaires de haute severite","La fourniture de mesures trop complexes pour les humains","L'incompatibilite avec la plateforme de developpement","La reduction substantielle des temps d'execution des tests"],
correct:[2],
justification:"<strong>\u2713 c) Correct</strong> \u2014 Si l\'automatisation des tests est incompatible avec la plateforme de developpement, elle ne pourra pas s\'integrer et, par exemple, passer les entrees de test a l\'objet de test et recevoir les resultats.<br><br><strong>\u2717 a) Incorrect</strong> \u2014 La detection de defauts supplementaires de haute severite serait un avantage de l\'automatisation, pas un risque.<br><br><strong>\u2717 b) Incorrect</strong> \u2014 Fournir des mesures trop complexes pour etre derivees manuellement est normalement considere comme un avantage de l\'automatisation.<br><br><strong>\u2717 d) Incorrect</strong> \u2014 Des temps d\'execution substantiellement reduits sont normalement consideres comme un avantage de l\'automatisation."}
];

