// ============================================================
// FLASHCARDS DATA (100+ cards)
// ============================================================
const FLASHCARDS = [
// Ch1 - Fondamentaux
{front:"Quel est l'objectif principal du test ?",back:"Reduire le risque de defaillances, evaluer la qualite, detecter les defauts et fournir de l'information aux parties prenantes. CORRIGER n'est PAS un objectif du test.",chapter:1,difficulty:1},
{front:"Quelle est la difference entre Test, QA et Debogage ?",back:"Test = orientee produit (detecter defauts). QA = orientee processus (prevenir defauts). Debogage = trouver et supprimer la cause d'une defaillance (activite du developpeur).",chapter:1,difficulty:2},
{front:"Quelle est la chaine causale complete ?",back:"Cause racine → Erreur (humaine) → Defaut (dans le code/doc) → Defaillance (comportement observe a l'execution).",chapter:1,difficulty:1},
{front:"Principe 1 : Le test montre la presence de defauts...",back:"...pas leur absence. Le test peut montrer qu'il y a des defauts mais ne peut jamais prouver qu'il n'y en a pas.",chapter:1,difficulty:1},
{front:"Principe 2 : Le test exhaustif est impossible",back:"Tester toutes les combinaisons d'entrees est impossible (sauf cas triviaux). On utilise les techniques de test et la priorisation des risques.",chapter:1,difficulty:1},
{front:"Principe 3 : Tester tot...",back:"...economise temps et argent. Les defauts trouves tot dans le SDLC coutent moins cher a corriger (shift-left).",chapter:1,difficulty:1},
{front:"Principe 4 : Regroupement des defauts",back:"Un petit nombre de composants contient la majorite des defauts (principe de Pareto ~80/20).",chapter:1,difficulty:1},
{front:"Principe 5 : Usure des tests (Pesticide paradox)",back:"Repeter les memes tests finit par ne plus trouver de nouveaux defauts. Il faut varier les tests et les donnees.",chapter:1,difficulty:1},
{front:"Principe 6 : Le test depend du contexte",back:"L'approche de test varie selon le contexte : e-commerce, medical, embarque, etc. Il n'y a pas d'approche universelle.",chapter:1,difficulty:1},
{front:"Principe 7 : L'illusion de l'absence de defauts",back:"Un logiciel sans bug peut quand meme ne pas satisfaire les besoins des utilisateurs. 0 defaut ≠ succes.",chapter:1,difficulty:1},
{front:"Quelles sont les 7 activites du processus de test ?",back:"1. Planification 2. Pilotage et controle 3. Analyse 4. Conception 5. Implementation 6. Execution 7. Completion",chapter:1,difficulty:2},
{front:"Que produit l'activite d'Analyse de test ?",back:"Conditions de test priorisees et defauts potentiels dans la base de test. Elle repond a 'quoi tester ?'.",chapter:1,difficulty:2},
{front:"Que produit l'activite de Conception de test ?",back:"Cas de test, chartes de test exploratoire, donnees de test identifiees, couverture de test.",chapter:1,difficulty:2},
{front:"Quelle est la difference entre testeur et gestionnaire de test ?",back:"Testeur : analyse, conçoit, implemente, execute les tests. Gestionnaire : planifie, coordonne la strategie, rapporte, decide de la sortie.",chapter:1,difficulty:2},
{front:"Qu'est-ce que l'approche 'equipe entiere' (whole team) ?",back:"Tout membre de l'equipe peut effectuer des taches liees au test. La qualite est la responsabilite de TOUTE l'equipe. Le testeur aide les representants metier a creer des tests d'acceptation.",chapter:1,difficulty:2},
{front:"Quels sont les avantages de l'independance du test ?",back:"Les testeurs independants trouvent des defauts differents (biais cognitifs differents), peuvent remettre en question les hypotheses du developpeur.",chapter:1,difficulty:2},
{front:"Quels sont les inconvenients de l'independance du test ?",back:"Isolation de l'equipe de dev, consideres comme goulot d'etranglement, perte du sens de responsabilite qualite chez les developpeurs.",chapter:1,difficulty:2},
{front:"Qu'est-ce que la tracabilite et a quoi sert-elle ?",back:"Lien entre base de test, cas de test et resultats. Sert a : evaluer la couverture, l'analyse d'impact des changements (tests de regression), la conformite aux audits.",chapter:1,difficulty:2},
// Ch2 - SDLC
{front:"Quelles bonnes pratiques s'appliquent a TOUS les modeles SDLC ?",back:"1. Chaque activite dev a une activite test correspondante. 2. Chaque niveau de test a des objectifs specifiques. 3. Analyse/conception des tests pendant l'activite dev correspondante. 4. Testeurs impliques des la definition des exigences.",chapter:2,difficulty:2},
{front:"Quelle est la difference entre TDD, ATDD et BDD ?",back:"TDD : tests unitaires AVANT le code (dev). ATDD : tests d'acceptation AVANT le dev (equipe). BDD : tests en langage naturel Given/When/Then, centre sur le comportement (equipe).",chapter:2,difficulty:3},
{front:"Qu'est-ce que l'approche shift-left ?",back:"Tester le plus tot possible : reviser exigences, ecrire tests avant code (TDD), analyse statique avant dynamique, tests de performance au niveau composant.",chapter:2,difficulty:2},
{front:"Qu'est-ce qui n'est PAS un exemple de shift-left ?",back:"Ecrire un script de test avant de mettre en place la gestion de configuration. C'est juste mal organise, pas shift-left.",chapter:2,difficulty:3},
{front:"A quoi servent les retrospectives ?",back:"Discuter de ce qui a bien fonctionne, ce qui peut etre ameliore, et definir des actions d'amelioration continue. PAS pour trouver des defauts ni evaluer les individus.",chapter:2,difficulty:2},
{front:"Quels sont les 5 niveaux de test ?",back:"1. Composant (unitaire) 2. Integration de composants 3. Systeme 4. Integration systeme 5. Acceptation",chapter:2,difficulty:1},
{front:"Que teste le test de composant ?",back:"Code, modules, classes. Base: conception detaillee, code. Defauts typiques: logique incorrecte, calculs errones, chemins manquants.",chapter:2,difficulty:2},
{front:"Que teste le test d'integration de composants ?",back:"Interfaces et interactions entre composants. Base: conception, API. Defauts typiques: donnees incorrectes entre composants.",chapter:2,difficulty:2},
{front:"Que teste le test systeme ?",back:"Systeme complet, workflow bout en bout. Base: exigences, cas d'utilisation. Defauts typiques: comportement fonctionnel/non-fonctionnel inattendu.",chapter:2,difficulty:2},
{front:"Que teste le test d'acceptation ?",back:"Systeme du point de vue metier. Base: processus metier, reglementations. Defauts typiques: workflows mal implementes, regles metier non respectees.",chapter:2,difficulty:2},
{front:"Quelle est la difference entre test fonctionnel et non-fonctionnel ?",back:"Fonctionnel = QUE fait le systeme (completude, exactitude). Non-fonctionnel = COMMENT il le fait (performance, securite, utilisabilite, fiabilite).",chapter:2,difficulty:1},
{front:"Quelle est la difference entre confirmation et regression ?",back:"Confirmation = re-tester un defaut corrige. Regression = verifier qu'un changement n'a pas casse ce qui marchait avant.",chapter:2,difficulty:2},
{front:"Quels sont les 3 declencheurs du test de maintenance ?",back:"1. Modification (corrections, ameliorations). 2. Changement d'environnement (migration). 3. Retrait du systeme (retirement).",chapter:2,difficulty:2},
{front:"Quels sont les avantages du DevOps pour le test ?",back:"Release plus rapide, disponibilite constante de logiciel executable, feedback rapide. PAS : reduction des tests de regression ni mise en place peu couteuse.",chapter:2,difficulty:2},
// Ch3 - Test statique
{front:"Que peut-on examiner par test statique ?",back:"Exigences, user stories, code source, plans de test, documents de conception, contrats. PAS le code compile/encrypte ni le code executable tiers.",chapter:3,difficulty:1},
{front:"Quels defauts sont trouves UNIQUEMENT par test statique ?",back:"Ecarts par rapport aux standards de codage, defauts dans les exigences (ambiguites, contradictions), defauts de conception, manque de couverture securite.",chapter:3,difficulty:2},
{front:"Quelles sont les 5 etapes du processus de revue (dans l'ordre) ?",back:"1. Planification → 2. Initiation de la revue → 3. Revue individuelle → 4. Communication et analyse → 5. Correction et rapport",chapter:3,difficulty:2},
{front:"Quel est le role du Manager dans une revue ?",back:"Decide ce qui doit etre revise, alloue les ressources, le temps et le budget.",chapter:3,difficulty:2},
{front:"Quel est le role de l'Auteur dans une revue ?",back:"Createur du produit d'activite revise. Corrige les defauts trouves lors de la revue.",chapter:3,difficulty:1},
{front:"Quel est le role du Moderateur/Facilitateur dans une revue ?",back:"Assure le bon deroulement des reunions de revue, gestion du temps, mediation entre participants.",chapter:3,difficulty:2},
{front:"Quel est le role du Scribe dans une revue ?",back:"Enregistre les anomalies trouvees, les problemes souleves et les decisions prises.",chapter:3,difficulty:1},
{front:"Qui dirige un walkthrough ?",back:"L'AUTEUR du produit d'activite. C'est une caracteristique distinctive du walkthrough.",chapter:3,difficulty:2},
{front:"Qui dirige une inspection ?",back:"Un facilitateur FORME. L'inspection est le type de revue le plus formel.",chapter:3,difficulty:2},
{front:"Quelle est la difference entre walkthrough et inspection ?",back:"Walkthrough: dirige par l'auteur, objectif = evaluer qualite. Inspection: dirige par facilitateur forme, objectif = max anomalies + metriques, la plus formelle.",chapter:3,difficulty:3},
{front:"Qu'est-ce qu'on trouve lors des revues : defauts ou defaillances ?",back:"Des DEFAUTS (pas des defaillances). Les defaillances n'apparaissent qu'a l'execution du logiciel (test dynamique).",chapter:3,difficulty:2},
{front:"Quels sont les facteurs de succes des revues ?",back:"Objectifs clairs, bon type de revue, temps suffisant pour preparer, soutien du management, culture de revue, pas de blame, diviser les grands documents.",chapter:3,difficulty:2},
// Ch4 - Techniques de test
{front:"Quelle est la difference entre techniques boite noire, boite blanche et basees sur l'experience ?",back:"Boite noire: basee sur les specs/comportement. Boite blanche: basee sur la structure du code. Experience: basee sur la connaissance du testeur.",chapter:4,difficulty:1},
{front:"Qu'est-ce qu'une partition d'equivalence ?",back:"Un groupe de valeurs d'entree pour lesquelles le systeme se comporte de la meme maniere. Chaque valeur appartient a exactement UNE partition.",chapter:4,difficulty:1},
{front:"Comment calcule-t-on la couverture EP ?",back:"Couverture EP = (nombre de partitions testees / nombre total de partitions) x 100%",chapter:4,difficulty:1},
{front:"En BVA 2 valeurs, combien de valeurs teste-t-on par frontiere ?",back:"2 valeurs par frontiere : une de chaque cote de la frontiere. Exemple : frontiere a 18 → tester 17 et 18.",chapter:4,difficulty:2},
{front:"En BVA 3 valeurs, combien de valeurs teste-t-on par frontiere ?",back:"3 valeurs par frontiere : la frontiere elle-meme + 1 de chaque cote. Exemple : frontiere a 18 → tester 17, 18, 19.",chapter:4,difficulty:2},
{front:"Comment calcule-t-on la couverture BVA ?",back:"Couverture BVA = (valeurs limites testees / nombre total de valeurs limites) x 100%",chapter:4,difficulty:2},
{front:"Dans une table de decision, que sont les conditions et les actions ?",back:"Conditions = entrees/situations (lignes du haut). Actions = sorties/resultats attendus (lignes du bas). Chaque colonne = une regle.",chapter:4,difficulty:2},
{front:"Comment calcule-t-on la couverture d'une table de decision ?",back:"Couverture = (nombre de regles testees / nombre total de regles) x 100%",chapter:4,difficulty:1},
{front:"Quels sont les elements d'un diagramme de transition d'etat ?",back:"Etats, transitions (entre etats), evenements (declencheurs), actions (resultats), gardes (conditions supplementaires).",chapter:4,difficulty:2},
{front:"Comment calcule-t-on la couverture des transitions ?",back:"Couverture transitions = (transitions executees / nombre total de transitions VALIDES) x 100%",chapter:4,difficulty:2},
{front:"Qu'est-ce que la couverture des instructions ?",back:"Chaque instruction du code executee au moins une fois. Mesure = instructions executees / total instructions x 100%.",chapter:4,difficulty:1},
{front:"Qu'est-ce que la couverture des branches ?",back:"Chaque branche (vrai ET faux) de chaque decision executee au moins une fois. Mesure = branches executees / total branches x 100%.",chapter:4,difficulty:1},
{front:"100% couverture instructions implique-t-il 100% couverture branches ?",back:"NON ! 100% instructions ne garantit PAS 100% branches. Une branche 'else' vide peut ne pas etre testee. En revanche, 100% branches → 100% instructions.",chapter:4,difficulty:3},
{front:"Qu'est-ce que le error guessing (supposition d'erreurs) ?",back:"Le testeur utilise son experience pour anticiper les erreurs, defauts et defaillances. Base sur les defauts passes et erreurs typiques des developpeurs.",chapter:4,difficulty:1},
{front:"Le error guessing anticipe-t-il les causes racines ?",back:"NON ! Le error guessing anticipe les erreurs, defauts et defaillances, mais PAS les causes racines.",chapter:4,difficulty:3},
{front:"Qu'est-ce que le test exploratoire ?",back:"Conception, execution et evaluation des tests sont simultanees. Utilise des chartes de test. Ideal quand les specs sont limitees ou le temps est court.",chapter:4,difficulty:2},
{front:"Le test exploratoire permet-il de predire le nombre de defauts restants ?",back:"NON ! Le test exploratoire ne fournit pas de metriques de couverture formelles et ne permet pas de prediction fiable du nombre de defauts restants.",chapter:4,difficulty:3},
{front:"Qu'est-ce que le test base sur des checklists ?",back:"Le testeur utilise une liste de conditions a verifier systematiquement. Construite a partir de l'experience, standards ou defauts connus. Couverture peut etre imprecise.",chapter:4,difficulty:1},
{front:"Que signifie 'Card, Conversation, Confirmation' pour les user stories ?",back:"Card = support decrivant la story. Conversation = echanges pour clarifier les details. Confirmation = criteres d'acceptation pour valider la completion.",chapter:4,difficulty:2},
{front:"Que signifie INVEST pour les user stories ?",back:"Independent, Negotiable, Valuable, Estimable, Small, Testable.",chapter:4,difficulty:2},
{front:"Quel est le format standard des criteres d'acceptation ?",back:"Given [contexte initial], When [action], Then [resultat attendu].",chapter:4,difficulty:1},
{front:"Quelle faiblesse a le test boite blanche ?",back:"Il ne peut PAS identifier les exigences non implementees (code manquant) car il se base uniquement sur la structure du code existant.",chapter:4,difficulty:3},
{front:"Combien de regles dans une table de decision avec n conditions booleennes ?",back:"2^n regles au maximum. Exemple : 3 conditions → 2^3 = 8 regles theoriques.",chapter:4,difficulty:2},
// Ch5 - Gestion des tests
{front:"Que contient un plan de test ?",back:"Contexte du test, approche de test, communication, registre des risques, calendrier, budget, ressources.",chapter:5,difficulty:2},
{front:"Quelle est la difference entre criteres d'entree et criteres de sortie ?",back:"Entree = conditions AVANT de commencer (env. dispo, code testable). Sortie = conditions pour TERMINER (couverture atteinte, densite defauts acceptable).",chapter:5,difficulty:1},
{front:"Quelle est la formule d'estimation a 3 points ?",back:"E = (a + 4m + b) / 6, ou a = optimiste, m = plus probable, b = pessimiste.",chapter:5,difficulty:2},
{front:"Qu'est-ce que le planning poker ?",back:"Technique d'estimation par consensus. Chaque membre estime independamment avec des cartes, puis discussion jusqu'au consensus.",chapter:5,difficulty:1},
{front:"Quelles sont les 3 strategies de priorisation des cas de test ?",back:"1. Basee sur le risque (haut risque d'abord). 2. Couverture additionnelle (max de couverture). 3. Basee sur les exigences (importance metier).",chapter:5,difficulty:2},
{front:"Qu'est-ce que la pyramide de test ?",back:"Base (beaucoup) : tests unitaires. Milieu : tests d'integration. Sommet (peu) : tests UI/E2E. Plus on monte, plus c'est couteux et lent.",chapter:5,difficulty:1},
{front:"Que montrent les quadrants de test agile ?",back:"La relation entre types de test et leur objectif : Q1 (tech, support equipe), Q2 (metier, support equipe), Q3 (metier, critique produit), Q4 (tech, critique produit).",chapter:5,difficulty:2},
{front:"Comment calculer le niveau de risque ?",back:"Risque = Probabilite x Impact. Plus le produit est eleve, plus le risque est important.",chapter:5,difficulty:1},
{front:"Quelle est la difference entre risque produit et risque projet ?",back:"Risque produit = qualite du logiciel (fonctionnalites incorrectes, securite). Risque projet = gestion (retard, budget, ressources, communication).",chapter:5,difficulty:2},
{front:"Donnez 3 exemples de risques produit.",back:"Performance insuffisante, problemes de securite, calculs incorrects, mauvaise utilisabilite, fiabilite insuffisante.",chapter:5,difficulty:2},
{front:"Donnez 3 exemples de risques projet.",back:"Retard calendrier, depassement budget, manque de ressources/competences, turnover equipe, problemes de communication.",chapter:5,difficulty:2},
{front:"Que contient un rapport de defaut ?",back:"ID, titre, date, auteur, element de test + environnement, etapes de reproduction, resultat attendu vs reel, severite, priorite, statut, references.",chapter:5,difficulty:2},
{front:"Quelle est la difference entre rapport d'avancement et rapport de completion ?",back:"Avancement = pendant les tests (statut vs plan, bloqueurs). Completion = a la fin (resume, deviations, lecons apprises, risques residuels, recommandations).",chapter:5,difficulty:2},
{front:"Qu'est-ce que la gestion de configuration ?",back:"Identification, controle de version et suivi de tous les produits d'activite de test. Permet de reproduire des etats anterieurs et maintenir la tracabilite.",chapter:5,difficulty:2},
{front:"Qu'est-ce qu'un burndown chart ?",back:"Representation graphique du travail restant en fonction du temps. Utilise en Agile pour montrer l'avancement d'une iteration.",chapter:5,difficulty:1},
{front:"En Agile, comment s'appellent les criteres d'entree et de sortie ?",back:"Criteres d'entree = Definition of Ready. Criteres de sortie = Definition of Done.",chapter:5,difficulty:2},
{front:"A quel quadrant de test appartient le test d'utilisabilite ?",back:"Q3 : Metier, Critique produit. Avec les tests exploratoires et les tests alpha/beta.",chapter:5,difficulty:3},
{front:"A quel quadrant de test appartient le test de composant ?",back:"Q1 : Technologie, Soutien equipe. Avec les tests unitaires.",chapter:5,difficulty:2},
// Ch6 - Outils
{front:"Quelles sont les categories d'outils de test ?",back:"Gestion, test statique, conception/implementation, execution/couverture, non-fonctionnel, DevOps/CI-CD, collaboration.",chapter:6,difficulty:2},
{front:"Quels sont les avantages de l'automatisation des tests ?",back:"Execution plus rapide, plus grande couverture, moins d'erreurs humaines, metriques objectives, feedback rapide, regression acceleree.",chapter:6,difficulty:1},
{front:"Quels sont les risques de l'automatisation des tests ?",back:"Attentes irrealistes, sous-estimation maintenance scripts, incompatibilite plateformes, faux sentiment de securite, competences requises, vendor lock-in.",chapter:6,difficulty:2},
{front:"Quels outils facilitent l'execution des tests ?",back:"Les outils DevOps/CI-CD et les outils de test non-fonctionnel (performance, securite).",chapter:6,difficulty:2},
// Additional cards for exam traps
{front:"Verification vs Validation : quelle difference ?",back:"Verification = le produit est-il construit correctement ? (conforme aux specs). Validation = le bon produit est-il construit ? (repond aux besoins utilisateur).",chapter:1,difficulty:2},
{front:"Un defaut entraine-t-il toujours une defaillance ?",back:"NON. Un defaut peut ne jamais etre execute, ou etre compense par un autre defaut. Une defaillance peut aussi venir de l'environnement.",chapter:1,difficulty:3},
{front:"La QA et le test sont-ils la meme chose ?",back:"NON. La QA est orientee processus (prevenir defauts). Le test est orientee produit (detecter defauts). Ce sont des activites complementaires.",chapter:1,difficulty:2},
{front:"Que se passe-t-il si on atteint 100% couverture branches ?",back:"On a automatiquement 100% couverture instructions. Mais l'inverse n'est PAS vrai : 100% instructions ne garantit PAS 100% branches.",chapter:4,difficulty:3},
{front:"Quelle est la relation entre couverture branches et couverture decisions ?",back:"100% couverture branches = 100% couverture decisions. Chaque resultat de decision correspond a une branche conditionnelle.",chapter:4,difficulty:3},
{front:"Que signifie 'les tests s'usent' (pesticide paradox) en pratique ?",back:"Il faut regulierement mettre a jour les cas de test, ajouter de nouveaux tests, modifier les donnees de test. Sinon, les memes tests ne trouvent plus rien.",chapter:1,difficulty:2},
{front:"Le test exploratoire peut-il utiliser des techniques boite noire ?",back:"OUI. Pendant l'exploration, le testeur peut appliquer des techniques comme EP, BVA, etc. Le test exploratoire est un cadre, pas une technique exclusive.",chapter:4,difficulty:3},
{front:"Qu'est-ce qu'une charte de test exploratoire ?",back:"Document definissant une session de test : ce qu'il faut explorer, avec quelles donnees, et quoi decouvrir. Produit de l'activite de conception de test.",chapter:4,difficulty:2},
{front:"Quand utiliser le test exploratoire ?",back:"Quand les specifications sont limitees, le temps est court, en complement d'autres techniques, pour explorer des zones non couvertes par les tests scriptes.",chapter:4,difficulty:2},
{front:"Quelle est l'estimation a 3 points pour a=2, m=11, b=14 ?",back:"E = (2 + 4x11 + 14) / 6 = (2 + 44 + 14) / 6 = 60/6 = 10 heures-personne.",chapter:5,difficulty:2},
{front:"En BVA 2 valeurs, pour un champ 1-99, quelles sont les valeurs limites ?",back:"Frontieres a 1 et 99. Valeurs : 0, 1, 99, 100. Total = 4 valeurs limites.",chapter:4,difficulty:2},
{front:"En BVA 3 valeurs, pour un champ 1-99, quelles sont les valeurs limites ?",back:"Frontieres a 1 et 99. Valeurs : 0, 1, 2, 98, 99, 100. Total = 6 valeurs limites.",chapter:4,difficulty:2},
{front:"Qu'est-ce que l'ATDD ?",back:"Acceptance Test-Driven Development : les tests d'acceptation sont crees a partir des criteres d'acceptation AVANT le developpement. Ils guident le dev.",chapter:2,difficulty:2},
{front:"Qu'est-ce que le BDD ?",back:"Behavior-Driven Development : tests exprimes en langage naturel (Given/When/Then). Centre sur le comportement souhaite, facilite la comprehension.",chapter:2,difficulty:2},
{front:"Qu'est-ce que le TDD ?",back:"Test-Driven Development : ecrire un test unitaire AVANT le code. Cycle : Red (test echoue) → Green (code minimal) → Refactor (ameliorer le code).",chapter:2,difficulty:2},
{front:"Quel est l'objectif principal d'une inspection ?",back:"Detecter le maximum d'anomalies, evaluer la qualite, collecter des metriques, et ameliorer le processus de revue.",chapter:3,difficulty:2},
{front:"Quel est l'objectif principal d'un walkthrough ?",back:"Evaluer la qualite du produit et trouver des anomalies. Dirige par l'AUTEUR.",chapter:3,difficulty:2},
{front:"Qu'est-ce que le feedback precoce ?",back:"Obtenir des retours tot dans le SDLC. Benefices : eviter les malentendus sur les exigences, reduire le cout de correction, ameliorer la communication.",chapter:3,difficulty:1},
{front:"Quels sont les 6 roles possibles dans une revue ?",back:"Manager, auteur, moderateur/facilitateur, review leader, reviseur, scribe.",chapter:3,difficulty:2},
{front:"Quelle est la difference entre severite et priorite d'un defaut ?",back:"Severite = impact technique du defaut. Priorite = urgence de la correction. Un defaut peut etre severe mais de faible priorite (et inversement).",chapter:5,difficulty:2},
{front:"Qu'est-ce que l'analyse d'impact ?",back:"Evaluer l'effet d'un changement sur le systeme et les tests existants. Aide a selectionner les cas de test de regression.",chapter:1,difficulty:2},
{front:"Que teste-t-on au niveau integration systeme ?",back:"Interactions entre systemes, APIs externes. Defauts typiques : formats de message incorrects, incompatibilites entre systemes.",chapter:2,difficulty:2},
{front:"En Agile, qu'est-ce que la Definition of Ready ?",back:"Criteres d'entree : conditions a remplir AVANT de commencer le travail sur une user story (ex: story claire, criteres d'acceptation definis).",chapter:5,difficulty:2},
{front:"En Agile, qu'est-ce que la Definition of Done ?",back:"Criteres de sortie : conditions a remplir pour considerer une user story TERMINEE (ex: tests passes, code revise, deploye en staging).",chapter:5,difficulty:2},
];

